/* Past-year questions for Rank mode · JEE Mains · Work, Energy and Power, grouped by topic and sub-topic.
   Sources: JEE Main (2019-2025), JEE Advanced and IIT-JEE, AIEEE. Wording as in the paper; solutions written for this site.
   MCQ: o + c (index or array of indices). Numerical: n. Multi-part: a. s = worked solution. y = exam and year. fig = diagram (PhysicaFig spec). */
window.PhysicaRankPyqWep=[
{"y":"JEE Main 2025 · 4 Apr · Shift 2","tp":"pww","st":"Work by a constant force","q":"A block of mass 25 kg is pulled along a horizontal surface by a force at an angle 45° with the horizontal. The friction coefficient between the block and the surface is 0.25. The block travels at a uniform velocity. The workdone by the applied force during a displacement of 5 m of the block is","o":["970 J","490 J","245 J","735 J"],"c":2,"s":"Uniform velocity, so net force is zero. Take g = 9.8 m/s².\nHorizontal: F cos45° = μN. Vertical: N = mg − F sin45°.\nSo F cos45° = μ(mg − F sin45°), which gives F cos45° (1 + μ) = μmg (since sin45° = cos45°).\nF cos45° = 0.25 × 25 × 9.8 / 1.25 = 49 N.\nWork = (F cos45°) × d = 49 × 5 = 245 J."},
{"y":"JEE Main 2025 · 22 Jan · Shift 2","tp":"pww","st":"Work by a constant force","q":"A force F⃗ = 2î + bĵ + k̂ is applied on a particle and it undergoes a displacement î − 2ĵ − k̂. What will be the value of b, if work done on the particle is zero?","o":["{1;3}","2","0","{1;2}"],"c":3,"s":"Work = F⃗ · d⃗ = 0.\n(2)(1) + (b)(−2) + (1)(−1) = 0.\n2 − 2b − 1 = 0, so 2b = 1.\nb = 1/2."},
{"y":"JEE Main 2025 · 24 Jan · Shift 1","tp":"pww","st":"Work by a variable force","q":"A force F = α + βx² acts on an object in the x-direction. The work done by the force is 5 J when the object is displaced by 1 m. If the constant α = 1 N then β will be","o":["15 N/m²","10 N/m²","8 N/m²","12 N/m²"],"c":3,"s":"Work = ∫F dx from 0 to 1 = ∫(α + βx²)dx.\nW = α(1) + β(1)³/3 = α + β/3.\n5 = 1 + β/3, so β/3 = 4.\nβ = 12 N/m²."},
{"y":"JEE Main 2024 · 29 Jan · Shift 1","tp":"pww","st":"Work by a constant force","q":"A block of mass 100 kg slides over a distance of 10 m on a horizontal surface. If the co-efficient of friction between the surfaces is 0.4, then the work done against friction (in J) is [g = 10 m/s²]","o":["4200","4000","4500","3900"],"c":1,"s":"Friction force f = μmg = 0.4 × 100 × 10 = 400 N (g = 10 m/s²).\nWork done against friction = f × d.\nW = 400 × 10 = 4000 J."},
{"y":"JEE Main 2024 · 30 Jan · Shift 2","tp":"pww","st":"Work by a constant force","q":"A block of mass 1 kg is pushed up a surface inclined to horizontal at an angle of 60° by a force of 10 N parallel to the inclined surface as shown in figure (μ = 0.1). When the block is pushed up by 10 m along inclined surface, the work done against frictional force is [g = 10 m/s²]","fig":{"w":240,"h":170,"alt":"Block M on a 60 degree incline pushed up the slope by a 10 N force, coefficient of friction 0.1","d":[["l",40,150,200,150],["p","M60 20 L60 150 L135 150 Z"],["p","M103.5 95.4 L91.5 74.6 L112.3 62.6 L124.3 83.4 Z","f"],["t",108,81,"M","ms"],["l",121,72,98,32,"a"],["t",126,32,"10 N"],["t",150,100,"μ = 0.1"],["t",142,146,"60°","s"]]},"o":["5√3 J","5 J","5×10³ J","10 J"],"c":1,"s":"Normal force on the incline N = mg cos60° = 1 × 10 × 0.5 = 5 N.\nFriction f = μN = 0.1 × 5 = 0.5 N.\nWork done against friction = f × d = 0.5 × 10 = 5 J."},
{"y":"JEE Main 2023 · 29 Jan · Shift 2","tp":"pww","st":"Work by a constant force","q":"Identify the correct statement from the following:\nA. Work done by a man in lifting a bucket out of a well by means of a rope tied to the bucket is negative.\nB. Work done by gravitational force in lifting a bucket out of a well by a rope tied to the bucket is negative.\nC. Work done by friction on a body sliding down an inclined plane is positive.\nD. Work done by an applied force on a body moving on a rough horizontal plane with uniform velocity is zero.\nE. Work done by the air resistance on an oscillating pendulum is negative.\nChoose the correct answer from the options given below:","o":["B, D and E only","B and E only","B and D only","A and C only"],"c":1,"s":"A: The rope force on the bucket is upward and the bucket moves up, so work is positive. A is false.\nB: Gravity is downward, displacement is upward, so work is negative. B is true.\nC: Friction opposes the sliding, so its work is negative. C is false.\nD: At uniform velocity the applied force equals friction and is not zero, so its work is positive. D is false.\nE: Air resistance opposes motion, so its work is negative. E is true.\nCorrect: B and E only."},
{"y":"JEE Main 2022 · 25 Jul · Shift 1","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"A body of mass 0.5 kg travels on straight line path with velocity v = (3x² + 4) m/s. The net work done by the force during its displacement from x = 0 to x = 2 m is","o":["64 J","60 J","120 J","128 J"],"c":1,"s":"Use the work-energy theorem: W = ½m(v² − u²).\nAt x = 0: v = 4 m/s. At x = 2: v = 3(4) + 4 = 16 m/s.\nW = ½ × 0.5 × (16² − 4²) = 0.25 × (256 − 16) = 0.25 × 240.\nW = 60 J."},
{"y":"JEE Main 2022 · 26 Jun · Shift 2","tp":"pww","st":"Graphs of force and work","q":"Arrange the four graphs in descending order of total work done; where W₁, W₂, W₃ and W₄ are the work done corresponding to figure a, b, c and d respectively.","fig":{"w":340,"h":265,"alt":"Four force versus displacement graphs (a) to (d); (a) a straight line from -F to +F, (b) rises from -F to F then flat, (c) same as b then falls to zero, (d) starts at +F, falls to -F, stays flat then rises","d":[["l",30,93,30,13,"a"],["l",30,55,160,55,"a"],["t",26,27,"F","se"],["t",26,89,"−F","se"],["t",156,67,"x","s"],["l",27,25,33,25],["l",27,85,33,85],["p","M30 85 L120 25","B"],["l",120,25,120,55,"d"],["t",75,68,"x₀","ms"],["t",120,68,"x₁","ms"],["t",90,110,"Figure (a)","ms"],["l",190,93,190,13,"a"],["l",190,55,320,55,"a"],["t",186,27,"F","se"],["t",186,89,"−F","se"],["t",316,67,"x","s"],["l",187,25,193,25],["l",187,85,193,85],["p","M190 85 L250 25 L300 25","B"],["l",250,25,250,55,"d"],["l",300,25,300,55,"d"],["t",220,68,"x₀","ms"],["t",250,68,"x₁","ms"],["t",300,68,"x₂","ms"],["t",250,110,"Figure (b)","ms"],["l",30,223,30,143,"a"],["l",30,185,160,185,"a"],["t",26,157,"F","se"],["t",26,219,"−F","se"],["t",156,197,"x","s"],["l",27,155,33,155],["l",27,215,33,215],["p","M30 215 L90 155 L130 155 L155 185","B"],["l",90,155,90,185,"d"],["l",130,155,130,185,"d"],["t",60,198,"x₀","ms"],["t",90,198,"x₁","ms"],["t",130,198,"x₂","ms"],["t",90,240,"Figure (c)","ms"],["l",190,223,190,143,"a"],["l",190,185,320,185,"a"],["t",186,157,"F","se"],["t",186,219,"−F","se"],["t",316,197,"x","s"],["l",187,155,193,155],["l",187,215,193,215],["p","M190 155 L250 215 L295 215 L295 185 L315 155","B"],["l",250,215,250,185,"d"],["l",315,155,315,185,"d"],["t",220,198,"x₀","ms"],["t",250,198,"x₁","ms"],["t",295,198,"x₂","ms"],["t",315,198,"x₃","ms"],["t",250,240,"Figure (d)","ms"]]},"o":["W₃ > W₂ > W₁ > W₄","W₃ > W₂ > W₄ > W₁","W₂ > W₃ > W₄ > W₁","W₂ > W₃ > W₁ > W₄"],"c":0,"s":"Work done = signed area under the F–x graph.\n(a) The line goes from −F to +F and crosses zero at the middle, so the negative and positive triangles cancel: W₁ = 0.\n(b) Same rising line, so the triangles cancel, and then a flat part at +F adds a positive rectangle: W₂ > 0.\n(c) Same as (b) plus an extra falling triangle of positive area, so W₃ > W₂.\n(d) The force starts positive but the graph has a longer negative flat part, so the net area is negative: W₄ < 0.\nOrder: W₃ > W₂ > W₁ > W₄."},
{"y":"JEE Main 2020 · 4 Sep · Shift 2","tp":"pww","st":"Work by a variable force","q":"A person pushes a box on a rough horizontal platform surface. He applies a force of 200 N over a distance of 15 m. Thereafter, he gets progressively tired and his applied force reduces linearly with distance to 100 N. The total distance through which the box has been moved is 30 m. What is the work done by the person during the total movement of the box?","o":["5250 J","5690 J","2780 J","3280 J"],"c":0,"s":"First 15 m: constant force, W₁ = 200 × 15 = 3000 J.\nNext 15 m: force falls linearly from 200 N to 100 N, so use the average force.\nAverage = (200 + 100)/2 = 150 N, W₂ = 150 × 15 = 2250 J.\nTotal W = 3000 + 2250 = 5250 J."},
{"y":"JEE Main 2020 · 9 Jan · Shift 1","tp":"pww","st":"Work by a variable force","q":"Consider a force F⃗ = −xî + yĵ. The work done by this force in moving a particle from point A(1, 0) to B(0, 1) along the line segment is (all quantities are in SI units)","fig":{"w":240,"h":190,"alt":"Line segment from A(1,0) on the x axis to B(0,1) on the y axis","d":[["l",50,150,210,150,"a"],["l",50,150,50,20,"a"],["l",150,150,50,50,"a"],["t",216,154,"X"],["t",44,16,"Y","e"],["t",56,46,"B (0, 1)"],["t",150,168,"A (1, 0)","m"],["t",42,166,"(0, 0)","e"]]},"o":["{3;2}","2","1","{1;2}"],"c":2,"s":"W = ∫F⃗ · dr⃗ = ∫(−x dx + y dy).\nThe x part goes from x = 1 to 0: ∫(−x)dx = [−x²/2] from 1 to 0 = +½.\nThe y part goes from y = 0 to 1: ∫y dy = [y²/2] = ½.\nW = ½ + ½ = 1 J."},
{"y":"JEE Main 2019 · 9 Apr · Shift 1","tp":"pww","st":"Work by a variable force","q":"A uniform cable of mass 'M' and length 'L' is placed on a horizontal surface such that its (1/n)th part is hanging below the edge of the surface. To lift the hanging part of the cable upto the surface, the work done should be","o":["{MgL;n²}","{MgL;2n²}","nMgL","{2MgL;n²}"],"c":1,"s":"Hanging length = L/n, so hanging mass = M/n.\nIts centre of mass is L/(2n) below the surface.\nWork = (weight of the hanging part) × (rise of its centre of mass).\nW = (M/n) g × L/(2n) = MgL/(2n²)."},
{"y":"JEE Main 2019 · 10 Jan · Shift 1","tp":"pww","st":"Work by a constant force","q":"A block of mass m is kept on a platform which starts from rest with constant acceleration g/2 upwards, as shown in figure. Work done by normal reaction on block in time t is","fig":{"w":300,"h":160,"alt":"Block of mass m on a platform accelerating upward with a = g/2","d":[["r",100,40,60,60],["t",130,76,"m","m"],["r",60,100,140,12,"f"],["l",230,100,230,50,"a"],["t",240,78,"a = g/2"]]},"o":["{mg²t²;8}","0","{3mg²t²;8}","−{mg²t²;8}"],"c":2,"s":"Newton's second law: N − mg = m(g/2), so N = 3mg/2.\nDistance moved in time t from rest: s = ½(g/2)t² = gt²/4.\nThe normal reaction is upward, along the displacement, so its work is positive.\nW = N × s = (3mg/2)(gt²/4) = 3mg²t²/8."},
{"y":"JEE Main 2014","tp":"pww","st":"Work by a variable force","q":"When a rubber-band is stretched a distance x, it exerts a restoring force of magnitude F = ax + bx² where a and b are constants. The work done in stretching the unstretched rubber-band by L is","o":["½({aL²;2} + {bL³;3})","aL² + bL³","½(aL² + bL³)","{aL²;2} + {bL³;3}"],"c":3,"s":"Work done = ∫F dx from 0 to L.\nW = ∫(ax + bx²)dx = a L²/2 + b L³/3.\nThis matches the last option."},
{"y":"JEE Advanced 2013","tp":"pww","st":"Work by a variable force","q":"The work done on a particle of mass m by a force, K[{x;(x²+y²)^(3/2)} î + {y;(x²+y²)^(3/2)} ĵ] (K being a constant of appropriate dimensions), when the particle is taken from the point (a, 0) to the point (0, a) along a circular path of radius a about the origin in the x-y plane is","o":["{2Kπ;a}","{Kπ;a}","{Kπ;2a}","0"],"c":3,"s":"The force is F⃗ = K r⃗ / r³, so it points along the radius (a central force).\nOn a circular path about the origin, each small displacement dr⃗ is along the tangent, perpendicular to r⃗.\nSo F⃗ · dr⃗ = 0 at every point of the path.\nWork done = 0."},
{"y":"AIEEE 2004","tp":"pww","st":"Work by a constant force","q":"A force F⃗ = (5î + 3ĵ + 2k̂) N is applied over a particle which displaces it from its origin to the point r⃗ = (2î − ĵ) m. The work done on the particle in joule is","o":["−7","+7","+10","+13"],"c":1,"s":"W = F⃗ · r⃗ = (5)(2) + (3)(−1) + (2)(0).\nW = 10 − 3 + 0.\nW = +7 J."},
{"y":"AIEEE 2004","tp":"pww","st":"Work by a variable force","q":"A uniform chain of length 2 m is kept on a table such that a length of 60 cm hangs freely from the edge of the table. The total mass of the chain is 4 kg. What is the work done in pulling the entire chain on the table?","o":["7.2 J","3.6 J","120 J","1200 J"],"c":1,"s":"Mass per unit length = 4/2 = 2 kg/m.\nHanging part: mass = 2 × 0.6 = 1.2 kg, and its centre of mass is 0.3 m below the table.\nW = (1.2)(10)(0.3), taking g = 10 m/s².\nW = 3.6 J."},
{"y":"IIT-JEE 2003","tp":"pwe","st":"Conservative forces and potential energy curves","q":"If W₁, W₂ and W₃ represent the work done in moving a particle from A to B along three different paths 1, 2 and 3 respectively (as shown) in the gravitational field of a point mass m, find the correct relation between W₁, W₂ and W₃.","fig":{"w":300,"h":200,"alt":"Three different paths 1, 2 and 3 from A at bottom left to B at top right, near a point mass m","d":[["p","M50 170 Q60 60 250 40"],["p","M50 170 Q130 120 250 40"],["p","M50 170 Q200 160 250 40"],["c",175,70,3,"F"],["t",184,66,"m"],["t",38,110,"1","e"],["t",140,134,"2"],["t",215,140,"3"],["t",40,176,"A","e"],["t",256,40,"B"]]},"o":["W₁ > W₂ > W₃","W₁ = W₂ = W₃","W₁ < W₂ < W₃","W₂ > W₁ > W₃"],"c":1,"s":"The gravitational force is a conservative force.\nThe work done by a conservative force depends only on the starting point A and the end point B, not on the path.\nSo the work along paths 1, 2 and 3 is the same.\nW₁ = W₂ = W₃."},
{"y":"IIT-JEE 1998","tp":"pww","st":"Work by a variable force","q":"A force F⃗ = −K(yî + xĵ) (where K is a positive constant) acts on a particle moving in the xy plane. Starting from the origin, the particle is taken along the positive x-axis to the point (a, 0), and then parallel to the y-axis to the point (a, a). The total work done by the force F on the particle is","o":["−2Ka²","2Ka²","−Ka²","Ka²"],"c":2,"s":"F⃗ · dr⃗ = −K(y dx + x dy).\nPart 1: along the x-axis, y = 0 and dy = 0, so the work is 0.\nPart 2: x = a is constant and dx = 0, so W = −K ∫ a dy from 0 to a = −Ka².\nTotal work = −Ka²."},
{"y":"IIT-JEE 1985","tp":"pww","st":"Work by a variable force","q":"A uniform chain of length L and mass M is lying on a smooth table and one third of its length is hanging vertically down over the edge of the table. If g is acceleration due to gravity, the work required to pull the hanging part on to the table is","o":["MgL","MgL/3","MgL/9","MgL/18"],"c":3,"s":"Hanging length = L/3, so hanging mass = M/3.\nIts centre of mass is L/6 below the table edge.\nW = (M/3) g × (L/6).\nW = MgL/18."},
{"y":"JEE Main 2025 · 23 Jan · Shift 1","tp":"pww","st":"Work by a variable force","q":"A force f⃗ = x²yî + y²ĵ acts on a particle in a plane x + y = 10. The work done by this force during a displacement from (0, 0) to (4 m, 2 m) is ______ Joule (round off to the nearest integer).","n":152,"s":"W = ∫F⃗ · dr⃗ = ∫x²y dx + ∫y² dy.\nUsing the plane x + y = 10, put y = 10 − x in the first integral.\n∫₀⁴ x²(10 − x)dx = 10(64)/3 − 256/4 = 213.33 − 64 = 149.33.\n∫₀² y² dy = 8/3 = 2.67.\nW = 149.33 + 2.67 = 152 J."},
{"y":"JEE Main 2024 · 9 Apr · Shift 2","tp":"pww","st":"Work by a variable force","q":"A force (3x² + 2x − 5) N displaces a body from x = 2 m to x = 4 m. Work done by this force is ______ J.","n":58,"s":"W = ∫F dx from 2 to 4 = [x³ + x² − 5x] from 2 to 4.\nAt x = 4: 64 + 16 − 20 = 60.\nAt x = 2: 8 + 4 − 10 = 2.\nW = 60 − 2 = 58 J."},
{"y":"JEE Main 2023 · 11 Apr · Shift 1","tp":"pww","st":"Work by a variable force","q":"A force F⃗ = (2 + 3x)î acts on a particle in the x direction where F is in newton and x is in meter. The work done by this force during a displacement from x = 0 to x = 4 m, is ______ J.","n":32,"s":"W = ∫(2 + 3x)dx from 0 to 4 = [2x + 3x²/2] from 0 to 4.\n= 2(4) + 3(16)/2 = 8 + 24.\nW = 32 J."},
{"y":"JEE Main 2023 · 15 Apr · Shift 1","tp":"pww","st":"Work by a variable force","q":"A block of mass 10 kg is moving along x-axis under the action of force F = 5x N. The work done by the force in moving the block from x = 2 m to 4 m will be ______ J.","n":30,"s":"W = ∫5x dx from 2 to 4 = [5x²/2] from 2 to 4.\n= (5/2)(16 − 4) = 2.5 × 12.\nW = 30 J."},
{"y":"JEE Main 2023 · 1 Feb · Shift 1","tp":"pww","st":"Work by a constant force","q":"A small particle moves to position 5î − 2ĵ + k̂ from its initial position 2î + 3ĵ − 4k̂ under the action of force F⃗ = (5î + 2ĵ + 7k̂) N. The value of work done will be ______ J.","n":40,"s":"Displacement = final − initial = (5 − 2)î + (−2 − 3)ĵ + (1 + 4)k̂ = 3î − 5ĵ + 5k̂.\nW = F⃗ · d⃗ = (5)(3) + (2)(−5) + (7)(5).\nW = 15 − 10 + 35.\nW = 40 J."},
{"y":"JEE Main 2023 · 1 Feb · Shift 2","tp":"pww","st":"Work by a variable force","q":"A force F = (5 + 3y²) acts on a particle in the y-direction, where F is in newton and y is in meter. The work done by the force during a displacement from y = 2 m to y = 5 m is ______ J.","n":132,"s":"W = ∫(5 + 3y²)dy from 2 to 5 = [5y + y³] from 2 to 5.\nAt y = 5: 25 + 125 = 150.\nAt y = 2: 10 + 8 = 18.\nW = 150 − 18 = 132 J."},
{"y":"JEE Main 2021 · 27 Aug · Shift 1","tp":"pww","st":"Work by a constant force","q":"Two persons A and B perform same amount of work in moving a body through a certain distance d with application of forces acting at angles 45° and 60° with the direction of displacement respectively. The ratio of force applied by person A to the force applied by person B is {1;√x}. The value of x is ______.","n":2,"s":"Work W = F d cosθ is the same for both.\nF_A cos45° = F_B cos60°.\nF_A/F_B = cos60°/cos45° = (1/2)/(1/√2) = 1/√2.\nComparing with 1/√x gives x = 2."},
{"y":"JEE Main 2021 · 25 Jul · Shift 1","tp":"pww","st":"Work by a variable force","q":"A force of F⃗ = (5y + 20)ĵ N acts on a particle. The workdone by this force when the particle is moved from y = 0 to y = 10 m is ______ J.","n":450,"s":"The force acts along y, so W = ∫F dy from 0 to 10.\nW = ∫(5y + 20)dy = [5y²/2 + 20y] from 0 to 10.\n= 5(100)/2 + 200 = 250 + 200.\nW = 450 J."},
{"y":"JEE Main 2020 · 3 Sep · Shift 1","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"A cricket ball of mass 0.15 kg is thrown vertically up by a bowling machine so that it rises to a maximum height of 20 m after leaving the machine. If the part pushing the ball applies a constant force F on the ball and moves a horizontal distance of 0.2 m while launching the ball, the value of F (in N) is ______. (g = 10 m s⁻²)","n":150,"s":"The ball leaves the machine with speed v, and it rises 20 m: ½mv² = mgH = 0.15 × 10 × 20 = 30 J.\nThe push is horizontal, so gravity does no work during it.\nBy the work-energy theorem, F × 0.2 = ½mv² = 30 J.\nF = 30/0.2 = 150 N."},
{"y":"JEE Advanced 2019","tp":"pww","st":"Work by a variable force","q":"A particle is moved along a path AB–BC–CD–DE–EF–FA, as shown in figure, in presence of a force F⃗ = (αyî + 2αxĵ) N, where x and y are in meter and α = −1 N m⁻¹. The work done on the particle by this force F⃗ will be ______ Joule.","fig":{"w":300,"h":240,"alt":"Path A(0,1) to B(1,1) to C(1,0.5) to D(0.5,0.5) to E(0.5,0) to F(0,0) and back to A on the xy plane","d":[["l",50,210,270,210,"a"],["l",50,210,50,20,"a"],["p","M50 50 L210 50 L210 130 L130 130 L130 210 L50 210 Z","B"],["l",130,130,130,210,"d"],["l",50,130,130,130,"d"],["l",210,50,210,210,"d"],["t",56,44,"A","s"],["t",214,44,"B","s"],["t",214,128,"C","s"],["t",122,126,"D","se"],["t",134,204,"E","s"],["t",56,204,"F","s"],["t",44,54,"1.0","se"],["t",44,134,"0.5","se"],["t",130,224,"0.5","ms"],["t",210,224,"1.0","ms"],["t",44,224,"0","se"],["t",276,214,"x"],["t",44,16,"y","e"]]},"n":0.75,"s":"Work on each segment: W = ∫(αy dx + 2αx dy). With α = −1:\nAB (y = 1, x: 0 to 1): −1(1)(1) = −1 J.\nBC (x = 1, y: 1 to 0.5): −2(1)(−0.5) = +1 J.\nCD (y = 0.5, x: 1 to 0.5): −(0.5)(−0.5) = +0.25 J.\nDE (x = 0.5, y: 0.5 to 0): −2(0.5)(−0.5) = +0.5 J.\nEF (y = 0) and FA (x = 0): 0 J.\nTotal W = −1 + 1 + 0.25 + 0.5 = 0.75 J."},
{"y":"IIT-JEE 1980","tp":"pwe","st":"Statements, matching and subjective","q":"In the figures (a) and (b), AC, DG and GF are fixed inclined planes, BC = EF = x and AB = DE = y. Small block of mass M is released from the point A. It slides down AC and reaches C with a speed v_C. The same block is released, from rest, from the point D. It slides down DGF and reaches the point F with speed v_F. The co-efficients of kinetic frictions, between the block and both the surfaces AC and DGF, are μ. Calculate v_C and v_F.","fig":{"w":340,"h":160,"alt":"Two figures: (a) a single incline AC with vertical height AB = y and base BC = x; (b) a two-part incline D to G to F with height DE = y and base EF = x","d":[["p","M40 20 L40 120 L140 120 Z"],["t",34,18,"A","se"],["t",34,128,"B","se"],["t",144,128,"C"],["t",36,72,"y","se"],["t",90,134,"x","ms"],["t",90,152,"(a)","ms"],["p","M200 20 L200 120 L300 120"],["p","M200 20 L238 82 L300 120","B"],["t",194,18,"D","se"],["t",194,128,"E","se"],["t",304,128,"F"],["t",244,80,"G"],["t",196,72,"y","se"],["t",250,134,"x","ms"],["t",250,152,"(b)","ms"]]},"a":"v_C = v_F = √(2(gy − μgx)) = √(2g(y − μx))","s":"On an incline of angle θ and length ℓ, friction does work −μMg cosθ · ℓ.\nBut ℓ cosθ is the horizontal projection of that piece of the path.\nPath AC: the horizontal projection is x, so friction work = −μMgx.\nPath DG + GF: the projections add up to x as well, so friction work = −μMgx.\nWork-energy theorem (gravity does Mgy): ½Mv² = Mgy − μMgx.\nSo v_C = v_F = √(2(gy − μgx))."},
{"y":"IIT-JEE 1980","tp":"pww","st":"Statements, matching and subjective","q":"A body of mass 2 kg is being dragged with a uniform velocity of 2 m/s on a rough horizontal plane. The co-efficient of friction between the body and the surface is 0.20, J = 4.2 joule/calorie and g = 9.8 m/s². Calculate the amount of heat generated in 5 second.","a":"9.33 cal","s":"Uniform velocity, so the pulling force equals friction: f = μmg = 0.20 × 2 × 9.8 = 3.92 N.\nDistance in 5 s = 2 × 5 = 10 m.\nWork done against friction = 3.92 × 10 = 39.2 J, all of it becomes heat.\nHeat = 39.2 J / 4.2 J per cal = 9.33 cal."},
{"y":"IIT-JEE 1980","tp":"pww","st":"Statements, matching and subjective","q":"A pulley arrangement is shown in the figure. The cylinder A has a diameter of 30 cm and the cylinder B has a diameter of 20 cm. The working handle has an arm of 50 cm. The direction of winding of the rope on A is opposite to that on B. Calculate the mechanical advantage of this arrangement.","fig":{"w":320,"h":235,"alt":"Differential pulley: cylinders A (30 cm) and B (20 cm) on one axle with a handle of arm 50 cm; a rope from A and B passes round a movable pulley C that carries the weight W","d":[["l",70,70,250,70],["r",90,40,60,60,"f"],["r",150,50,50,40,"f"],["t",120,32,"A (30 cm)","ms"],["t",175,44,"B (20 cm)","ms"],["l",250,70,250,50],["l",250,70,250,125],["l",250,125,285,125],["t",268,142,"50 cm","ms"],["l",124,100,124,170],["l",156,90,156,170],["p","M124 170 A16 16 0 0 0 156 170"],["c",140,170,16],["l",140,186,140,205],["r",128,205,24,18],["t",140,218,"W","ms"],["t",108,174,"C","e"]]},"a":"Mechanical advantage = 20","s":"Turn the handle once: the handle end moves a distance 2π(50) cm.\nThe rope winds on A by 2π(15) cm and unwinds from B by 2π(10) cm, so the rope loop shortens by 2π(15 − 10) = 2π(5) cm.\nThe loop is shared by the two sides of the movable pulley C, so the load rises by half of this: 2π(2.5) cm.\nMechanical advantage = distance moved by effort / distance moved by load (ideal machine) = 50 / 2.5 = 20."},
{"y":"JEE Main 2025 · 3 Apr · Shift 1","tp":"pwe","st":"Conservation of mechanical energy","q":"A particle is released from height S above the surface of the earth. At certain height its kinetic energy is three times its potential energy. The height from the surface of the earth and the speed of the particle at that instant are respectively.","o":["{S;2}, {3gS;2}","{S;4}, {3gS;2}","{S;4}, √{3gS;2}","{S;2}, √{3gS;2}"],"c":2,"s":"Total energy = mgS (all potential at the start).\nAt the height h: KE = 3 PE, so total = KE + PE = 4 PE = 4mgh.\n4mgh = mgS, so h = S/4.\nKE = 3/4 of the total: ½mv² = (3/4)mgS, so v² = 3gS/2.\nh = S/4 and v = √(3gS/2)."},
{"y":"JEE Main 2025 · 7 Apr · Shift 2","tp":"pwe","st":"Conservative forces and potential energy curves","q":"Which one of the following forces cannot be expressed in terms of potential energy?","o":["Gravitational force","Coulomb's force","Frictional force","Restoring force"],"c":2,"s":"Potential energy exists only for conservative forces, whose work does not depend on the path.\nGravitational, Coulomb and spring (restoring) forces are conservative.\nFriction is non-conservative: its work depends on the path length and it dissipates energy.\nSo friction cannot be expressed in terms of potential energy."},
{"y":"JEE Main 2025 · 8 Apr · Shift 2","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"A body of mass 2 kg moving with velocity of v⃗ᵢₙ = 3î + 4ĵ m s⁻¹ enters into a constant force field of 6 N directed along positive z-axis. If the body remains in the field for a period of {5;3} seconds, then velocity of the body when it emerges from force field is","o":["3î + 4ĵ − 5k̂","4î + 3ĵ + 5k̂","3î + 4ĵ + 5k̂","3î + 4ĵ + √5k̂"],"c":2,"s":"Acceleration a = F/m = 6/2 = 3 m/s² along +z.\nChange in velocity = a t = 3 × 5/3 = 5 m/s along +z.\nThe x and y components do not change (no force along them).\nv⃗ = 3î + 4ĵ + 5k̂ m/s."},
{"y":"JEE Main 2025 · 8 Apr · Shift 2","tp":"pwe","st":"Potential energy and springs","q":"A block of mass 2 kg is attached to one end of a massless spring whose other end is fixed at a wall. The spring-mass system moves on a frictionless horizontal table. The spring's natural length is 2 m and spring constant is 200 N/m. The block is pushed such that the length of the spring becomes 1 m and then released. At distance x m (x < 2) from the wall, the speed of the block will be","o":["10[1 − (2 − x)]^(3/2) m/s","10[1 − (2 − x)²]^(1/2) m/s","10[1 − (2 − x)²]² m/s","10[1 − (2 − x)²] m/s"],"c":1,"s":"Initial compression = 2 − 1 = 1 m, released from rest.\nAt distance x from the wall the compression is (2 − x).\nEnergy conservation: ½k(1)² = ½mv² + ½k(2 − x)².\nv² = (k/m)[1 − (2 − x)²] = 100[1 − (2 − x)²].\nv = 10[1 − (2 − x)²]^(1/2) m/s."},
{"y":"JEE Main 2025 · 22 Jan · Shift 1","tp":"pwv","st":"Vertical circle conditions","q":"A bob of mass m is suspended at a point O by a light string of length l and left to perform vertical motion (circular) as shown in figure. Initially, by applying horizontal velocity v₀ at the point 'A', the string becomes slack when, the bob reaches at the point 'D'. The ratio of the kinetic energy of the bob at the points B and C is","fig":{"w":300,"h":220,"alt":"Vertical circle with centre O, A at the bottom, D at the top, B at 60 degrees from OA and C at 60 degrees from OD, bob given horizontal speed v0 at A","d":[["c",120,110,80],["l",120,30,120,190,"d"],["l",120,110,189,150],["l",120,110,189,70],["t",116,28,"D","e"],["t",116,204,"A","e"],["t",194,160,"B"],["t",194,70,"C"],["t",112,114,"O","e"],["t",128,75,"60°","s"],["t",128,150,"60°","s"],["l",126,190,175,190,"a"],["t",178,194,"v₀"]]},"o":["3","2","1","4"],"c":1,"s":"The string just becomes slack at the top D, so mg = mv_D²/l, giving v_D² = gl and KE at D = ½mgl.\nB is 60° from the bottom, so B is only l(1 − cos60°) = l/2 above A, which means B is 3l/2 below D.\nC is 60° from the top, so C is below D by l − l cos60° = l/2.\nKE_B = ½mgl + mg(3l/2) = 2mgl. KE_C = ½mgl + mg(l/2) = mgl.\nKE_B : KE_C = 2."},
{"y":"JEE Main 2025 · 22 Jan · Shift 2","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"A ball of mass 100 g is projected with velocity 20 m/s at 60° with horizontal. The decrease in kinetic energy of the ball during the motion from point of projection to highest point is","o":["15 J","Zero","5 J","20 J"],"c":0,"s":"Initial KE = ½ × 0.1 × 20² = 20 J.\nAt the highest point only the horizontal velocity remains: 20 cos60° = 10 m/s.\nKE at the top = ½ × 0.1 × 10² = 5 J.\nDecrease = 20 − 5 = 15 J."},
{"y":"JEE Main 2025 · 22 Jan · Shift 2","tp":"pwv","st":"Tension and speed in a circle","q":"A body of mass 100 g is moving in circular path of radius 2 m on vertical plane as shown in figure. The velocity of the body at point A is 10 m/s. The ratio of its kinetic energies at point B and C is\n(Take acceleration due to gravity as 10 m/s²)","fig":{"w":300,"h":210,"alt":"Vertical circle with A at the bottom, B at 30 degrees from OA, and C such that angle BOC is 90 degrees","d":[["c",140,105,75],["l",140,30,140,180,"d"],["l",140,105,177.5,170],["l",140,105,205,67.5],["t",136,28,"D","e"],["t",136,194,"A","e"],["t",182,178,"B"],["t",210,67,"C"],["t",132,109,"O","e"],["t",142,148,"30°","s"],["t",160,112,"90°","s"]]},"o":["{3 − √2;2}","{2 + √2;3}","{2 + √3;3}","{3 + √3;2}"],"c":3,"s":"KE at A = ½ × 0.1 × 10² = 5 J. Radius R = 2 m.\nB is 30° from the bottom: height above A = R(1 − cos30°) = 2 − √3. KE_B = 5 − 0.1×10×(2 − √3) = 3 + √3.\nAngle BOC = 90°, so OC is 120° from the bottom: height above A = R(1 − cos120°) = 3 m. KE_C = 5 − 3 = 2.\nRatio KE_B : KE_C = (3 + √3)/2."},
{"y":"JEE Main 2025 · 23 Jan · Shift 2","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"A ball having kinetic energy KE, is projected at an angle of 60° from the horizontal. What will be the kinetic energy of ball at the highest point of its flight?","o":["{KE;16}","{KE;4}","{KE;2}","{KE;8}"],"c":1,"s":"At the highest point only the horizontal velocity u cos60° remains.\nKE_top = ½m(u cos60°)² = ½mu² × cos²60°.\nKE_top = KE × (1/2)² = KE/4."},
{"y":"JEE Main 2025 · 28 Jan · Shift 1","tp":"pwe","st":"Potential energy and springs","q":"A bead of mass 'm' slides without friction on the wall of a vertical circular hoop of radius 'R' as shown in figure. The bead moves under the combined action of gravity and a massless spring (k) attached to the bottom of the hoop.\nThe equilibrium length of the spring is 'R'. If the bead is released from top of the hoop with (negligible) zero initial speed, velocity of bead, when the length of spring becomes 'R', would be (spring constant is 'k', g is acceleration due to gravity)","fig":{"w":280,"h":230,"alt":"Vertical hoop of radius R with a spring along the vertical diameter from the bead m at the top to the bottom of the hoop, diameter 2R","d":[["c",140,105,80],["p","M140 25 L140 40 L128 48 L152 62 L128 76 L152 90 L128 104 L152 118 L128 132 L152 146 L140 154 L140 185"],["c",140,25,5,"F"],["t",150,20,"m"],["l",60,25,60,185,"db"],["t",54,108,"2R","e"],["t",160,110,"k","s"],["l",70,196,210,196]]},"o":["√(2Rg + {4kR²;m})","√(2Rg + {kR²;m})","2√(gR + {kR²;m})","√(3Rg + {kR²;m})"],"c":3,"s":"At the top, the spring length is 2R, so its extension is R. Energy stored = ½kR².\nWhen the spring length is R (natural length), the stored energy is zero. The bead is then at a chord R from the bottom, so the angle at the centre is 60°.\nHeight of the bead above the bottom = R(1 − cos60°) = R/2, so it has fallen 2R − R/2 = 3R/2.\nEnergy conservation: mg(3R/2) + ½kR² = ½mv².\nv = √(3Rg + kR²/m)."},
{"y":"JEE Main 2025 · 29 Jan · Shift 1","tp":"pwv","st":"Tension and speed in a circle","q":"A body of mass 'm' connected to a massless and unstretchable string goes in vertical circle of radius 'R' under gravity g. The other end of the string is fixed at the center of circle. If velocity at top of circular path is n√(gR), where, n ≥ 1, then ratio of kinetic energy of the body at bottom to that at top of the circle is","o":["{n;n+4}","{n²+4;n²}","{n²;n²+4}","{n+4;n}"],"c":1,"s":"KE at the top = ½m(n²gR).\nEnergy conservation from top to bottom (drop of 2R): KE_bottom = KE_top + mg(2R) = ½mgR(n² + 4).\nRatio = ½mgR(n² + 4) / (½mgRn²).\nRatio = (n² + 4)/n²."},
{"y":"JEE Main 2024 · 4 Apr · Shift 1","tp":"pwe","st":"Conservation of mechanical energy","q":"If a rubber ball falls from a height h and rebounds upto the height of h/2. The percentage loss of total energy of the initial system as well as velocity of ball before it strikes the ground, respectively, are","o":["50%, √{gh;2}","50%, √(2gh)","40%, √(2gh)","50%, √(gh)"],"c":1,"s":"Initial energy = mgh. After the rebound it reaches h/2, so energy = mgh/2.\nPercentage loss = (mgh − mgh/2)/mgh × 100 = 50%.\nSpeed just before hitting the ground (free fall from h): v² = 2gh.\nv = √(2gh)."},
{"y":"JEE Main 2024 · 4 Apr · Shift 2","tp":"pwe","st":"Conservation of mechanical energy","q":"A body of mass m kg slides from rest along the curve of vertical circle from point A to B in friction less path. The velocity of the body at B is\n(Given : R = 14 m, g = 10 m/s² and √2 = 1.4)","fig":{"w":340,"h":210,"alt":"Vertical circle with A on the circle at 45 degrees above the horizontal through the centre and B at the bottom","d":[["c",110,100,75],["l",110,25,110,175,"d"],["l",110,100,185,100],["l",110,100,163,47],["t",165,44,"A"],["t",106,192,"B","e"],["t",140,96,"45°","s"],["t",192,104,"(Vertical circle)"]]},"o":["21.9 m/s","16.7 m/s","10.6 m/s","19.8 m/s"],"c":0,"s":"A is at 45° above the horizontal through the centre, so its height above the centre is R sin45°.\nHeight of A above B = R + R sin45° = 14 + 14/√2 = 14 + 10 = 24 m (using √2 = 1.4).\nEnergy conservation: ½mv² = mg h, so v = √(2 × 10 × 24) = √480.\nv ≈ 21.9 m/s."},
{"y":"JEE Main 2024 · 5 Apr · Shift 1","tp":"pww","st":"Work by a constant force","q":"A body of mass 50 kg is lifted to a height of 20 m from the ground in the two different ways as shown in the figures. The ratio of work done against the gravity in both the cases, will be","fig":{"w":340,"h":250,"alt":"Case 1: a 50 kg box pulled straight up through 20 m. Case 2: a 50 kg box pulled up a 30 degree ramp of vertical height 20 m.","d":[["t",10,16,"Case 1: pulled straight up","s"],["r",40,70,30,24],["t",55,112,"M = 50 kg","ms"],["l",55,66,55,30,"a"],["l",230,30,230,100],["l",230,100,330,100],["l",230,30,330,100],["l",218,30,218,100,"bd"],["t",212,68,"h = 20 m","es"],["t",305,96,"30°","s"],["t",10,142,"Case 2: along the ramp","s"],["l",230,160,230,230],["l",230,230,330,230],["l",230,160,330,230],["l",218,160,218,230,"bd"],["t",212,198,"h = 20 m","es"],["r",275,184,14,14,"f"],["t",255,178,"M = 50 kg","es"],["l",270,205,248,192,"a"],["t",305,226,"30°","s"]]},"o":["1 : 2","1 : 1","√3 : 2","2 : 1"],"c":1,"s":"Work done against gravity depends only on the weight and the vertical height gained, not on the path.\nCase 1: W = mgh = 50 × 10 × 20 = 10000 J.\nCase 2: along the smooth ramp the force component along the ramp is mg sin30°, the distance is h/sin30°, so W = mgh again.\nRatio = 1 : 1."},
{"y":"JEE Main 2024 · 6 Apr · Shift 1","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"A bullet of mass 50 g is fired with a speed 100 m/s on a plywood and emerges with 40 m/s. The percentage loss of kinetic energy is","o":["32%","84%","16%","44%"],"c":1,"s":"Kinetic energy is proportional to v².\nFinal/initial = (40/100)² = 0.16.\nLoss = 1 − 0.16 = 0.84, i.e. 84%."},
{"y":"JEE Main 2024 · 6 Apr · Shift 1","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"Four particles A, B, C, D of mass {m;2}, m, 2m, 4m, have same momentum, respectively. The particle with maximum kinetic energy is","o":["C","A","D","B"],"c":1,"s":"For the same momentum p, K = p²/2m, so K is larger for the smaller mass.\nThe smallest mass is m/2, which belongs to particle A.\nSo A has the maximum kinetic energy."},
{"y":"JEE Main 2024 · 6 Apr · Shift 2","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"When kinetic energy of a body becomes 36 times of its original value, the percentage increase in the momentum of the body will be","o":["60%","500%","6%","600%"],"c":1,"s":"p = √(2mK), so p ∝ √K.\nK becomes 36 times, so p becomes √36 = 6 times.\nIncrease = (6 − 1) × 100 = 500%."},
{"y":"JEE Main 2024 · 8 Apr · Shift 1","tp":"pwc","st":"Collisions with springs and energy loss","q":"A stationary particle breaks into two parts of masses mₐ and m_B which move with velocities vₐ and v_B respectively. The ratio of their kinetic energies (K_B : Kₐ) is","o":["m_Bv_B : mₐvₐ","v_B : vₐ","1 : 1","m_B : mₐ"],"c":1,"s":"Starting from rest, momentum is conserved: mₐvₐ = m_Bv_B (equal magnitudes).\nK = ½ m v² = ½ p v for equal p.\nSo K_B : Kₐ = v_B : vₐ."},
{"y":"JEE Main 2024 · 8 Apr · Shift 1","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"Three bodies A, B and C have equal kinetic energies and their masses are 400 g, 1.2 kg and 1.6 kg, respectively. The ratio of their linear momenta is","o":["1 : √3 : 2","√2 : √3 : 1","1 : √3 : √2","√3 : √2 : 1"],"c":0,"s":"For equal kinetic energy, p = √(2mK), so p ∝ √m.\nMasses in kg: 0.4 : 1.2 : 1.6 = 1 : 3 : 4.\nRatio of momenta = √1 : √3 : √4 = 1 : √3 : 2."},
{"y":"JEE Main 2024 · 8 Apr · Shift 2","tp":"pwe","st":"Energy on slopes and with friction","q":"A block is simply released from the top of an inclined plane as shown in the figure above. The maximum compression in the spring when the block hits the spring is","fig":{"w":340,"h":170,"alt":"A 5 kg block on a smooth 30 degree incline of length 10 m. At the foot a horizontal rough surface (mu 0.5) of length 2 m leads to a spring of constant 100 N/m fixed to a wall.","d":[["l",30,25,150,94],["r",30,12,14,14,"f"],["t",52,24,"5 kg","s"],["t",72,36,"μ = 0","s"],["t",60,70,"10 m","es"],["l",150,94,300,94],["l",300,45,300,94,"B"],["p","M245,76 L250,68 L256,84 L262,68 L268,84 L274,68 L280,84 L286,68 L292,76 L300,76"],["t",252,56,"k = 100 N/m","s"],["l",150,112,245,112,"b"],["t",197,128,"2 m","ms"],["t",200,152,"μ = 0.5","ms"],["t",122,88,"30°","s"],["l",20,94,150,94,"d"]]},"o":["1 m","√6 m","2 m","√5 m"],"c":2,"s":"The incline is smooth (μ = 0). Height of the top = 10 sin30° = 5 m, so energy released = mgh = 5 × 10 × 5 = 250 J (g = 10 m/s²).\nFriction acts only on the 2 m rough stretch: loss = 0.5 × 5 × 10 × 2 = 50 J.\nEnergy left when the block reaches the spring = 200 J.\nThis goes into the spring: ½kx² = 200, so 50x² = 200 and x = 2 m.\n(The figure shows the rough surface only for the 2 m before the spring.)"},
{"y":"JEE Main 2024 · 9 Apr · Shift 2","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"A particle of mass m moves on a straight line with its velocity increasing with distance according to the equation v = α√x, where α is a constant. The total work done by all the forces applied on the particle during its displacement from x = 0 to x = d, will be","o":["2mα²d","{md;2α²}","{m;2α²d}","{mα²d;2}"],"c":3,"s":"By the work-energy theorem, work = change in kinetic energy.\nAt x = 0, v = 0. At x = d, v² = α²d.\nW = ½ m α² d − 0 = {mα²d;2}."},
{"y":"JEE Main 2024 · 1 Feb · Shift 1","tp":"pwc","st":"Inelastic collisions and coefficient of restitution","q":"A simple pendulum of length 1 m has a wooden bob of mass 1 kg. It is struck by a bullet of mass 10⁻² kg moving with a speed of 2 × 10² m s⁻¹. The bullet gets embedded into the bob. The height to which the bob rises before swinging back is (use g = 10 m s⁻²)","o":["0.35 m","0.40 m","0.20 m","0.30 m"],"c":2,"s":"Momentum is conserved in the collision: 0.01 × 200 = (1 + 0.01) v, so v = 2/1.01 ≈ 1.98 m/s.\nAfter that, mechanical energy is conserved: h = v²/2g = (1.98)²/20 ≈ 0.196 m.\nh ≈ 0.20 m."},
{"y":"JEE Main 2024 · 27 Jan · Shift 1","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"Two bodies of mass 4 g and 25 g are moving with equal kinetic energies. The ratio of magnitude of their linear momentum is","o":["2 : 5","3 : 5","4 : 5","5 : 4"],"c":0,"s":"For equal kinetic energy, p = √(2mK), so p ∝ √m.\np₁ : p₂ = √4 : √25 = 2 : 5."},
{"y":"JEE Main 2024 · 27 Jan · Shift 2","tp":"pwv","st":"Tension and speed in a circle","q":"A ball suspended by a thread swings in a vertical plane so that its magnitude of acceleration in the extreme position and lowest position are equal. The angle (θ) of thread deflection in the extreme position will be","o":["tan⁻¹(√2)","2tan⁻¹({1;√5})","2tan⁻¹({1;2})","tan⁻¹({1;2})"],"c":2,"s":"At the extreme position the speed is zero, so the acceleration is only tangential: a₁ = g sinθ.\nAt the lowest position v² = 2gL(1 − cosθ), and the acceleration is centripetal: a₂ = v²/L = 2g(1 − cosθ).\nSet a₁ = a₂: sinθ = 2(1 − cosθ), i.e. 2 sin(θ/2) cos(θ/2) = 4 sin²(θ/2).\nSo tan(θ/2) = 1/2, giving θ = 2tan⁻¹(1/2)."},
{"y":"JEE Main 2024 · 29 Jan · Shift 2","tp":"pwe","st":"Conservative forces and potential energy curves","q":"The potential energy function (in J) of a particle in a region of space is given as U = (2x² + 3y² + 2z). Here x, y and z are in meter. The magnitude of x-component of force (in N) acting on the particle at point P(1, 2, 3) m is","o":["8","4","6","2"],"c":1,"s":"Force is the negative gradient of potential energy: Fₓ = −∂U/∂x.\nFₓ = −∂(2x² + 3y² + 2z)/∂x = −4x.\nAt x = 1 m, Fₓ = −4 N, so the magnitude is 4 N."},
{"y":"JEE Main 2024 · 29 Jan · Shift 2","tp":"pwv","st":"Tension and speed in a circle","q":"The bob of a pendulum was released from a horizontal position. The length of the pendulum is 10 m. If it dissipates 10% of its initial energy against air resistance, the speed with which the bob arrives at the lowest point is\n[Use, g = 10 m s⁻²]","o":["5√5 m s⁻¹","2√5 m s⁻¹","5√6 m s⁻¹","6√5 m s⁻¹"],"c":3,"s":"The bob falls through a height L = 10 m, so initial energy = mgL.\n90% of it becomes kinetic energy: ½mv² = 0.9 mgL.\nv² = 1.8 gL = 1.8 × 10 × 10 = 180.\nv = √180 = 6√5 m/s."},
{"y":"JEE Main 2024 · 29 Jan · Shift 2","tp":"pwv","st":"Vertical circle conditions","q":"A bob of mass 'm' is suspended by a light string of length 'L'. It is imparted a minimum horizontal velocity at the lowest point A such that it just completes the circle reaching the top most position B. The ratio of kinetic energies (K.E.)A / (K.E.)B is","o":["3 : 2","1 : 5","2 : 5","5 : 1"],"c":3,"s":"At the top B, the minimum speed for a string is v_B = √(gL).\nEnergy conservation from A to B: ½v_A² = ½v_B² + 2gL, so v_A² = gL + 4gL = 5gL.\n(K.E.)A / (K.E.)B = v_A² / v_B² = 5gL / gL = 5 : 1."},
{"y":"JEE Main 2024 · 30 Jan · Shift 1","tp":"pwe","st":"Conservation of mechanical energy","q":"A particle is placed at the point A of a frictionless track ABC as shown in figure. It is gently pushed towards right. The speed of the particle when it reaches the point B is (Take g = 10 m/s²)","fig":{"w":300,"h":150,"alt":"A frictionless bowl-shaped track ABC. A is at the left rim, 1 m above the ground. B is on the left slope, 0.5 m above the ground. C is at the right rim at the same height as A.","d":[["p","M30,50 H62 C75,125 110,130 145,130 C185,130 210,125 222,50 H280"],["l",20,130,290,130],["c",45,42,2.5,"F"],["t",45,32,"A","ms"],["t",76,86,"B","s"],["t",255,40,"C","ms"],["l",68,90,130,90,"d"],["l",20,50,20,130,"b"],["t",16,94,"1 m","es"],["l",42,90,42,130,"b"],["t",46,114,"0.5 m","s"]]},"o":["10 m/s","√10 m/s","2√10 m/s","20 m/s"],"c":1,"s":"A is 1 m above the ground and B is 0.5 m above the ground, so the particle falls through 1 − 0.5 = 0.5 m. The gentle push gives almost no initial speed.\nEnergy conservation: ½mv² = mg(0.5).\nv = √(2 × 10 × 0.5) = √10 m/s."},
{"y":"JEE Main 2024 · 31 Jan · Shift 1","tp":"pwc","st":"Collisions with springs and energy loss","q":"An artillery piece of mass M₁ fires a shell of mass M₂ horizontally. Instantaneously after the firing, the ratio of kinetic energy of the artillery and that of the shell is","o":["{M₁;(M₁+M₂)}","{M₂;M₁}","{M₂;(M₁+M₂)}","{M₁;M₂}"],"c":1,"s":"Before firing the system is at rest, so the momenta of the gun and shell are equal in size: p.\nK = p²/2m, so K ∝ 1/m.\nK(gun) : K(shell) = M₂ : M₁, i.e. {M₂;M₁}."},
{"y":"JEE Main 2023 · 13 Apr · Shift 1","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"Two bodies are having kinetic energies in the ratio 16 : 9. If they have same linear momentum, the ratio of their masses respectively is","o":["4 : 3","3 : 4","16 : 9","9 : 16"],"c":3,"s":"For the same momentum p, K = p²/2m, so m ∝ 1/K.\nm₁ : m₂ = K₂ : K₁ = 9 : 16."},
{"y":"JEE Main 2022 · 24 Jun · Shift 1","tp":"pww","st":"Work by a variable force","q":"A particle experiences a variable force F⃗ = (4xî + 3y²ĵ) in a horizontal x-y plane. Assume distance in meters and force is newton. If the particle moves from point (1, 2) to point (2, 3) in the x-y plane, then kinetic energy changes by","o":["50.0 J","12.5 J","25.0 J","0 J"],"c":2,"s":"Change in kinetic energy = work done = ∫Fₓ dx + ∫F_y dy.\n∫ from 1 to 2 of 4x dx = 2(2² − 1²) = 6 J.\n∫ from 2 to 3 of 3y² dy = 3³ − 2³ = 19 J.\nΔK = 6 + 19 = 25 J."},
{"y":"JEE Main 2022 · 28 Jun · Shift 2","tp":"pww","st":"Work by a variable force","q":"A block of mass 2 kg moving on a horizontal surface with speed of 4 m s⁻¹ enters a rough surface ranging from x = 0.5 m to x = 1.5 m. The retarding force in this range of rough surface is related to distance by F = −kx where k = 12 N m⁻¹. The speed of the block as it just crosses the rough surface will be","o":["zero","1.5 m s⁻¹","2.0 m s⁻¹","2.5 m s⁻¹"],"c":2,"s":"Work done by the retarding force = −∫ kx dx from 0.5 to 1.5 = −½ × 12 × (1.5² − 0.5²) = −6 × 2 = −12 J.\nInitial kinetic energy = ½ × 2 × 4² = 16 J.\nFinal kinetic energy = 16 − 12 = 4 J = ½ × 2 × v², so v = 2 m/s."},
{"y":"JEE Main 2022 · 26 Jul · Shift 1","tp":"pwe","st":"Potential energy and springs","q":"As per the given figure, two blocks each of mass 250 g are connected to a spring of spring constant 2 N m⁻¹. If both are given velocity v in opposite directions, then maximum elongation of the spring is","fig":{"w":300,"h":110,"alt":"Two blocks of 250 g joined by a spring, moving away from each other with speed v.","d":[["r",70,40,50,34],["t",95,61,"250 g","ms"],["p","M120,57 L126,47 L134,67 L142,47 L150,67 L158,47 L166,67 L172,57 L180,57"],["r",180,40,50,34],["t",205,61,"250 g","ms"],["l",70,57,35,57,"a"],["t",52,48,"v","ms"],["l",230,57,265,57,"a"],["t",248,48,"v","ms"]]},"o":["{v;2√2}","{v;2}","{v;4}","{v;√2}"],"c":1,"s":"The total momentum is zero, so at maximum elongation both blocks are momentarily at rest.\nAll kinetic energy becomes spring energy: 2 × ½ × 0.25 × v² = ½ × 2 × x².\n0.25v² = x², so x = v/2."},
{"y":"JEE Main 2022 · 26 Jul · Shift 2","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"A body of mass 8 kg and another of mass 2 kg are moving with equal kinetic energy. The ratio of their respective momenta will be","o":["1 : 1","2 : 1","1 : 4","4 : 1"],"c":1,"s":"For equal kinetic energy, p = √(2mK), so p ∝ √m.\np₁ : p₂ = √8 : √2 = 2 : 1."},
{"y":"JEE Main 2022 · 28 Jul · Shift 2","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"A bullet of mass 200 g having initial kinetic energy 90 J is shot inside a long swimming pool. It's kinetic energy reduces to 40 J within 1 s, the minimum length of the pool, the bullet has to travel so that it completely comes to rest at is","o":["45 m","90 m","125 m","25 m"],"c":0,"s":"Initial speed: ½ × 0.2 × v₀² = 90, so v₀ = 30 m/s.\nAfter 1 s: ½ × 0.2 × v² = 40, so v = 20 m/s.\nTaking a constant retardation: a = (30 − 20)/1 = 10 m/s².\nDistance to stop: s = v₀²/2a = 900/20 = 45 m."},
{"y":"JEE Main 2022 · 29 Jul · Shift 1","tp":"pwe","st":"Conservation of mechanical energy","q":"A ball is thrown up vertically with a certain velocity so that, it reaches a maximum height h. Find the ratio of the times in which it is at height {h;3} while going up and coming down respectively.","o":["{√2 − 1;√2 + 1}","{√3 − √2;√3 + √2}","{√3 − 1;√3 + 1}","{1;3}"],"c":1,"s":"Let the launch speed be u, so h = u²/2g.\nHeight h/3: ut − ½gt² = h/3 = u²/6g. Solving, t = (u/g)(1 ∓ √(2/3)).\nGoing up (smaller t): t₁ = (u/g)(1 − √(2/3)); coming down (larger t): t₂ = (u/g)(1 + √(2/3)).\nt₁/t₂ = (√3 − √2)/(√3 + √2)."},
{"y":"JEE Main 2022 · 29 Jul · Shift 2","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"If momentum of a body is increased by 20%, then its kinetic energy increases by","o":["36%","40%","44%","48%"],"c":2,"s":"K = p²/2m, so K ∝ p².\nNew p = 1.2p, so new K = 1.44 K.\nIncrease = 44%."},
{"y":"JEE Main 2022 · 24 Jun · Shift 2","tp":"pwe","st":"Conservative forces and potential energy curves","q":"Potential energy as a function of r is given by U = {A;r¹⁰} − {B;r⁵}, where r is the interatomic distance, A and B are positive constants. The equilibrium distance between the two atoms will be","o":["({A;B})^(1/5)","({B;A})^(1/5)","({2A;B})^(1/5)","({B;2A})^(1/5)"],"c":2,"s":"At equilibrium the force is zero, so dU/dr = 0.\ndU/dr = −10A/r¹¹ + 5B/r⁶ = 0.\n5B/r⁶ = 10A/r¹¹, so r⁵ = 2A/B.\nr = (2A/B)^(1/5)."},
{"y":"JEE Main 2022 · 26 Jun · Shift 1","tp":"pwe","st":"Conservation of mechanical energy","q":"An object is thrown vertically upwards. At its maximum height, which of the following quantity becomes zero?","o":["Momentum","Potential energy","Acceleration","Force"],"c":0,"s":"At the highest point the velocity is zero, so momentum mv = 0.\nPotential energy is maximum there, and gravity (force and acceleration g) still acts, so they are not zero."},
{"y":"JEE Main 2022 · 27 Jun · Shift 2","tp":"pwv","st":"Tension and speed in a circle","q":"A stone tied to a string of length L is whirled in a vertical circle with the other end of the string at the centre. At a certain instant of time, the stone is at its lowest position and has a speed u. The magnitude of change in its velocity, as it reaches a position where the string is horizontal, is √(x(u² − gL)). The value of x is","o":["3","2","1","5"],"c":1,"s":"At the lowest point the velocity is u (horizontal). At the horizontal position the velocity v is vertical.\nEnergy conservation: v² = u² − 2gL.\nThe two velocities are perpendicular, so |Δv| = √(u² + v²) = √(2u² − 2gL) = √(2(u² − gL)).\nSo x = 2."},
{"y":"JEE Main 2022 · 29 Jun · Shift 1","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"A particle of mass 500 gm is moving in straight line with velocity v = bx^(5/2). The work done by the net force during its displacement from x = 0 to x = 4 m is\n(Take b = 0.25 m^(−3/2) s⁻¹).","o":["2 J","4 J","8 J","16 J"],"c":3,"s":"At x = 4 m: v = 0.25 × 4^(5/2) = 0.25 × 32 = 8 m/s. At x = 0, v = 0.\nWork by the net force = change in kinetic energy.\nW = ½ × 0.5 × 8² = 16 J."},
{"y":"JEE Main 2022 · 29 Jun · Shift 2","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"In the given figure, the block of mass m is dropped from the point 'A'. The expression for kinetic energy of block when it reaches point 'B' is","fig":{"w":220,"h":240,"alt":"A block starts at point A at the top. Point B is a distance y0 below A. The ground is at the bottom; y is the distance measured from A down to the ground.","d":[["r",60,8,60,20,"f"],["l",120,18,180,18,"d"],["t",186,22,"A"],["l",100,108,180,108,"d"],["t",186,112,"B"],["l",135,18,135,108,"b"],["t",142,66,"y₀","s"],["l",72,30,72,208,"b"],["t",64,124,"y","es"],["l",40,212,170,212],["t",105,230,"Ground","ms"]]},"o":["½ mg y₀²","½ mg y²","mg (y − y₀)","mg y₀"],"c":3,"s":"The block starts from rest at A and falls a distance y₀ to reach B.\nBy the work-energy theorem (only gravity acts): K = mg × (distance fallen).\nK = mg y₀."},
{"y":"JEE Main 2021 · 1 Sep · Shift 2","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"A body of mass 'm' dropped from a height 'h' reaches the ground with a speed of 0.8√(gh). The value of work done by the air-friction is","o":["−0.68 mgh","mgh","0.64 mgh","1.64 mgh"],"c":0,"s":"Work-energy theorem: W_gravity + W_air = change in K.\nmgh + W_air = ½m(0.8√(gh))² = 0.32 mgh.\nW_air = 0.32 mgh − mgh = −0.68 mgh."},
{"y":"JEE Main 2021 · 31 Aug · Shift 2","tp":"pwc","st":"Collisions with springs and energy loss","q":"A block moving horizontally on a smooth surface with a speed of 40 m/s splits into two parts with masses in the ratio of 1 : 2. If the smaller part moves at 60 m/s in the same direction, then the fractional change in kinetic energy is","o":["{1;3}","{2;3}","{1;4}","{1;8}"],"c":3,"s":"Let masses be m and 2m (total 3m). Momentum conservation: 3m × 40 = m × 60 + 2m × v, so v = 30 m/s.\nInitial K = ½ × 3m × 1600 = 2400m.\nFinal K = ½m(3600) + ½(2m)(900) = 1800m + 900m = 2700m.\nFractional change = (2700m − 2400m)/2400m = 1/8."},
{"y":"JEE Main 2021 · 20 Jul · Shift 2","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"If the kinetic energy of a moving body becomes four times its initial kinetic energy, then the percentage change in its momentum will be","o":["100%","200%","400%","300%"],"c":0,"s":"p ∝ √K.\nK becomes 4 times, so p becomes 2 times.\nPercentage change = (2 − 1) × 100 = 100%."},
{"y":"JEE Main 2021 · 22 Jul · Shift 2","tp":"pww","st":"Work by a constant force","q":"A porter lifts a heavy suitcase of mass 80 kg and at the destination lowers it down by a distance of 80 cm with a constant velocity. Calculate the work done by the porter in lowering the suitcase. (Take g = 9.8 m s⁻²)","o":["−62720.0 J","+627.2 J","−627.2 J","784.0 J"],"c":2,"s":"Constant velocity means no change in kinetic energy, so the porter's force equals the weight mg and points upward.\nThe suitcase moves down 0.8 m, opposite to the force, so the work is negative.\nW = −mgh = −80 × 9.8 × 0.8 = −627.2 J."},
{"y":"JEE Main 2021 · 27 Jul · Shift 1","tp":"pwe","st":"Conservative forces and potential energy curves","q":"Given below is the plot of a potential energy function U(x) for a system, in which a particle is in one dimensional motion, while a conservative force F(x) acts on it. Suppose that Emech = 8 J, the incorrect statement for this system is\n[where K.E. = kinetic energy]","fig":{"w":340,"h":185,"alt":"Potential energy U against x. U equals 8 J for x below x1, drops steeply to 0 at x2, rises to a hump of 4 J at x3, dips again, rises to 6 J at x4 and jumps to 8 J beyond x4. A dashed line marks the mechanical energy 8 J.","d":[["l",50,160,50,15,"a"],["l",50,160,325,160,"a"],["t",58,14,"U (J)","s"],["t",320,176,"x","s"],["t",44,164,"0","es"],["t",44,136,"2","es"],["t",44,112,"4","es"],["t",44,88,"6","es"],["t",44,64,"8","es"],["t",44,40,"10","es"],["l",50,64,330,64,"d"],["t",260,52,"Emech = 8 J","s"],["p","M50,64 H110 Q120,64 123,110 Q128,160 138,160 Q150,160 155,135 Q160,112 165,112 Q172,112 178,135 Q190,160 205,160 Q230,160 245,90 L250,88 V64 H325","B"],["l",110,64,110,160,"d"],["l",138,100,138,160,"d"],["l",165,112,165,160,"d"],["l",250,64,250,160,"d"],["t",110,174,"x₁","ms"],["t",138,174,"x₂","ms"],["t",165,174,"x₃","ms"],["t",250,174,"x₄","ms"]]},"o":["at x = x₂, K.E. is greatest and the particle is moving at the fastest speed.","at x < x₁, K.E. is smallest and the particle is moving at the slowest speed.","at x = x₃, K.E. = 4 J","at x > x₄, K.E. is constant throughout the region."],"c":1,"s":"K.E. = Emech − U(x) = 8 − U.\n(a) At x₂, U = 0 (minimum), so K.E. = 8 J is greatest. True.\n(c) At x₃, U = 4 J, so K.E. = 4 J. True.\n(d) For x > x₄, U = 8 J everywhere, so K.E. = 0 is constant. True.\n(b) For x < x₁, U = 8 J = Emech, so K.E. = 0 there; the particle is at rest, not 'moving at the slowest speed'. This is the incorrect statement."},
{"y":"JEE Main 2021 · 17 Mar · Shift 1","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"A boy is rolling a 0.5 kg ball on the frictionless floor with the speed of 20 m s⁻¹. The ball gets deflected by an obstacle on the way. After deflection it moves with 5% of its initial kinetic energy. What is the speed of the ball now ?","o":["19.0 m s⁻¹","14.41 m s⁻¹","4.47 m s⁻¹","1.00 m s⁻¹"],"c":2,"s":"Kinetic energy is proportional to v², so v_new = v × √(0.05).\nv_new = 20 × 0.2236 = 4.47 m/s."},
{"y":"JEE Main 2021 · 18 Mar · Shift 2","tp":"pwe","st":"Conservative forces and potential energy curves","q":"A particle of mass m moves in a circular orbit under the central potential field, U(r) = −{C;r}, where C is a positive constant.\nThe correct radius – velocity graph of the particle's motion is","fig":{"w":340,"h":255,"alt":"Four radius-versus-speed graphs. (a) quarter-circle falling from the r axis to the v axis, (b) straight line through the origin, (c) curve rising steeply with v, (d) curve falling like a hyperbola, steep near the r axis and flattening toward the v axis.","d":[["l",30,90,30,12,"a"],["l",30,90,160,90,"a"],["t",24,14,"r","es"],["t",162,102,"v","s"],["t",22,102,"O","es"],["t",95,116,"(a)","ms"],["p","M30,25 L55,25 C105,25 120,55 120,90"],["l",200,90,200,12,"a"],["l",200,90,330,90,"a"],["t",194,14,"r","es"],["t",332,102,"v","s"],["t",192,102,"O","es"],["t",265,116,"(b)","ms"],["p","M200,90 L305,28"],["l",30,215,30,137,"a"],["l",30,215,160,215,"a"],["t",24,139,"r","es"],["t",162,227,"v","s"],["t",22,227,"O","es"],["t",95,241,"(c)","ms"],["p","M32,213 C85,210 120,195 132,150"],["l",200,215,200,137,"a"],["l",200,215,330,215,"a"],["t",194,139,"r","es"],["t",332,227,"v","s"],["t",192,227,"O","es"],["t",265,241,"(d)","ms"],["p","M210,139 C212,185 235,211 320,213"]]},"o":["Graph (a)","Graph (b)","Graph (c)","Graph (d)"],"c":3,"s":"Force F = −dU/dr = −C/r² (attractive), of size C/r².\nThis provides the centripetal force: mv²/r = C/r², so v² = C/(mr).\nSo r = C/(mv²), i.e. r ∝ 1/v². The graph of r against v is a falling hyperbola-type curve, steep near the r axis and flattening toward the v axis. This is graph (d)."},
{"y":"JEE Main 2021 · 24 Feb · Shift 2","tp":"pww","st":"Work by a variable force","q":"A particle is projected with velocity v₀ along x-axis. A damping force is acting on the particle which is proportional to the square of the distance from the origin i.e., a = −αx² (α is a constant). The distance at which the particle stops is","o":["({2v₀²;3α})^(1/2)","({3v₀²;2α})^(1/2)","({2v₀;3α})^(1/3)","({3v₀²;2α})^(1/3)"],"c":3,"s":"Use a = v dv/dx. Taking the damping as a = −αx² (the options have no m, so the mass is absorbed in α):\nv dv/dx = −αx², so ∫ v dv from v₀ to 0 = −α ∫ x² dx from 0 to X.\n−v₀²/2 = −αX³/3.\nX³ = 3v₀²/(2α), so X = (3v₀²/2α)^(1/3)."},
{"y":"JEE Main 2020 · 4 Sep · Shift 2","tp":"pwe","st":"Conservation of mechanical energy","q":"Two identical cylindrical vessels are kept on the ground and each contain the same liquid of density d. The area of the base of both vessels is S but the height of liquid in one vessel is x₁ and in the other, x₂. When both cylinders are connected through a pipe of negligible volume very close to the bottom, the liquid flows from one vessel to the other until it comes to equilibrium at a new height. The change in energy of the system in the process is","o":["{3;4} gdS(x₂ − x₁)²","gdS(x₂² − x₁²)","{1;4} gdS(x₂ − x₁)²","gdS(x₂ + x₁)²"],"c":2,"s":"A liquid column of height x and base S has mass dSx and its centre of mass is at x/2, so its potential energy is dSg x²/2.\nInitial: U_i = dSg(x₁² + x₂²)/2.\nFinal height is (x₁ + x₂)/2 in each vessel: U_f = 2 × dSg((x₁ + x₂)/2)²/2 = dSg(x₁ + x₂)²/4.\nU_i − U_f = dSg(x₁² + x₂²)/2 − dSg(x₁ + x₂)²/4 = {1;4} dSg(x₂ − x₁)².\nThe energy of the system changes (decreases) by {1;4} gdS(x₂ − x₁)²."},
{"y":"JEE Main 2020 · 6 Sep · Shift 1","tp":"pwe","st":"Conservative forces and potential energy curves","q":"If the potential energy between two molecules is given by U = −{A;r⁶} + {B;r¹²}, then at equilibrium, separation between molecules, and the potential energy are","o":["({B;2A})^(1/6), −{A²;2B}","({B;A})^(1/6), 0","({2B;A})^(1/6), −{A²;4B}","({2B;A})^(1/6), −{A²;2B}"],"c":2,"s":"At equilibrium dU/dr = 0: 6A/r⁷ − 12B/r¹³ = 0, so r⁶ = 2B/A and r = (2B/A)^(1/6).\nThen A/r⁶ = A²/2B and B/r¹² = B A²/4B² = A²/4B.\nU = −A²/2B + A²/4B = −A²/4B."},
{"y":"JEE Main 2019 · 8 Apr · Shift 1","tp":"pww","st":"Graphs of force and work","q":"A particle moves in one dimension from rest under the influence of a force that varies with the distance travelled by the particle as shown in the figure. The kinetic energy of the particle after it has travelled 3 m is","fig":{"w":300,"h":170,"alt":"Force in newton against distance in metre. The force is 2 N from 0 to 2 m, then rises in a straight line to 3 N at 3 m.","d":[["l",50,140,50,20,"a"],["l",50,140,270,140,"a"],["t",56,16,"Force (N)","s"],["t",270,158,"Distance (m)","es"],["l",46,110,50,110],["t",42,114,"1","es"],["l",46,80,50,80],["t",42,84,"2","es"],["l",46,50,50,50],["t",42,54,"3","es"],["l",110,140,110,144],["t",110,155,"1","ms"],["l",170,140,170,144],["t",170,155,"2","ms"],["l",230,140,230,144],["t",230,155,"3","ms"],["p","M50,80 H170 L230,50","B"],["l",50,50,230,50,"d"],["l",170,80,170,140,"d"],["l",230,50,230,140,"d"]]},"o":["2.5 J","6.5 J","5 J","4 J"],"c":1,"s":"The work done equals the area under the force-distance graph, and it equals the kinetic energy gained (starts from rest).\nFrom 0 to 2 m, F = 2 N: area = 2 × 2 = 4 J.\nFrom 2 to 3 m, F rises from 2 N to 3 N: area = ½ × (2 + 3) × 1 = 2.5 J.\nK = 4 + 2.5 = 6.5 J."},
{"y":"JEE Main 2019 · 9 Apr · Shift 2","tp":"pwe","st":"Conservation of mechanical energy","q":"A wedge of mass M = 4m lies on a frictionless plane. A particle of mass m approaches the wedge with speed v. There is no friction between the particle and the plane or between the particle and the wedge. The maximum height climbed by the particle on the wedge is given by","o":["{v²;g}","{2v²;5g}","{v²;2g}","{2v²;7g}"],"c":1,"s":"At maximum height the particle and wedge move with the same horizontal velocity V.\nMomentum conservation: mv = (m + 4m)V, so V = v/5.\nEnergy conservation: ½mv² = ½(5m)(v/5)² + mgh.\nmgh = ½mv² − ½mv²/5 = (2/5)mv², so h = 2v²/5g."},
{"y":"JEE Main 2019 · 12 Apr · Shift 2","tp":"pwe","st":"Potential energy and springs","q":"A spring whose unstretched length is l has a force constant k. The spring is cut into two pieces of unstretched length l₁ and l₂ where, l₁ = nl₂ and n is an integer. The ratio k₁/k₂ of the corresponding force constants, k₁ and k₂ will be","o":["{1;n²}","n²","n","{1;n}"],"c":3,"s":"The force constant of a spring is inversely proportional to its length (k × l is constant).\nSo k₁l₁ = k₂l₂, giving k₁/k₂ = l₂/l₁.\nSince l₁ = nl₂, k₁/k₂ = 1/n."},
{"y":"JEE Main 2019 · 9 Jan · Shift 1","tp":"pwe","st":"Potential energy and springs","q":"A block of mass m, lying on a smooth horizontal surface, is attached to a spring (of negligible mass) of spring constant k. The other end of the spring is fixed, as shown in the figure. The block is initially at rest in its equilibrium position. If now the block is pulled with a constant force F, the maximum speed of the block is","fig":{"w":300,"h":110,"alt":"A block of mass m on a smooth horizontal surface attached to a spring whose other end is fixed to a wall on the left. A constant force F pulls the block to the right.","d":[["l",30,20,30,80],["l",30,80,280,80],["p","M30,62 L40,62 L46,52 L54,72 L62,52 L70,72 L78,52 L86,72 L92,62 L110,62"],["r",110,46,44,34,"f"],["t",132,68,"m","ms"],["l",154,62,210,62,"a"],["t",222,66,"F"]]},"o":["{F;√(mk)}","{F;π√(mk)}","{πF;√(mk)}","{2F;√(mk)}"],"c":0,"s":"The speed is maximum when the net force is zero, i.e. kx = F, so x = F/k.\nWork-energy theorem: F x − ½kx² = ½mv².\nF²/k − F²/2k = F²/2k = ½mv².\nv² = F²/(mk), so v = F/√(mk)."},
{"y":"JEE Main 2019 · 9 Jan · Shift 2","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"A force acts on a 2 kg object so that its position is given as a function of time as x = 3t² + 5. What is the work done by this force in first 5 seconds?","o":["850 J","950 J","875 J","900 J"],"c":3,"s":"Velocity v = dx/dt = 6t. At t = 0, v = 0; at t = 5 s, v = 30 m/s.\nWork = change in kinetic energy = ½ × 2 × 30² − 0.\nW = 900 J."},
{"y":"JEE Main 2019 · 10 Jan · Shift 2","tp":"pww","st":"Work by a constant force","q":"A particle which is experiencing a force, given by F⃗ = 3î − 12ĵ, undergoes a displacement d⃗ = 4î. If the particle has a kinetic energy of 3 J at the beginning of the displacement, what is its kinetic energy at the end of the displacement?","o":["9 J","12 J","10 J","15 J"],"c":3,"s":"Work done = F⃗·d⃗ = (3)(4) + (−12)(0) = 12 J.\nBy the work-energy theorem, final KE = initial KE + work done.\nFinal KE = 3 + 12 = 15 J.\nAnswer: 15 J."},
{"y":"JEE Main 2018","tp":"pwe","st":"Conservative forces and potential energy curves","q":"A particle is moving in a circular path of radius a under the action of an attractive potential U = −{k;2r²}. Its total energy is","o":["−{k;4a²}","{k;2a²}","Zero","−{3k;2a²}"],"c":2,"s":"Force from the potential: F = −dU/dr = −k/r³, so the attractive force has magnitude k/r³.\nFor a circular orbit of radius a: mv²/a = k/a³, so mv² = k/a².\nKE = ½mv² = k/(2a²). PE = −k/(2a²).\nTotal energy = KE + PE = 0.\nAnswer: zero."},
{"y":"JEE Main 2018 · Online","tp":"pwe","st":"Conservative forces and potential energy curves","q":"Two particles of the same mass m are moving in circular orbits because of force, given by F(r) = −{16;r} − r³. The first particle is at a distance r = 1, and the second, at r = 4. The best estimate for the ratio of kinetic energies of the first and the second particle is closest to","o":["6 × 10⁻²","10⁻¹","3 × 10⁻²","6 × 10²"],"c":0,"s":"The force is attractive with magnitude F = 16/r + r³ and supplies the centripetal force: mv²/r = 16/r + r³.\nSo KE = ½mv² = ½(16 + r⁴).\nAt r = 1: KE₁ = ½(17) = 8.5. At r = 4: KE₂ = ½(16 + 256) = 136.\nRatio = 8.5/136 = 1/16 = 0.0625 ≈ 6 × 10⁻².\nAnswer: 6 × 10⁻²."},
{"y":"JEE Main 2018 · Online","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"A body of mass m starts moving from rest along x-axis so that its velocity varies as v = a√s where a is a constant and s is the distance covered by the body. The total work done by all the forces acting on the body in the first t seconds after the start of the motion is","o":["{1;4}ma⁴t²","4ma⁴t²","{1;8}ma⁴t²","8ma⁴t²"],"c":2,"s":"v² = a²s. Compare with v² = 2·(acceleration)·s: the acceleration is a²/2, constant.\nStarting from rest, v = (a²/2)t after time t.\nWork done by all forces = change in KE = ½mv² = ½m(a⁴t²/4).\nWork = ma⁴t²/8.\nAnswer: ma⁴t²/8 (option c)."},
{"y":"JEE Main 2017","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"A body of mass m = 10⁻² kg is moving in a medium and experiences a frictional force F = −kv². Its initial speed is v₀ = 10 m s⁻¹. If, after 10 s, its energy is {1;8}mv₀², the value of k will be","o":["10⁻³ kg m⁻¹","10⁻³ kg s⁻¹","10⁻⁴ kg m⁻¹","10⁻¹ kg m⁻¹ s⁻¹"],"c":2,"s":"Final energy: ½mv² = ⅛mv₀², so v² = v₀²/4 and v = v₀/2 = 5 m/s.\nEquation of motion: m dv/dt = −kv², so dv/v² = −(k/m)dt.\nIntegrate: 1/v − 1/v₀ = kt/m. Here 1/5 − 1/10 = 0.1.\nSo k = 0.1 × m/t = 0.1 × 10⁻²/10 = 10⁻⁴ (units kg/m, since F = kv²).\nAnswer: 10⁻⁴ kg m⁻¹."},
{"y":"JEE Main 2017","tp":"pww","st":"Work by a variable force","q":"A time dependent force F = 6t acts on a particle of mass 1 kg. If the particle starts from rest, the work done by the force during the first 1 sec will be","o":["4.5 J","22 J","9 J","18 J"],"c":0,"s":"Acceleration a = F/m = 6t, so v = ∫6t dt = 3t² (starting from rest).\nAt t = 1 s, v = 3 m/s.\nWork = change in KE = ½(1)(3)² = 4.5 J.\nAnswer: 4.5 J."},
{"y":"JEE Main 2016","tp":"pwe","st":"Energy on slopes and with friction","q":"A point particle of mass m, moves along the uniformly rough track PQR as shown in the figure. The coefficient of friction, between the particle and the rough track equals μ. The particle is released, from rest, from the point P and it comes to rest at a point R. The energies, lost by the ball, over the parts, PQ and QR, of the track, are equal to each other, and no energy is lost when particle changes direction from PQ to QR.\nThe values of the coefficient of friction μ and the distance x (= QR), are respectively close to","o":["0.2 and 6.5 m","0.2 and 3.5 m","0.29 and 3.5 m","0.29 and 6.5 m"],"c":2,"s":"Height h = 2 m and the slope angle is 30°, so PQ = h/sin30° = 4 m.\nEnergy lost on PQ = μmg cos30° × 4 = 2√3 μmg. Energy lost on QR = μmg x.\nThese are equal, so x = 2√3 ≈ 3.46 m ≈ 3.5 m.\nTotal loss = mgh, and the two losses are equal: 2(2√3 μmg) = mg(2), so μ = 1/(2√3) ≈ 0.29.\nAnswer: μ ≈ 0.29 and x ≈ 3.5 m.","fig":{"w":340,"h":170,"alt":"Right triangle track: point P at height h = 2 m above the horizontal surface, the slope PQ makes 30 degrees with the surface at Q, and the horizontal rough track continues from Q to R.","d":[["l",20,120,320,120],["l",70,40,208,120,"B"],["l",208,120,300,120,"B"],["l",70,40,70,120,"db"],["t",62,38,"P","e"],["t",208,138,"Q","m"],["t",300,138,"R","m"],["t",62,84,"h = 2 m","e"],["t",170,114,"30°","s"],["c",70,40,3,"F"]]}},
{"y":"JEE Main 2016","tp":"pwp","st":"Power and efficiency","q":"A person trying to lose weight by burning fat lifts a mass of 10 kg upto a height of 1 m 1000 times. Assume that the potential energy lost each time he lowers the mass is dissipated. How much fat will he use up considering the work done only when the weight is lifted up? Fat supplies 3.8 × 10⁷ J of energy per kg which is converted to mechanical energy with a 20% efficiency rate. Take g = 9.8 m s⁻².","o":["2.45 × 10⁻³ kg","6.45 × 10⁻³ kg","9.89 × 10⁻³ kg","12.89 × 10⁻³ kg"],"c":3,"s":"Work in one lift = mgh = 10 × 9.8 × 1 = 98 J. For 1000 lifts: 98 000 J.\nOnly 20% of the energy from fat becomes mechanical work, so energy needed from fat = 98 000/0.2 = 4.9 × 10⁵ J.\nMass of fat = 4.9 × 10⁵ / (3.8 × 10⁷) = 1.289 × 10⁻² kg.\nAnswer: 12.89 × 10⁻³ kg."},
{"y":"JEE Main 2016 · Online","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"Velocity-time graph for a body of mass 10 kg is shown in figure. Work-done on the body in first two seconds of the motion is","o":["−9300 J","12000 J","−4500 J","−12000 J"],"c":2,"s":"The graph is a straight line from 50 m/s at t = 0 to 0 at t = 10 s. Slope = −5 m/s², so v = 50 − 5t.\nAt t = 2 s, v = 40 m/s.\nWork done = change in KE = ½(10)(40² − 50²) = 5 × (−900) = −4500 J.\nAnswer: −4500 J.","fig":{"w":340,"h":180,"alt":"Velocity-time graph: a straight line falling from 50 m/s at t = 0 to zero at t = 10 s.","d":[["l",50,150,50,20,"a"],["l",50,150,300,150,"a"],["l",50,40,250,150,"B"],["l",250,146,250,154],["t",50,14,"v (m/s)","m"],["t",44,44,"50 m/s","e"],["t",250,168,"10 s","m"],["t",44,164,"O","e"],["t",306,154,"t (s)"]]}},
{"y":"JEE Main 2015 · Online","tp":"pwe","st":"Potential energy and springs","q":"A block of mass m = 0.1 kg is connected to a spring of unknown spring constant k. It is compressed to a distance x from its equilibrium position and released from rest. After approaching half the distance ({x;2}) from equilibrium position, it hits another block of the same mass and comes to rest momentarily, while the other block moves with a velocity 3 m s⁻¹. The total initial energy of the spring is","o":["1.5 J","0.6 J","0.3 J","0.8 J"],"c":1,"s":"Spring energy ∝ (compression)². At x/2 the spring energy is ¼ of the initial energy E, so the block's KE there is ¾E.\nThe block stops and the other block (taken to have the same mass 0.1 kg, as in the original problem) moves off at 3 m/s, so all this KE passes to it.\nKE = ½(0.1)(3)² = 0.45 J = ¾E.\nE = 0.45 × 4/3 = 0.6 J.\nAnswer: 0.6 J."},
{"y":"JEE Main 2015 · Online","tp":"pwe","st":"Conservative forces and potential energy curves","q":"A particle is moving in a circle of radius r under the action of a force F = αr² which is directed towards centre of the circle. Total mechanical energy (kinetic energy + potential energy) of the particle is\n(take potential energy = 0 for r = 0)","o":["αr³","{1;2}αr³","{4;3}αr³","{5;6}αr³"],"c":3,"s":"The force supplies the centripetal force: mv²/r = αr², so KE = ½mv² = ½αr³.\nPotential energy (zero at r = 0): U = −∫₀^r F·dr with F = −αr² (towards the centre), so U = ∫₀^r αr² dr = αr³/3.\nTotal energy = ½αr³ + ⅓αr³ = 5αr³/6.\nAnswer: 5αr³/6 (option d)."},
{"y":"JEE Main 2014 · Online","tp":"pwe","st":"Energy on slopes and with friction","q":"A small ball of mass m starts at a point A with speed v₀ and moves along a frictionless track AB as shown. The track BC has coefficient of friction μ. The ball comes to stop at C after travelling a distance L which is","o":["{2h;μ} + {v₀²;2μg}","{h;μ} + {v₀²;2μg}","{h;2μ} + {v₀²;μg}","{h;2μ} + {v₀²;2μg}"],"c":1,"s":"Track AB is frictionless, so the energy at B is ½mv₀² + mgh.\nOn BC friction removes all of it: μmgL = ½mv₀² + mgh.\nDivide by μmg: L = h/μ + v₀²/(2μg).\nAnswer: h/μ + v₀²/(2μg).","fig":{"w":340,"h":180,"alt":"Ball at A on a smooth curved track of height h that curves down to B; the rough horizontal track BC of length L continues to the right.","d":[["p","M60 20 C62 90 85 118 150 120"],["l",150,120,300,120,"B"],["c",60,15,5,"F"],["l",36,20,36,120,"b"],["t",30,74,"h","e"],["t",66,14,"A"],["t",150,138,"B","m"],["t",300,138,"C","m"],["l",150,148,300,148,"b"],["t",225,166,"L","m"]]}},
{"y":"JEE Advanced 2014","tp":"pwv","st":"Loops, beads and other circular tracks","q":"A wire, which passes through the hole in a small bead, is bent in the form of quarter of a circle. The wire is fixed vertically on ground as shown in the figure. The bead is released from near the top of the wire and it slides along the wire without friction. As the bead moves from A to B, the force it applies on the wire is","o":["always radially outwards.","always radially inwards.","radially outwards initially and radially inwards later.","radially inwards initially and radially outwards later."],"c":3,"s":"Let the bead be at angle φ from the top, measured at the centre O. Energy: v² = 2gR(1 − cosφ).\nAlong the radius, taking N as the outward force of the wire on the bead: mg cosφ − N = mv²/R.\nSo N = mg cosφ − 2mg(1 − cosφ) = mg(3cosφ − 2).\nInitially N > 0 (wire pushes bead outwards) and later N < 0 (wire pushes bead inwards).\nBy Newton's third law the bead pushes the wire radially inwards first and radially outwards later.\nAnswer: option d.","fig":{"w":340,"h":200,"alt":"Quarter-circle wire fixed vertically on the ground, with a bead at the top A and the other end B on the ground; the centre of the circle is at the bottom left corner where the angle is 90 degrees.","d":[["l",60,170,60,40,"B"],["l",60,170,200,170,"B"],["p","M60 40 A130 130 0 0 1 190 170"],["c",60,40,6],["t",50,36,"A","e"],["t",196,184,"B"],["t",72,160,"90°","s"]]}},
{"y":"JEE Main 2013 · Online","tp":"pwe","st":"Potential energy and springs","q":"Two springs of force constants 300 N/m (Spring A) and 400 N/m (Spring B) are joined together in series. The combination is compressed by 8.75 cm. The ratio of energy stored in A and B is E_A / E_B. Then E_A / E_B is equal to","o":["{4;3}","{16;9}","{3;4}","{9;16}"],"c":0,"s":"In series the same force F acts on both springs. Energy stored = F²/(2k), so E ∝ 1/k.\nE_A/E_B = k_B/k_A = 400/300 = 4/3.\nThe total compression 8.75 cm is not needed.\nAnswer: 4/3."},
{"y":"AIEEE 2012 · Online","tp":"pww","st":"Graphs of force and work","q":"The force F⃗ = Fî on a particle of mass 2 kg, moving along the x-axis is given in the figure as a function of its position x. The particle is moving with a velocity of 5 m/s along the x-axis at x = 0. What is the kinetic energy of the particle at x = 8 m?","o":["34 J","34.5 J","4.5 J","29.5 J"],"c":3,"s":"Work done = area under the F–x graph. From the figure F falls from 2 N at x = 0 to −1 N at x = 3 m (zero at x = 2), stays −1 N up to x = 4 m, then rises to +3 N at x = 8 m (zero at x = 5).\nAreas: 0–2 m: +2 J. 2–3 m: −0.5 J. 3–4 m: −1 J. 4–5 m: −0.5 J. 5–8 m: +4.5 J.\nTotal work = 2 − 0.5 − 1 − 0.5 + 4.5 = 4.5 J.\nInitial KE = ½(2)(5)² = 25 J, so final KE = 25 + 4.5 = 29.5 J.\nAnswer: 29.5 J.","fig":{"w":340,"h":180,"alt":"Graph of force F in newtons against position x from 0 to 8 m: F falls linearly from 2 N to -1 N at x = 3, stays at -1 N until x = 4, then rises linearly to 3 N at x = 8.","d":[["l",50,150,50,15,"a"],["l",50,100,312,100,"a"],["p","M50 50 L140 125 L170 125 L290 25","B"],["l",80,96,80,104],["t",80,114,"1","ms"],["l",110,96,110,104],["t",110,114,"2","ms"],["l",140,96,140,104],["t",140,114,"3","ms"],["l",170,96,170,104],["t",170,114,"4","ms"],["l",200,96,200,104],["t",200,114,"5","ms"],["l",230,96,230,104],["t",230,114,"6","ms"],["l",260,96,260,104],["t",260,114,"7","ms"],["l",290,96,290,104],["t",290,114,"8","ms"],["l",46,25,54,25],["t",42,29,"3","es"],["l",46,50,54,50],["t",42,54,"2","es"],["l",46,75,54,75],["t",42,79,"1","es"],["l",46,125,54,125],["t",42,129,"-1","es"],["l",46,150,54,150],["t",42,154,"-2","es"],["t",58,12,"F (N)"],["t",314,104,"x (m)"],["t",44,114,"0","es"]]}},
{"y":"AIEEE 2010","tp":"pwe","st":"Conservative forces and potential energy curves","q":"The potential energy function for the force between two atoms in a diatomic molecule is approximately given by U(x) = {a;x¹²} − {b;x⁶}, where a and b are constants and x is the distance between the atoms. If the dissociation energy of the molecule is D = [U(x = ∞) − U_at equilibrium], D is","o":["{b²;6a}","{b²;2a}","{b²;12a}","{b²;4a}"],"c":3,"s":"At equilibrium dU/dx = 0: −12a/x¹³ + 6b/x⁷ = 0, so x⁶ = 2a/b.\nU at equilibrium = a/x¹² − b/x⁶ = a(b²/4a²) − b(b/2a) = b²/4a − b²/2a = −b²/4a.\nU(∞) = 0, so D = 0 − (−b²/4a) = b²/4a.\nAnswer: b²/(4a)."},
{"y":"IIT-JEE 2010","tp":"pww","st":"Graphs of force and work","q":"A block of mass 2 kg is free to move along the x-axis. It is at rest and from t = 0 onwards it is subjected to a time-dependent force F(t) in the x direction. The force F(t) varies with t as shown in the figure. The kinetic energy of the block after 4.5 seconds is","o":["4.50 J","7.50 J","5.06 J","14.06 J"],"c":2,"s":"From the graph F falls linearly from 4 N at t = 0 to 0 at t = 3 s, and continues to −2 N at t = 4.5 s.\nImpulse = area under the F–t graph = ½(4)(3) − ½(1.5)(2) = 6 − 1.5 = 4.5 N s.\nStarting from rest, v = impulse/m = 4.5/2 = 2.25 m/s.\nKE = ½(2)(2.25)² = 5.06 J.\nAnswer: 5.06 J.","fig":{"w":340,"h":110,"alt":"Graph of force F(t) against time: a straight line falling from 4 N at t = 0, crossing zero at t = 3 s and reaching about -2 N at t = 4.5 s.","d":[["l",50,100,50,10,"a"],["l",50,60,312,60,"a"],["l",50,20,230,80,"B"],["l",230,60,230,86,"d"],["t",44,24,"4 N","es"],["t",170,50,"3 s","ms"],["t",230,98,"4.5 s","ms"],["t",58,10,"F(t)"],["t",314,64,"t"],["t",44,74,"O","es"]]}},
{"y":"AIEEE 2008","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"An athlete in the olympic games covers a distance of 100 m in 10 s. His kinetic energy can be estimated to be in the range","o":["2,000 J − 5,000 J","200 J − 500 J","2 × 10⁵ J − 3 × 10⁵ J","20,000 J − 50,000 J"],"c":0,"s":"Speed v = 100/10 = 10 m/s.\nAn athlete's mass is roughly 50 kg to 100 kg.\nKE = ½mv² = ½(50)(100) = 2500 J up to ½(100)(100) = 5000 J.\nThis matches the range 2,000 J to 5,000 J."},
{"y":"IIT-JEE 2008","tp":"pwv","st":"Tension and speed in a circle","q":"A bob of mass M is suspended by a massless string of length L. The horizontal velocity V at position A is just sufficient to make it reach the point B. The angle θ at which the speed of the bob is half of that at A, satisfies","o":["θ = {π;4}","{π;4} < θ < {π;2}","{π;2} < θ < {3π;4}","{3π;4} < θ < π"],"c":3,"s":"To just reach the top B, the speed there satisfies v_B² = gL. Energy from A to B: V² = v_B² + 4gL = 5gL.\nAt angle θ from A the bob has risen L(1 − cosθ). Energy: (V/2)² = V² − 2gL(1 − cosθ).\n5gL/4 = 5gL − 2gL(1 − cosθ), so 1 − cosθ = 15/8 and cosθ = −7/8.\nθ ≈ 151°. This is greater than 135° (3π/4, where cos = −0.707) and less than 180°.\nAnswer: 3π/4 < θ < π.","fig":{"w":340,"h":200,"alt":"Vertical circle of radius L with the bob's lowest point A, top point B, the centre marked, the string at angle theta from the downward vertical, and the horizontal velocity V drawn at A.","d":[["c",170,100,70],["l",170,30,170,170,"d"],["l",170,100,231,135],["c",231,135,5,"F"],["l",170,170,230,170,"a"],["t",236,174,"V"],["t",170,22,"B","m"],["t",170,188,"A","m"],["t",162,142,"L","e"],["t",182,128,"θ","s"]]}},
{"y":"AIEEE 2007","tp":"pwe","st":"Conservation of mechanical energy","q":"A particle is projected at 60° to the horizontal with a kinetic energy K. The kinetic energy at the highest point is","o":["K/2","K","zero","K/4"],"c":3,"s":"The horizontal component of velocity stays constant; the vertical component is zero at the highest point.\nIf the launch speed is u, then K = ½mu². At the top the speed is u cos60° = u/2.\nKE at top = ½m(u/2)² = ¼(½mu²) = K/4.\nAnswer: K/4."},
{"y":"AIEEE 2007","tp":"pwe","st":"Potential energy and springs","q":"A 2 kg block slides on a horizontal floor with a speed of 4 m/s. It strikes an uncompressed spring, and compresses it till the block is motionless. The kinetic friction force is 15 N and spring constant is 10,000 N/m. The spring compresses by","o":["8.5 cm","5.5 cm","2.5 cm","11.0 cm"],"c":1,"s":"Energy balance: initial KE = work against friction + spring energy.\n½(2)(4)² = 15x + ½(10 000)x², i.e. 16 = 15x + 5000x².\n5000x² + 15x − 16 = 0, so x = [−15 + √(225 + 320 000)]/10 000 = (−15 + 566)/10 000 ≈ 0.055 m.\nx ≈ 5.5 cm.\nAnswer: 5.5 cm."},
{"y":"AIEEE 2006","tp":"pwe","st":"Conservative forces and potential energy curves","q":"The potential energy of a 1 kg particle free to move along the x-axis is given by V(x) = ({x⁴;4} − {x²;2}) J. The total mechanical energy is 2 J. Then, the maximum speed (in m/s) is","o":["2","{3;√2}","√2","{1;√2}"],"c":1,"s":"KE = E − V, so the speed is maximum where V is minimum.\ndV/dx = x³ − x = 0 gives x = ±1, where V = ¼ − ½ = −¼ J.\nMaximum KE = 2 − (−¼) = 9/4 J.\n½(1)v² = 9/4, so v² = 9/2 and v = 3/√2 m/s.\nAnswer: 3/√2."},
{"y":"AIEEE 2006","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"A particle of mass 100 g is thrown vertically upwards with a speed of 5 m/s. The work done by the force of gravity during the time the particle goes up is","o":["0.5 J","−0.5 J","−1.25 J","1.25 J"],"c":2,"s":"Work by gravity = change in KE (gravity is the only force).\nThe particle rises until it stops, so ΔKE = 0 − ½(0.1)(5)² = −1.25 J.\nGravity opposes the upward motion, so its work is negative.\nAnswer: −1.25 J."},
{"y":"AIEEE 2006","tp":"pwc","st":"Collisions with springs and energy loss","q":"A bomb of mass 16 kg at rest explodes into two pieces of masses of 4 kg and 12 kg. The velocity of the 12 kg mass is 4 m s⁻¹. The kinetic energy of the other mass is","o":["96 J","144 J","288 J","192 J"],"c":2,"s":"Momentum is conserved and the bomb starts at rest, so the pieces have equal and opposite momentum.\n4 × v = 12 × 4, so the 4 kg piece moves at v = 12 m/s.\nKE = ½(4)(12)² = 288 J.\nAnswer: 288 J."},
{"y":"AIEEE 2006","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"A mass of M kg is suspended by a weightless string. The horizontal force that is required to displace it until the string making an angle of 45° with the initial vertical direction is","o":["Mg(√2 − 1)","Mg(√2 + 1)","Mg√2","{Mg;√2}"],"c":0,"s":"Take a constant horizontal force F that pulls the mass (string length L) until the string is at 45° and the mass is at rest there.\nWork by F = F × (horizontal displacement) = F L sin45°.\nGain in PE = MgL(1 − cos45°).\nWork-energy theorem: F L sin45° = MgL(1 − cos45°), so F = Mg(1 − cos45°)/sin45° = Mg(√2 − 1).\nAnswer: Mg(√2 − 1)."},
{"y":"AIEEE 2006","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"A ball of mass 0.2 kg is thrown vertically upwards by applying a force by hand. If the hand moves 0.2 m while applying the force and the ball goes upto 2 m height further, find the magnitude of the force. Consider g = 10 m/s²","o":["22 N","4 N","16 N","20 N"],"c":0,"s":"The ball starts from rest and is at rest again at the highest point, so total work = 0.\nThe hand pushes with force F over 0.2 m. Gravity acts over the whole rise: 0.2 + 2 = 2.2 m.\nF(0.2) − mg(2.2) = 0, so F(0.2) = 0.2 × 10 × 2.2 = 4.4 J.\nF = 4.4/0.2 = 22 N.\nAnswer: 22 N."},
{"y":"AIEEE 2005","tp":"pwe","st":"Potential energy and springs","q":"The block of mass M moving on the frictionless horizontal surface collides with the spring of spring constant K and compresses it by length L. The maximum momentum of the block after collision is","o":["zero","{ML²;K}","√(MK) L","{KL²;2M}"],"c":2,"s":"The block's KE just before touching the spring becomes spring energy at maximum compression: ½Mv² = ½KL².\nSo v = L√(K/M).\nMomentum = Mv = ML√(K/M) = √(MK) L (this is also the momentum with which it leaves the spring).\nAnswer: √(MK) L.","fig":{"w":340,"h":110,"alt":"A block of mass M on a frictionless horizontal surface moving toward a spring fixed to a wall on the right.","d":[["l",20,80,320,80],["r",60,40,50,40],["t",85,65,"M","m"],["p","M110 60 H140 L146 48 L158 72 L170 48 L182 72 L194 48 L206 72 L212 60 H250"],["l",250,25,250,80,"B"]]}},
{"y":"AIEEE 2004","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"A particle is acted upon by a force of constant magnitude which is always perpendicular to the velocity of the particle, the motion of the particle takes place in a plane. It follows that","o":["its velocity is constant","its acceleration is constant","its kinetic energy is constant","it moves in a straight line."],"c":2,"s":"A force perpendicular to the velocity does no work (power = F⃗·v⃗ = 0).\nBy the work-energy theorem the kinetic energy, and so the speed, stays constant.\nThe direction of velocity keeps changing, so the velocity is not constant; the acceleration changes direction too; the path is a circle, not a straight line.\nAnswer: its kinetic energy is constant."},
{"y":"AIEEE 2004","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"A particle moves in a straight line with retardation proportional to its displacement. Its loss of kinetic energy for any displacement x is proportional to","o":["x²","eˣ","x","logₑ x."],"c":0,"s":"Retardation proportional to displacement: a = −kx, so v dv/dx = −kx.\nIntegrate: ½v² − ½v₀² = −½kx².\nLoss of KE = ½m(v₀² − v²) = ½mkx².\nSo the loss of KE is proportional to x².\nAnswer: x²."},
{"y":"IIT-JEE 2004","tp":"pwe","st":"Conservative forces and potential energy curves","q":"A particle is acted by a force F = kx, where k is a +ve constant. Its potential energy at x = 0 is zero. Which curve correctly represents the variation of potential energy of the block with respect to x?","o":["Graph (a)","Graph (b)","Graph (c)","Graph (d)"],"c":1,"s":"Potential energy is U = −∫F dx = −∫kx dx = −½kx² (with U = 0 at x = 0).\nThis is a parabola opening downwards with its top at the origin, symmetric about the U axis.\nThat is graph (b).\nAnswer: graph (b).","fig":{"w":340,"h":240,"alt":"Four small U versus x graphs: (a) upward parabola with vertex at origin, (b) downward parabola with vertex at origin, (c) straight line rising through origin, (d) straight line falling through origin.","d":[["t",8,16,"(a)"],["l",60,112,60,12,"a"],["l",22,60,152,60,"a"],["t",66,14,"U"],["t",150,74,"x","e"],["p","M40 28 Q60 92 80 28"],["t",178,16,"(b)"],["l",230,112,230,12,"a"],["l",192,60,322,60,"a"],["t",236,14,"U"],["t",320,74,"x","e"],["p","M210 92 Q230 28 250 92"],["t",8,136,"(c)"],["l",60,232,60,132,"a"],["l",22,180,152,180,"a"],["t",66,134,"U"],["t",150,194,"x","e"],["l",30,210,90,150],["t",178,136,"(d)"],["l",230,232,230,132,"a"],["l",192,180,322,180,"a"],["t",236,134,"U"],["t",320,194,"x","e"],["l",200,150,260,210]]}},
{"y":"AIEEE 2003","tp":"pwe","st":"Potential energy and springs","q":"A spring of spring constant 5 × 10³ N/m is stretched initially by 5 cm from the unstretched position. Then the work required to stretch it further by another 5 cm is","o":["12.50 N m","18.75 N m","25.00 N m","6.25 N m"],"c":1,"s":"Work = change in spring energy = ½k(x₂² − x₁²), with x₁ = 0.05 m and x₂ = 0.10 m.\nWork = ½(5000)(0.10² − 0.05²) = 2500 × 0.0075.\nWork = 18.75 N m.\nAnswer: 18.75 N m."},
{"y":"AIEEE 2003","tp":"pww","st":"Statements, matching and subjective","q":"Consider the following two statements.\nA. Linear momentum of a system of particles is zero.\nB. Kinetic energy of a system of particles is zero.\nThen","o":["A does not imply B and B does not imply A","A implies B but B does not imply A","A does not imply B but B implies A","A implies B and B implies A."],"c":2,"s":"If the KE of the system is zero, every particle is at rest, so the total momentum is zero. So B implies A.\nIf the total momentum is zero, the KE need not be zero: two equal masses moving in opposite directions have zero total momentum but non-zero KE. So A does not imply B.\nAnswer: A does not imply B but B implies A."},
{"y":"AIEEE 2002","tp":"pwe","st":"Potential energy and springs","q":"A spring of force constant 800 N/m has an extension of 5 cm. The work done in extending it from 5 cm to 15 cm is","o":["16 J","8 J","32 J","24 J"],"c":1,"s":"Work = ½k(x₂² − x₁²) with x₁ = 0.05 m and x₂ = 0.15 m.\nWork = ½(800)(0.0225 − 0.0025) = 400 × 0.02.\nWork = 8 J.\nAnswer: 8 J."},
{"y":"AIEEE 2002","tp":"pww","st":"Statements, matching and subjective","q":"If mass-energy equivalence is taken into account, when water is cooled to form ice, the mass of water should","o":["increase","remain unchanged","decrease","first increase then decrease."],"c":2,"s":"Cooling water into ice releases energy (latent heat) to the surroundings.\nBy E = mc², a system that loses energy loses mass.\nSo the mass of the water decreases (by a tiny, unmeasurable amount).\nAnswer: decrease."},
{"y":"AIEEE 2002","tp":"pwe","st":"Conservation of mechanical energy","q":"A ball whose kinetic energy is E, is projected at an angle of 45° to the horizontal. The kinetic energy of the ball at the highest point of its flight will be","o":["E","E/√2","E/2","zero"],"c":2,"s":"At the highest point only the horizontal component of velocity remains: v cos45° = v/√2.\nKE at top = ½m(v/√2)² = ½(½mv²) = E/2.\nAnswer: E/2."},
{"y":"IIT-JEE 2002","tp":"pwe","st":"Potential energy and springs","q":"An ideal spring with spring-constant k is hung from the ceiling and a block of mass M is attached to its lower end. The mass is released with the spring initially unstretched. Then the maximum extension in the spring is","o":["{4Mg;k}","{2Mg;k}","{Mg;k}","{Mg;2k}"],"c":1,"s":"At maximum extension x the block is momentarily at rest, so all the lost gravitational PE is stored in the spring.\nMgx = ½kx², so x = 2Mg/k.\n(The block oscillates about the equilibrium extension Mg/k with amplitude Mg/k, so the maximum extension is twice Mg/k.)\nAnswer: 2Mg/k."},
{"y":"IIT-JEE 2000","tp":"pwe","st":"Conservative forces and potential energy curves","q":"A particle, which is constrained to move along the x-axis, is subjected to a force in the same direction which varies with the distance x of the particle from the origin as F(x) = −kx + ax³. Here k and a are positive constants. For x ≥ 0, the graphical form of the potential energy U(x) of the particle is","o":["Graph (a)","Graph (b)","Graph (c)","Graph (d)"],"c":3,"s":"Potential energy: U = −∫F dx = kx²/2 − ax⁴/4 (taking U = 0 at x = 0).\nFor small x the kx²/2 term dominates, so U rises from zero.\nThe force is zero at x = √(k/a), where U is a maximum. For larger x the −ax⁴/4 term wins, so U falls and becomes negative.\nThat is graph (d): rises from the origin, reaches a maximum, then falls through zero.\nAnswer: graph (d).","fig":{"w":340,"h":240,"alt":"Four U(x) versus x graphs: (a) dips below the axis from the origin and curves back up, (b) rises to a hump and stays positive, (c) comes down from large positive values near the axis, has a minimum and a small hump, (d) rises from the origin to a maximum then falls through zero to negative values.","d":[["t",8,16,"(a)"],["l",60,112,60,12,"a"],["l",22,60,152,60,"a"],["t",66,14,"U(x)"],["t",150,74,"x","e"],["p","M60 60 C75 112 125 112 145 56"],["t",178,16,"(b)"],["l",230,112,230,12,"a"],["l",192,60,322,60,"a"],["t",236,14,"U(x)"],["t",320,74,"x","e"],["p","M230 60 C255 20 280 25 320 55"],["t",8,136,"(c)"],["l",60,232,60,132,"a"],["l",22,180,152,180,"a"],["t",66,134,"U(x)"],["t",150,194,"x","e"],["p","M64 132 C66 200 85 224 105 220 C125 216 135 190 150 194"],["t",178,136,"(d)"],["l",230,232,230,132,"a"],["l",192,180,322,180,"a"],["t",236,134,"U(x)"],["t",320,194,"x","e"],["p","M230 180 C245 140 265 140 280 170 S305 220 320 225"]]}},
{"y":"IIT-JEE 1999","tp":"pwe","st":"Potential energy and springs","q":"A spring of force-constant k is cut into two pieces such that one piece is double the length of the other. Then the long piece will have a force-constant of","o":["(2/3)k","(3/2)k","3k","6k"],"c":1,"s":"The force constant of a spring is inversely proportional to its length.\nThe pieces have lengths L/3 and 2L/3.\nShort piece: k₁ = k × L/(L/3) = 3k. Long piece: k₂ = k × L/(2L/3) = (3/2)k.\nAnswer: (3/2)k."},
{"y":"IIT-JEE 1998","tp":"pwv","st":"Tension and speed in a circle","q":"A stone tied to a string of length L is whirled in a vertical circle with the other end of the string at the centre. At a certain instant of time, the stone is at its lowest position, and has a speed u. The magnitude of the change in its velocity as it reaches a position, where the string is horizontal is","o":["√(u² − 2gL)","√(2gL)","√(u² − gL)","√(2(u² − gL))"],"c":3,"s":"At the lowest point the velocity is u, horizontal. At the horizontal-string position the stone has risen L, so v² = u² − 2gL, and the velocity is vertical.\nThe two velocities are perpendicular, so |Δv⃗| = √(u² + v²).\n|Δv⃗| = √(u² + u² − 2gL) = √(2u² − 2gL) = √(2(u² − gL)).\nAnswer: √(2(u² − gL))."},
{"y":"IIT-JEE 1980","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"Two masses of 1 g and 4 g are moving with equal kinetic energies. The ratio of the magnitudes of their momenta is","o":["4 : 1","√2 : 1","1 : 2","1 : 16"],"c":2,"s":"Momentum and KE are related by p = √(2mK). For equal K, p ∝ √m.\np₁/p₂ = √(1/4) = 1/2.\nAnswer: 1 : 2."},
{"y":"JEE Advanced 2020","tp":"pwe","st":"Conservation of mechanical energy","q":"A student skates up a ramp that makes an angle 30° with the horizontal. He/she starts (as shown in the figure) at the bottom of the ramp with speed v₀ and wants to turn around over a semicircular path xyz of radius R during which he/she reaches a maximum height h (at point y) from the ground as shown in the figure. Assume that the energy loss is negligible and the force required for this turn at the highest point is provided by his/her weight only. Then (g is the acceleration due to gravity)","o":["v₀² − 2gh = {1;2}gR","v₀² − 2gh = {√3;2}gR","the centripetal force required at points x and z is zero","the centripetal force required is maximum at points x and z."],"c":[0,3],"s":"At the top point y the centripetal force comes from the component of weight along the slope: mg sin30° = mg/2.\nSo mv_y²/R = mg/2, giving v_y² = gR/2.\nEnergy conservation from the bottom to y: ½mv₀² = ½mv_y² + mgh, so v₀² − 2gh = v_y² = gR/2. Option (a) is true, (b) is false.\nThe speed is smallest at the highest point y and largest at x and z (the lowest points of the arc), so mv²/R is maximum at x and z. It is not zero there, so (c) is false and (d) is true.\nAnswers: (a) and (d).","fig":{"w":340,"h":200,"alt":"Side view of a ramp rising at 30 degrees to the horizontal with height h at its upper end; near the top a semicircular path xyz is drawn on the ramp, with the skater's path arriving at x and leaving at z.","d":[["l",30,180,280,180],["l",30,180,280,36],["l",280,36,280,180],["l",280,36,280,180,"b"],["t",288,112,"h"],["t",64,176,"30°","s"],["l",81,174,211,99,"a"],["l",189,61,100,112],["p","M211 99 A22 22 0 0 0 189 61"],["t",218,112,"x","s"],["t",182,56,"z","es"],["t",224,66,"y","s"]]}},
{"y":"JEE Advanced 2018","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"A particle of mass m is initially at rest at the origin. It is subjected to a force and starts moving along the x-axis. Its kinetic energy K changes with time as dK/dt = γt, where γ is a positive constant of appropriate dimensions. Which of the following statements is (are) true?","o":["The force applied on the particle is constant","The speed of the particle is proportional to time","The distance of the particle from the origin increases linearly with time","The force is conservative"],"c":[0,1,3],"s":"dK/dt = γt gives K = ½γt² (K = 0 at t = 0).\nK = ½mv², so v = t√(γ/m): speed is proportional to time. (b) is true.\nAcceleration = √(γ/m) is constant, so F = ma = √(γm) is constant. (a) is true.\nDistance = ½(acceleration)t² grows as t², not linearly. (c) is false.\nA constant force does work that depends only on displacement (path independent), so it is conservative. (d) is true.\nAnswers: (a), (b) and (d)."},
{"y":"IIT-JEE 2006","tp":"pwe","st":"Energy on slopes and with friction","q":"A small ball starts moving from A over a fixed track as shown in the figure. Surface AB has friction. From A to B the ball rolls without slipping. Surface BC is frictionless. K_A, K_B and K_C are kinetic energies of the ball at A, B and C respectively. Then","o":["h_A > h_C ; K_B > K_C","h_A > h_C ; K_C > K_A","h_A = h_C ; K_B = K_C","h_A < h_C ; K_B > K_C"],"c":[0,1],"s":"Rolling without slipping: friction does no work on AB, so mechanical energy is conserved: K_A + mg h_A = K_B.\nOn the smooth surface BC there is no torque, so the ball keeps spinning at the same rate. At the highest point C only the translational part of K_B has turned into height; the spin energy remains, so K_C > 0.\nHence mg h_C = K_B − K_C < K_B, and since the ball starts (essentially from rest) at A, K_B ≈ mg h_A. So h_A > h_C and K_B > K_C. (a) is true.\nFrom K_A + mg h_A = K_C + mg h_C with h_A > h_C we get K_C > K_A. (b) is true.\nAnswers: (a) and (b).","fig":{"w":340,"h":200,"alt":"A U-shaped fixed track: the ball starts at A on the left at height h_A, moves down through B on the ground, and rises on the right to point C at height h_C.","d":[["l",20,170,320,170,"B"],["p","M60 30 C62 120 110 164 180 164 C250 164 300 100 310 30"],["c",60,22,7],["c",180,157,7],["c",310,22,7],["l",36,170,36,30,"b"],["t",30,100,"h_A","e"],["l",330,170,330,30,"b"],["t",324,100,"h_C","e"],["t",72,16,"A"],["t",180,188,"B","m"],["t",298,16,"C","e"]]}},
{"y":"IIT-JEE 1987","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"A particle is acted upon by a force of constant magnitude which is always perpendicular to the velocity of the particle. The motion of the particle takes place in a plane. It follows that","o":["its velocity is constant","its acceleration is constant","its kinetic energy is constant","it moves in a circular path"],"c":[2,3],"s":"The force is always perpendicular to the velocity, so it does no work (W = F·v dt = 0).\nBy the work-energy theorem the kinetic energy stays constant, so the speed is constant (c is correct).\nThe force only turns the velocity, so the velocity changes in direction and the acceleration changes direction too: (a) and (b) are wrong.\nA force of constant size, always at right angles to the velocity, gives a = F/m = v²/r with constant v, so r is constant: the path is a circle (d is correct).\nCorrect options: (c) and (d)."},
{"y":"JEE Main 2023 · 6 Apr · Shift 1","tp":"pww","st":"Work by a variable force","q":"A particle of mass 10 g moves in a straight line with retardation 2x, where x is the displacement in SI units. Its loss of kinetic energy for above displacement is (10/x)^(−n) J. The value of n will be ______.","n":2,"s":"Loss of kinetic energy = work done against the retarding force.\nF = m × 2x = 0.01 × 2x = 0.02x N.\nLoss = ∫ 0.02x dx = 0.01x² J = (x/10)² J.\n(x/10)² = (10/x)^(−2), so n = 2."},
{"y":"JEE Main 2023 · 6 Apr · Shift 2","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"A body is dropped on ground from a height 'h₁' and after hitting the ground, it rebounds to a height 'h₂'. If the ratio of velocities of the body just before and after hitting ground is 4, then percentage loss in kinetic energy of the body is {x;4}. The value of x is ______.","n":375,"s":"Kinetic energy is proportional to v². The speed ratio is 4, so KE before : KE after = 16 : 1.\nFraction lost = (16 − 1)/16 = 15/16.\nPercentage loss = 15/16 × 100 = 93.75%.\nSet 93.75 = x/4, so x = 375."},
{"y":"JEE Main 2023 · 8 Apr · Shift 1","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"The momentum of a body is increased by 50%. The percentage increase in the kinetic energy of the body is ______ %.","n":125,"s":"KE = p²/(2m), so KE is proportional to p².\nNew momentum = 1.5p, so new KE = (1.5)² × old KE = 2.25 × old KE.\nIncrease = 1.25 times the old KE.\nPercentage increase = 125%."},
{"y":"JEE Main 2023 · 8 Apr · Shift 2","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"A body of mass 5 kg is moving with a momentum of 10 kg m s⁻¹. Now a force of 2 N acts on the body in the direction of its motion for 5 s. The increase in the kinetic energy of the body is ______ J.","n":30,"s":"Impulse = F t = 2 × 5 = 10 kg m/s along the motion.\nFinal momentum = 10 + 10 = 20 kg m/s.\nKE = p²/(2m): initial = 100/10 = 10 J, final = 400/10 = 40 J.\nIncrease in KE = 40 − 10 = 30 J."},
{"y":"JEE Main 2023 · 10 Apr · Shift 1","tp":"pwv","st":"Loops, beads and other circular tracks","q":"A closed circular tube of average radius 15 cm, whose inner walls are rough, is kept in vertical plane. A block of mass 1 kg just fit inside the tube. The speed of block is 22 m/s, when it is introduced at the top of tube. After completing five oscillations, the block stops at the bottom region of tube. The work done by the tube on the block is ______ J.\n(Given g = 10 m/s²)","fig":{"w":300,"h":190,"alt":"Vertical circular tube of average diameter 30 cm with a 1 kg block at its top moving to the right at 22 m/s","d":[["c",150,105,80],["c",150,105,60],["r",140,27,20,16,"f"],["l",160,35,230,35,"a"],["t",236,39,"22 m/s"],["t",150,18,"1 kg","ms"],["l",80,105,220,105,"b"],["t",150,122,"30 cm","m"]]},"n":245,"s":"The tube's normal force does no work, so the work done by the tube is the work of friction on the walls.\nWork-energy theorem from the top (22 m/s) to rest at the bottom: W_tube + mg(2R) = 0 − ½mv².\nKE at the top = ½ × 1 × 22² = 242 J.\nThe block falls through 2R = 0.3 m, so gravity gives mg(2R) = 1 × 10 × 0.3 = 3 J.\nThe tube removes 242 + 3 = 245 J of energy. The work done by the tube is −245 J, so its magnitude is 245 J (the book key gives 245)."},
{"y":"JEE Main 2023 · 12 Apr · Shift 1","tp":"pwp","st":"Power and efficiency","q":"To maintain a speed of 80 km/h by a bus of mass 500 kg on a plane rough road for 4 km distance, the work done by the engine of the bus will be ______ kJ. [The coefficient of friction between tyre of bus and road is 0.04] (Take g = 9.8 m s⁻²)","n":784,"s":"At constant speed the engine force equals friction: F = μmg.\nWith g = 9.8 m/s² (as used in the book key): F = 0.04 × 500 × 9.8 = 196 N.\nWork = F × d = 196 × 4000 = 784000 J.\nWork done by the engine = 784 kJ (the speed 80 km/h is not needed)."},
{"y":"JEE Main 2023 · 13 Apr · Shift 2","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"A car accelerates from rest to u m/s. The energy spent in this process is E J. The energy required to accelerate the car from u m/s to 2u m/s is nE J. The value of n is ______.","n":3,"s":"Energy spent = change in kinetic energy.\nFrom rest to u: E = ½mu² − 0 = ½mu².\nFrom u to 2u: ½m(2u)² − ½mu² = 2mu² − ½mu² = 1.5mu² = 3 × (½mu²) = 3E.\nSo n = 3."},
{"y":"JEE Main 2023 · 24 Jan · Shift 1","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"A spherical body of mass 2 kg starting from rest acquires a kinetic energy of 10000 J at the end of 5ᵗʰ second. The force acted on the body is ______ N.","n":40,"s":"KE = ½mv², so 10000 = ½ × 2 × v², giving v = 100 m/s after 5 s.\nAcceleration a = v/t = 100/5 = 20 m/s².\nForce F = ma = 2 × 20 = 40 N."},
{"y":"JEE Main 2023 · 25 Jan · Shift 1","tp":"pww","st":"Work by a variable force","q":"An object of mass 'm' initially at rest on a smooth horizontal plane starts moving under the action of force F = 2 N. In the process of its linear motion, the angle θ (as shown in figure) between the direction of force and horizontal varies as θ = kx, where k is a constant and x is the distance covered by the object from its initial position. The expression of kinetic energy of the object will be E = {n;k} sin θ. The value of n is ______.","fig":{"w":320,"h":150,"alt":"A block on a smooth horizontal surface pulled by a force F at angle θ above the horizontal","d":[["r",90,70,100,50,"f"],["t",140,100,"m","m"],["l",50,120,300,120],["t",170,138,"Smooth horizontal surface","ms"],["l",190,70,265,35,"a"],["t",270,34,"F⃗"],["l",190,70,290,70,"d"],["t",240,66,"θ","m"]]},"n":2,"s":"The vertical force component does no work on the plane. Only F cos θ moves the block.\nWork-energy theorem: E = ∫ F cos θ dx = ∫ 2 cos(kx) dx.\nE = (2/k) sin(kx) = (2/k) sin θ.\nComparing with E = (n/k) sin θ gives n = 2."},
{"y":"JEE Main 2023 · 29 Jan · Shift 1","tp":"pwe","st":"Conservation of mechanical energy","q":"A 0.4 kg mass takes 8 s to reach ground when dropped from a certain height 'P' above surface of earth. The loss of potential energy in the last second of fall is ______ J.\n(Take, g = 10 m/s²)","n":300,"s":"Distance fallen in 8 s = ½ × 10 × 8² = 320 m.\nDistance fallen in 7 s = ½ × 10 × 7² = 245 m.\nDistance in the last second = 320 − 245 = 75 m.\nLoss of PE = mgh = 0.4 × 10 × 75 = 300 J."},
{"y":"JEE Main 2023 · 31 Jan · Shift 1","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"A lift of mass M = 500 kg is descending with speed of 2 ms⁻¹. Its supporting cable begins to slip thus allowing it to fall with a constant acceleration of 2 ms⁻². The kinetic energy of the lift at the end of fall through to a distance of 6 m will be ______ kJ.","n":7,"s":"Use v² = u² + 2as with u = 2 m/s, a = 2 m/s², s = 6 m.\nv² = 4 + 2 × 2 × 6 = 28 m²/s².\nKE = ½Mv² = ½ × 500 × 28 = 7000 J.\nKE = 7 kJ."},
{"y":"JEE Main 2022 · 28 Jul · Shift 1","tp":"pwe","st":"Potential energy and springs","q":"A block of mass 'm' (as shown in figure) moving with kinetic energy E compresses a spring through a distance 25 cm when, its speed is halved. The value of spring constant of used spring will be nE N m⁻¹ for n = ______.","fig":{"w":280,"h":140,"alt":"A block of mass m moving to the right with kinetic energy E toward a spring fixed to a wall on a smooth surface","d":[["r",60,60,60,50,"f"],["t",90,90,"m","m"],["l",85,50,130,50,"a"],["t",136,54,"E"],["p","M120 85 L135 85 L142 70 L156 100 L170 70 L184 100 L198 70 L212 100 L219 85 L230 85"],["l",230,55,230,110,"B"],["l",40,110,240,110],["t",140,128,"Smooth surface","ms"]]},"n":24,"s":"Initial KE = E. When the speed is halved, KE = E/4, so the spring has absorbed 3E/4.\nEnergy stored in the spring: ½kx² = 3E/4, with x = 0.25 m.\nk = 3E/(2x²) = 3E/(2 × 0.0625) = 24E.\nSo k = nE with n = 24."},
{"y":"JEE Main 2022 · 24 Jun · Shift 1","tp":"pwe","st":"Potential energy and springs","q":"A ball of mass 100 g is dropped from a height h = 10 cm on a platform fixed at the top of a vertical spring (as shown in figure). The ball stays on the platform and the platform is depressed by a distance {h;2}. The spring constant is ______ N m⁻¹.\n(Use g = 10 m s⁻²)","fig":{"w":260,"h":210,"alt":"A ball dropped from height h onto a platform fixed on top of a vertical spring","d":[["c",150,40,7],["l",150,48,150,108,"d"],["t",158,82,"h"],["l",110,110,190,110,"B"],["t",104,114,"Platform","e"],["p","M150 110 L150 120 L160 128 L140 140 L160 152 L140 164 L150 172 L150 185"],["r",120,185,60,8,"F"]]},"n":120,"s":"Take the platform and spring as massless. Total fall of the ball = h + h/2 = 1.5h = 0.15 m.\nEnergy conservation: mg(1.5h) = ½k(h/2)².\n0.1 × 10 × 0.15 = ½ × k × (0.05)².\n0.15 = k × 0.00125, so k = 120 N/m."},
{"y":"JEE Main 2022 · 25 Jun · Shift 1","tp":"pwe","st":"Potential energy and springs","q":"A 0.5 kg block moving at a speed of 12 m s⁻¹ compresses a spring through a distance 30 cm when its speed is halved. The spring constant of the spring will be ______ N m⁻¹.","n":600,"s":"The loss of kinetic energy is stored in the spring.\nLoss = ½ × 0.5 × (12² − 6²) = 0.25 × 108 = 27 J.\n½kx² = 27 with x = 0.3 m: ½ × k × 0.09 = 27.\nk = 27/0.045 = 600 N/m."},
{"y":"JEE Main 2022 · 27 Jun · Shift 1","tp":"pwv","st":"Vertical circle conditions","q":"A pendulum of length 2 m consists of a wooden bob of mass 50 g. A bullet of mass 75 g is fired towards the stationary bob with a speed v. The bullet emerges out of the bob with a speed {v;3} and the bob just completes the vertical circle. The value of v is ______ m s⁻¹.\n(If g = 10 m/s²).","n":10,"s":"The bob just completes the circle, so its speed at the bottom is √(5gL) = √(5 × 10 × 2) = 10 m/s.\nMomentum is conserved in the collision: 0.075v = 0.075(v/3) + 0.05 × 10.\n0.075 × (2v/3) = 0.5, so 0.05v = 0.5.\nv = 10 m/s."},
{"y":"JEE Main 2022 · 28 Jun · Shift 1","tp":"pwv","st":"Tension and speed in a circle","q":"A pendulum is suspended by a string of length 250 cm. The mass of the bob of the pendulum is 200 g. The bob is pulled aside until the string is at 60° with vertical as shown in the figure. After releasing the bob, the maximum velocity attained by the bob will be ______ m s⁻¹. (If g = 10 m s⁻²)","fig":{"w":340,"h":190,"alt":"A pendulum of length 250 cm pulled aside until the string makes 60 degrees with the vertical","d":[["l",140,15,260,15,"B"],["l",180,15,180,165,"d"],["l",180,15,310,90],["c",310,90,7],["c",180,165,7],["t",190,50,"60°"],["t",172,110,"l = 250 cm","e"]]},"n":5,"s":"The speed is maximum at the lowest point.\nHeight fallen = L(1 − cos 60°) = 2.5 × 0.5 = 1.25 m.\nEnergy conservation: ½v² = g × 1.25, so v² = 2 × 10 × 1.25 = 25.\nv = 5 m/s."},
{"y":"JEE Main 2021 · 1 Sep · Shift 2","tp":"pwe","st":"Potential energy and springs","q":"An engine is attached to a wagon through a shock absorber of length 1.5 m. The system with a total mass of 40,000 kg is moving with a speed of 72 km h⁻¹ when the brakes are applied to bring it to rest. In the process of the system being brought to rest, the spring of the shock absorber gets compressed by 1.0 m. If 90% of energy of the wagon is lost due to friction, the spring constant is ______ × 10⁵ N/m.","n":16,"s":"Speed = 72 km/h = 20 m/s.\nInitial KE = ½ × 40000 × 20² = 8 × 10⁶ J.\nThe spring stores the remaining 10%: 8 × 10⁵ J.\n½k(1.0)² = 8 × 10⁵, so k = 16 × 10⁵ N/m.\nThe value is 16."},
{"y":"JEE Main 2021 · 26 Aug · Shift 1","tp":"pwe","st":"Conservation of mechanical energy","q":"A uniform chain of length 3 meter and mass 3 kg overhangs a smooth table with 2 meter laying on the table. If K is the kinetic energy of the chain in joule as it completely slips off the table, then the value of K is ______. (Take g = 10 m s⁻²)","n":40,"s":"Take the table top as the zero of potential energy.\nInitially 1 m (1 kg) hangs, its centre is 0.5 m below: PE = −1 × 10 × 0.5 = −5 J. The part on the table has PE = 0.\nFinally the whole chain hangs, its centre is 1.5 m below: PE = −3 × 10 × 1.5 = −45 J.\nK = loss of PE = 45 − 5 = 40 J."},
{"y":"JEE Main 2021 · 31 Aug · Shift 1","tp":"pwc","st":"Inelastic collisions and coefficient of restitution","q":"A block moving horizontally on a smooth surface with a speed of 40 m s⁻¹ splits into two equal parts. If one of the parts moves at 60 m s⁻¹ in the same direction, then the fractional change in the kinetic energy will be x : 4 where x = ______.","n":1,"s":"Momentum conservation: m × 40 = (m/2) × 60 + (m/2) × v₂, so v₂ = 80 − 60 = 20 m/s.\nInitial KE = ½m(40)² = 800m.\nFinal KE = ½(m/2)(60²) + ½(m/2)(20²) = 900m + 100m = 1000m.\nChange = 200m, fraction = 200m/800m = 1/4 = x/4.\nSo x = 1."},
{"y":"JEE Main 2021 · 20 Jul · Shift 1","tp":"pwe","st":"Potential energy and springs","q":"In a springgun having spring constant 100 N m⁻¹ a small ball 'B' of mass 100 g is put in its barrel (as shown in figure) by compressing the spring through 0.05 m. There should be a box placed at a distance 'd' on the ground so that the ball falls in it. If the ball leaves the gun horizontally at a height of 2 m above the ground. The value of d is ______ m. (g = 10 m s⁻²).","fig":{"w":320,"h":200,"alt":"A spring gun fires a ball horizontally from 2 m above the ground; the ball lands in a box at horizontal distance d","d":[["l",50,25,150,25],["l",50,55,150,55],["l",50,25,50,55],["p","M50 40 L62 40 L67 31 L77 49 L87 31 L97 49 L107 31 L112 40"],["c",119,40,7,"F"],["t",60,15,"Gun"],["t",165,60,"Ball"],["l",35,40,35,170,"b"],["t",30,108,"2 m","e"],["l",30,170,310,170],["p","M126 40 Q198 40 270 170","d"],["r",258,160,24,10],["l",126,40,126,170,"d"],["l",126,185,270,185,"b"],["t",198,181,"d","m"]]},"n":1,"s":"Spring energy = kinetic energy of the ball: ½ × 100 × 0.05² = ½ × 0.1 × v².\n0.125 = 0.05v², so v² = 2.5 and v = √2.5 m/s.\nTime of fall from 2 m: t = √(2h/g) = √(0.4) s.\nd = vt = √(2.5 × 0.4) = √1 = 1 m."},
{"y":"JEE Main 2021 · 25 Jul · Shift 1","tp":"pwv","st":"Tension and speed in a circle","q":"A pendulum bob has a speed of 3 m/s at its lowest position. The pendulum is 50 cm long. The speed of bob, when the length makes an angle of 60° to the vertical will be (g = 10 m/s²) ______ m/s.","n":2,"s":"Height gained at 60° = L(1 − cos 60°) = 0.5 × 0.5 = 0.25 m.\nEnergy conservation: v² = u² − 2gh = 9 − 2 × 10 × 0.25 = 4.\nv = 2 m/s."},
{"y":"JEE Main 2021 · 27 Jul · Shift 2","tp":"pwv","st":"Loops, beads and other circular tracks","q":"A small block slides down from the top of hemisphere of radius R = 3 m as shown in the figure. The height h at which the block will lose contact with the surface of the sphere is ______ m.\n(Assume there is no friction between the block and the hemisphere)","fig":{"w":340,"h":200,"alt":"A block sliding down a smooth hemisphere of radius R centred at O, leaving the surface at point A at height h above the base, with R minus h measured down from the top","d":[["p","M10 175 A120 120 0 0 1 250 175 Z","f"],["r",110,41,40,14,"F"],["l",130,175,130,55,"d"],["t",122,120,"R","e"],["l",130,175,219,95],["l",130,55,300,55,"d"],["l",219,95,300,95,"d"],["l",285,55,285,95,"b"],["t",291,79,"(R − h)","s"],["l",285,95,285,175,"b"],["t",291,138,"h"],["l",219,95,219,150,"a"],["t",224,118,"θ"],["t",130,192,"O","m"],["t",224,90,"A"]]},"n":2,"s":"At the point A the normal force becomes zero: mg cos θ = mv²/R.\nEnergy conservation from the top: v² = 2g(R − h).\nHere cos θ = h/R, so g h/R = 2g(R − h)/R, giving h = 2R − 2h.\n3h = 2R, so h = 2R/3 = 2 × 3/3 = 2 m."},
{"y":"JEE Main 2021 · 18 Mar · Shift 1","tp":"pwv","st":"Loops, beads and other circular tracks","q":"As shown in the figure, a particle of mass 10 kg is placed at a point A. When the particle is slightly displaced to its right, it starts moving and reaches the point B. The speed of the particle at B is x m/s. (Take g = 10 m/s²)\nThe value of 'x' to the nearest integer is ______.","fig":{"w":340,"h":215,"alt":"A smooth track on a horizontal surface; point A is 10 m above the ground, the lowest point B is 5 m above the ground, and C is at the same level as A","d":[["l",40,50,120,50],["p","M120 50 C135 110 160 125 190 125 C225 125 250 90 262 50"],["l",262,50,320,50],["l",40,200,320,200],["l",120,50,120,200,"b"],["t",126,130,"10 m"],["l",190,125,190,200,"b"],["t",196,165,"5 m"],["t",116,42,"A","m"],["t",198,118,"B"],["t",262,42,"C","m"],["t",40,68,"Horizontal surface","s"]]},"n":10,"s":"A is 10 m and B is 5 m above the ground, so the particle falls 5 m from A to B.\nThe track is smooth: ½mv² = mg × 5.\nv² = 2 × 10 × 5 = 100, so v = 10 m/s.\nx = 10 (the mass of 10 kg cancels)."},
{"y":"JEE Main 2021 · 18 Mar · Shift 2","tp":"pwe","st":"Potential energy and springs","q":"A ball of mass 4 kg, moving with a velocity of 10 m s⁻¹, collides with a spring of length 8 m and force constant 100 N m⁻¹. The length of the compressed spring is x m. The value of x, to the nearest integer, is ______.","n":6,"s":"The ball stops when all its KE is stored in the spring: ½mv² = ½kΔ².\n½ × 4 × 100 = ½ × 100 × Δ², so Δ² = 4 and Δ = 2 m.\nCompressed length = 8 − 2 = 6 m.\nx = 6."},
{"y":"JEE Main 2021 · 24 Feb · Shift 2","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"Two solids A and B of mass 1 kg and 2 kg respectively are moving with equal linear momentum. The ratio of their kinetic energies (K.E.)ₐ : (K.E.)_B will be {A;1}, so the value of A will be ______.","n":2,"s":"KE = p²/(2m). With equal momentum, KE is inversely proportional to mass.\n(KE)ₐ/(KE)_B = m_B/mₐ = 2/1.\nSo A/1 = 2/1 and A = 2."},
{"y":"JEE Main 2021 · 25 Feb · Shift 1","tp":"pwe","st":"Conservative forces and potential energy curves","q":"The potential energy U of a diatomic molecule is a function dependent on r (interatomic distance) as U = {α;r¹⁰} − {β;r⁵} − 3; where, α and β are positive constants. The equilibrium distance between two atoms will be (2α/β)^(a/b), where a = ______.","n":1,"s":"At equilibrium the force is zero, so dU/dr = 0.\ndU/dr = −10α/r¹¹ + 5β/r⁶ = 0.\n5β/r⁶ = 10α/r¹¹, so r⁵ = 2α/β.\nr = (2α/β)^(1/5), so a/b = 1/5 and a = 1."},
{"y":"JEE Main 2021 · 25 Feb · Shift 2","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"Two particles having masses 4 g and 16 g respectively are moving with equal kinetic energies. The ratio of the magnitude of their linear momentum is n : 2. The value of n will be ______.","n":1,"s":"p = √(2mK). With equal K, p is proportional to √m.\np₁/p₂ = √(4/16) = 1/2.\nWriting 1/2 = n/2 gives n = 1."},
{"y":"JEE Main 2021 · 26 Feb · Shift 1","tp":"pww","st":"Work by a constant force","q":"A boy pushes a box of mass 2 kg with a force F⃗ = (20î + 10ĵ) N on a frictionless surface. If the box was initially at rest, then ______ m is displacement along the x-axis after 10 s.","n":500,"s":"The x-motion depends only on the x-component of the force: Fₓ = 20 N.\naₓ = 20/2 = 10 m/s².\nStarting from rest: x = ½aₓt² = ½ × 10 × 10² = 500 m."},
{"y":"JEE Main 2020 · 7 Jan · Shift 1","tp":"pwe","st":"Conservation of mechanical energy","q":"A particle (m = 1 kg) slides down a frictionless track (AOC) starting from rest at a point A (height 2 m). After reaching C, the particle continues to move freely in air as a projectile. When it reaches its highest point P (height 1 m), the kinetic energy of the particle (in J) is ______ (Figure drawn is schematic and not to scale; take g = 10 m s⁻²)","fig":{"w":300,"h":200,"alt":"A V-shaped frictionless track AOC: the particle starts at A, 2 m above the lowest point O, leaves the track at C and rises as a projectile to its highest point P at height 1 m","d":[["l",180,190,180,20,"a"],["t",180,14,"Height","ms"],["l",60,50,180,170],["l",180,170,225,140],["p","M225 140 Q243.5 110 262 110","d"],["c",262,110,3,"F"],["t",262,100,"P","m"],["c",60,50,4],["t",54,46,"A","e"],["l",50,50,50,170,"b"],["t",44,115,"2 m","e"],["l",50,170,180,170,"d"],["t",186,184,"O"],["t",232,154,"C","m"]]},"n":10,"s":"The track is frictionless, so mechanical energy is conserved from A to P.\nAt A the particle is at rest at height 2 m; at P it is at height 1 m.\nKE at P = mg(2 − 1) = 1 × 10 × 1 = 10 J.\n(At P the vertical velocity is zero, but the horizontal velocity remains, so KE is not zero.)"},
{"y":"JEE Advanced 2014","tp":"pww","st":"Work-energy theorem and kinetic energy","q":"Consider an elliptically shaped rail PQ in the vertical plane with OP = 3 m and OQ = 4 m. A block of mass 1 kg is pulled along the rail from P to Q with a force of 18 N, which is always parallel to line PQ (see the figure given). Assuming no frictional losses, the kinetic energy of the block when it reaches Q is (n × 10) joules. The value of n is ______.\n(take acceleration due to gravity = 10 m s⁻²)","fig":{"w":260,"h":225,"alt":"Elliptical rail from P on the horizontal axis at 3 m from O to Q on the vertical axis 4 m above O, with the chord PQ dashed","d":[["p","M195 200 A135 180 0 0 0 60 20"],["l",195,200,60,20,"d"],["l",60,200,60,20,"d"],["l",60,200,195,200,"d"],["p","M60 185 L75 185 L75 200"],["r",181,127,10,16,"F"],["l",150,140,132,116,"a"],["t",126,112,"18 N","e"],["t",55,16,"Q","e"],["t",200,204,"P"],["t",50,204,"O","e"],["t",54,110,"4 m","e"],["t",127,218,"3 m","m"]]},"n":5,"s":"The rail's normal force is perpendicular to the motion and does no work.\nPQ = √(3² + 4²) = 5 m, and the 18 N force is along PQ, so the work done by it = 18 × 5 = 90 J (it acts along the chord, with displacement P to Q).\nGravity: the block rises 4 m, so work = −mgh = −1 × 10 × 4 = −40 J.\nKE at Q = 90 − 40 = 50 J = n × 10, so n = 5."},
{"y":"IIT-JEE 2011","tp":"pwe","st":"Energy on slopes and with friction","q":"A block of mass 0.18 kg is attached to a spring of force-constant 2 N/m. The coefficient of friction between the block and the floor is 0.1. Initially the block is at rest and the spring is unstretched. An impulse is given to the block as shown in the figure. The block slides a distance of 0.06 m and comes to rest for the first time. The initial velocity of the block in m/s is V = N/10. Then N is ______.","fig":{"w":300,"h":130,"alt":"A block on a rough floor moving right toward a spring whose far end is fixed to a wall","d":[["l",40,100,260,100],["r",70,60,50,40,"f"],["l",75,48,115,48,"a"],["p","M120 80 L140 80 L148 65 L162 95 L176 65 L190 95 L204 65 L212 80 L240 80"],["l",240,55,240,100,"B"]]},"n":4,"s":"Energy given to the block is used against friction and stored in the spring.\n½mV² = μmg x + ½kx² with x = 0.06 m.\nFriction work = 0.1 × 0.18 × 10 × 0.06 = 0.0108 J. Spring energy = ½ × 2 × 0.06² = 0.0036 J.\n½ × 0.18 × V² = 0.0144, so V² = 0.16 and V = 0.4 m/s = 4/10.\nSo N = 4."},
{"y":"JEE Advanced 2015","tp":"pwe","st":"Statements, matching and subjective","q":"A particle of unit mass is moving along the x-axis under the influence of a force and its total energy is conserved. Four possible forms of the potential energy of the particle are given in column I (a and U₀ are constants). Match the potential energies in column I to the corresponding statement(s) in column II.\nColumn I\n(a) U₁(x) = {U₀;2}[1 − (x/a)²]²\n(b) U₂(x) = {U₀;2}(x/a)²\n(c) U₃(x) = {U₀;2}(x/a)² exp[−(x/a)²]\n(d) U₄(x) = {U₀;2}[x/a − {1;3}(x/a)³]\nColumn II\n(p) The force acting on the particle is zero at x = a.\n(q) The force acting on the particle is zero at x = 0.\n(r) The force acting on the particle is zero at x = −a.\n(s) The particle experiences an attractive force towards x = 0 in the region |x| < a.\n(t) The particle with total energy {U₀;4} can oscillate about the point x = −a.","a":"(a) → (p, q, r, t); (b) → (q, s); (c) → (p, q, r, s); (d) → (p, r, t)","s":"Force F = −dU/dx. Zero force at a point means dU/dx = 0 there.\n(a) dU/dx is proportional to x(1 − x²/a²): zero at 0, ±a (p, q, r). U₁(0) = U₀/2 is a hump; U₁(±a) = 0 are minima, so with energy U₀/4 (below U₀/2) it oscillates about x = −a (t).\n(b) dU/dx is proportional to x: zero only at x = 0 (q). U increases with |x|, so the force points to the origin (s).\n(c) dU/dx is proportional to x(1 − x²/a²) exp(−x²/a²): zero at 0, ±a (p, q, r). U increases with |x| for |x| < a, so the force is attractive towards 0 (s). Its peaks at x = ±a are only U₀/(2e) < U₀/4, so a particle of energy U₀/4 is not trapped near −a (no t).\n(d) dU/dx = (U₀/2a)(1 − x²/a²): zero at ±a (p, r), not at 0. U increases for |x| < a, so the force pushes away from the middle at x < 0 (no s). x = −a is a minimum with U = −U₀/3 and the maximum at x = +a is U₀/3 > U₀/4, so oscillation about −a is possible (t)."},
{"y":"JEE Main 2025 · 28 Jan · Shift 1","tp":"pwe","st":"Statements, matching and subjective","q":"Given below are two statements: one is labelled as Assertion A and the other is labelled as Reason R\nAssertion A: In a central force field, the work done is independent of the path chosen.\nReason R: Every force encountered in mechanics does not have an associated potential energy.\nIn the light of the above statements, choose the most appropriate answer the options given below","o":["Both A and R are true but R is not the correct explanation of A.","A is true but R is false","A is false but R is true","Both A and R are true and R is the correct explanation of A."],"c":0,"s":"A central force is a conservative force, so the work it does depends only on the end points, not on the path. A is true.\nR is also true: non-conservative forces such as friction have no potential energy.\nBut the reason for A is that the central force is conservative, not that some forces lack potential energy. R does not explain A.\nAnswer: both true, R is not the correct explanation of A."},
{"y":"JEE Main 2023 · 12 Apr · Shift 1","tp":"pww","st":"Statements, matching and subjective","q":"Given below are two statements:\nStatement I: A truck and a car moving with same kinetic energy are brought to rest by applying breaks which provides equal retarding forces. Both come to rest in equal distance.\nStatement II: A car moving towards east takes a turn and moves towards north, the speed remains unchanged. The acceleration of the car is zero.\nIn the light of given statements, choose the most appropriate answer from the options given below.","o":["Both Statement I and Statement II are correct.","Statement I is incorrect and Statement-II is correct.","Both Statement I and Statement II are incorrect.","Statement I is correct but Statement II is incorrect."],"c":3,"s":"Statement I: work done by the retarding force = initial KE, so F × d = KE.\nBoth have the same KE and the same F, so the stopping distance d = KE/F is the same. Statement I is correct.\nStatement II: the speed is unchanged but the direction changes, so the velocity changes. Hence the acceleration is not zero. Statement II is incorrect.\nAnswer: I is correct but II is incorrect."},
{"y":"AIEEE 2012","tp":"pwe","st":"Statements, matching and subjective","q":"This question has Statement 1 and Statement 2. Of the four choices given after the statements, choose the one that best describes the two statements. If two springs S₁ and S₂ of force constants k₁ and k₂, respectively, are stretched by the same force, it is found that more work is done on spring S₁ than on spring S₂.\nStatement 1: If stretched by the same amount, work done on S₁, will be more than that on S₂.\nStatement 2: k₁ < k₂.","o":["Statement 1 is true, Statement 2 is false.","Statement 1 is true, Statement 2 is true, Statement 2 is the correct explanation of Statement 1.","Statement 1 is true, Statement 2 is true, Statement 2 is not the correct explanation of Statement 1.","Statement 1 is false, Statement 2 is true."],"c":3,"s":"Same force F: the extension is x = F/k and the work is W = ½Fx = F²/(2k).\nMore work on S₁ means k₁ < k₂, so Statement 2 is true.\nSame extension x: W = ½kx², which is larger for the stiffer spring, S₂ (k₂ > k₁). So the work on S₁ is less. Statement 1 is false.\nAnswer: Statement 1 false, Statement 2 true."},
{"y":"IIT-JEE 2002","tp":"pwv","st":"Statements, matching and subjective","q":"A spherical ball of mass m is kept at the highest point in the space between two fixed, concentric spheres A and B (see figure). The smaller sphere A has a radius R and the space between the two spheres has a width d. The ball has a diameter very slightly less than d. All surfaces are frictionless. The ball is given a gentle push (towards the right in the figure). The angle made by the radius vector of the ball with the upward vertical is denoted by θ (shown in the figure).\n(a) Express the total normal reaction force exerted by the sphere on the ball as a function of angle θ.\n(b) Let N_A and N_B denote the magnitudes of the normal reaction forces on the ball exerted by the sphere A and B respectively. Sketch the variations of N_A and N_B as functions of cosθ in the range 0 ≤ θ ≤ π by drawing two separate graphs taking cosθ on the horizontal axes.","fig":{"w":340,"h":210,"alt":"Two concentric spheres with centre O; the smaller sphere A has radius R, the gap between the spheres has width d, and a ball between them has its radius vector at angle θ to the upward vertical","d":[["c",170,110,60],["c",170,110,80],["l",170,110,170,25,"d"],["l",170,110,205,49],["c",205,49,5,"F"],["t",178,82,"θ"],["t",176,122,"O"],["l",170,110,128,152],["t",142,138,"R","e"],["l",90,110,110,110,"b"],["t",100,104,"d","m"],["t",262,36,"Sphere B"],["l",262,44,241,68,"a"],["t",250,186,"Sphere A"],["l",250,178,214,154,"a"]]},"a":"(a) N = mg(3cosθ − 2)\n(b) (i) for θ ≤ cos⁻¹(2/3): N_B = 0, N_A = mg(3cosθ − 2); (ii) for θ > cos⁻¹(2/3): N_A = 0, N_B = mg(2 − 3cosθ)","s":"Let r = R + d/2 be the radius of the ball's path. Starting from the top at rest: v² = 2gr(1 − cosθ) (energy conservation).\nRadial equation (inward positive): mg cosθ − N = mv²/r, so N = mg cosθ − 2mg(1 − cosθ) = mg(3cosθ − 2).\nWhile cosθ > 2/3 the ball presses on the inner sphere A (N positive, outwards on the ball), so N_A = mg(3cosθ − 2) and N_B = 0.\nAt cosθ = 2/3 the force is zero. After that the ball needs an inward force, which only the outer sphere B can give: N_B = −N = mg(2 − 3cosθ), and N_A = 0.\nGraph of N_A against cosθ: zero for cosθ from −1 up to 2/3, then a straight line rising to mg at cosθ = 1.\nGraph of N_B against cosθ: a straight line starting at 5mg at cosθ = −1 and falling to zero at cosθ = 2/3, then zero up to cosθ = 1."},
{"y":"IIT-JEE 1985","tp":"pwe","st":"Statements, matching and subjective","q":"A string, with one end fixed on a rigid wall, passing over a fixed frictionless pulley at a distance of 2 m from the wall, has a point mass M = 2 kg attached to it at a distance of 1 m from the wall. A mass m = 0.5 kg attached at the free end is held at rest so that the string is horizontal between the wall and the pulley and vertical beyond the pulley. What will be the speed with which the mass M will hit the wall when the mass m is released?","fig":{"w":300,"h":185,"alt":"A string fixed to a wall passes horizontally over a pulley 2 m from the wall; mass M sits on the string 1 m from the wall and mass m hangs vertically from the free end","d":[["l",40,10,40,170,"B"],["l",40,40,220,40],["c",220,50,10],["l",230,50,230,140],["r",220,140,20,20,"f"],["t",246,155,"m"],["r",120,28,20,12,"f"],["t",130,22,"M","m"],["l",40,80,130,80,"b"],["t",85,76,"1 m","m"],["l",40,105,220,105,"b"],["t",130,101,"2 m","m"]]},"a":"3.35 m/s","s":"M is fixed to the string 1 m from the wall, so it moves on a circle of radius 1 m about the wall end. It hits the wall at the point 1 m directly below the fixing point, where its velocity is horizontal.\nThere the string from M to the pulley has length √(2² + 1²) = √5 m (before it was 1 m), so m rises by √5 − 1 = 1.236 m. M falls by 1 m.\nThe string direction makes cos φ = 2/√5 with M's velocity, so v_m = v cos φ = 2v/√5.\nEnergy: Mg(1) − mg(√5 − 1) = ½Mv² + ½m(2v/√5)².\nWith g = 9.8: 19.6 − 6.06 = 13.54 J = v²(1 + 0.2) = 1.2v², so v ≈ 3.36 m/s, which matches the book answer 3.35 m/s (g = 10 gives 3.39 m/s)."},
{"y":"IIT-JEE 1983","tp":"pwe","st":"Statements, matching and subjective","q":"A 0.5 kg block slides from the point A (see fig) on a horizontal track with an initial speed of 3 m/s towards a weightless horizontal spring of length 1 m and force constant 2 newton/m. The part AB of the track is frictionless and the part BC has the co-efficient of static and kinetic friction as 0.22 and 0.2 respectively. If the distances AB and BD are 2 m and 2.14 m respectively, find the total distance through which the block moves before it comes to rest completely.\n(Take g = 10 m/s²).","fig":{"w":300,"h":130,"alt":"A block at A moving right at 3 m/s on a horizontal track; AB is smooth, then the rough part BC; the free end of a horizontal spring starts at D and its other end is fixed to a wall at C","d":[["l",30,100,270,100],["r",40,70,36,30,"f"],["l",45,58,90,58,"a"],["t",95,62,"3 m/s","s"],["t",58,116,"A","m"],["l",130,95,130,105],["t",130,116,"B","m"],["l",207,95,207,105],["t",207,116,"D","m"],["p","M207 80 L212 80 L216 70 L222 90 L228 70 L234 90 L240 80 L250 80"],["l",250,60,250,100,"B"],["t",250,116,"C","m"]]},"a":"4.24 m","s":"AB is smooth, so the block reaches B with 3 m/s. Friction acts from B onwards (kinetic μ = 0.2): f = 0.2 × 0.5 × 10 = 1 N.\nKE at B = ½ × 0.5 × 9 = 2.25 J. Work against friction over BD = 1 × 2.14 = 2.14 J.\nKE on reaching D (spring end) = 2.25 − 2.14 = 0.11 J.\nCompression x of the spring: 0.11 = ½kx² + fx = x² + x, so x² + x − 0.11 = 0, giving x = 0.1 m.\nSpring force at this point = kx = 0.2 N, less than the maximum static friction 0.22 × 0.5 × 10 = 1.1 N, so the block stays at rest.\nTotal distance = 2 + 2.14 + 0.1 = 4.24 m."},
{"y":"IIT-JEE 1982","tp":"pwe","st":"Statements, matching and subjective","q":"Two blocks A and B are connected to each other by a string and a spring; the string passes over a frictionless pulley as shown in the figure. Block B slides over the horizontal top surface of a stationary block C and the block A slides along the vertical side of C, both with the same uniform speed. The co-efficient of friction between the surfaces of blocks is 0.2. Force constant of the spring is 1960 newton/m. If mass of block A is 2 kg, calculate the mass of block B and the energy stored in the spring.","fig":{"w":300,"h":180,"alt":"Block B on top of a large fixed block C is joined by a string over a pulley at the top right corner to a spring, which hangs down to block A sliding along the vertical right side of C","d":[["r",60,40,150,130,"f"],["r",80,15,40,25],["t",100,34,"B","m"],["l",80,8,125,8,"a"],["l",120,28,214,28],["c",214,36,8],["l",222,36,222,60],["p","M222 60 L222 70 L230 76 L214 88 L230 100 L214 108 L222 114 L222 120"],["r",212,120,22,22],["t",223,136,"A","m"],["l",245,120,245,150,"a"],["t",135,110,"C","m"]]},"a":"Mass of B = 10 kg; energy stored in the spring = 0.098 J","s":"A moves down at uniform speed and is not pressed against C (no normal force, so no friction on A). So the spring tension T balances its weight: T = m_A g = 2 × 9.8 = 19.6 N.\nB also moves at uniform speed, so the tension equals the friction on B: T = μ m_B g.\n19.6 = 0.2 × m_B × 9.8, so m_B = 10 kg.\nExtension of the spring x = T/k = 19.6/1960 = 0.01 m.\nEnergy stored = ½kx² = ½ × 1960 × (0.01)² = 0.098 J."},
{"y":"IIT-JEE 1980","tp":"pww","st":"Statements, matching and subjective","q":"The displacement x of a particle moving in one dimension, under the action of a constant force is related to the time t by the equation t = √x + 3 where x is in metre and t in second. Find\n(i) The displacement of the particle when its velocity is zero, and\n(ii) The work done by the force in the first 6 second.","a":"(i) zero   (ii) zero","s":"From t = √x + 3 we get x = (t − 3)².\nVelocity v = dx/dt = 2(t − 3). The velocity is zero at t = 3 s, where x = 0. So (i) the displacement is zero.\nAt t = 0: v = −6 m/s. At t = 6 s: v = +6 m/s. The speed is the same, so the kinetic energy is the same.\nBy the work-energy theorem, work in the first 6 s = change in KE = 0. So (ii) the work done is zero.\n(The acceleration is constant, 2 m/s², as the problem says the force is constant.)"},
{"y":"JEE Main 2025 · 7 Apr · Shift 1","tp":"pwp","st":"Variable power and vehicles","q":"An object of mass 1000 g experiences a time dependent force F⃗ = (2tî + 3t²ĵ) N. The power generated by the force at time t is","o":["(2t² + 3t³) W","(2t² + 18t³) W","(2t³ + 3t⁵) W","(3t³ + 5t⁵) W"],"c":2,"s":"Mass = 1 kg, so a⃗ = F⃗/m = 2tî + 3t²ĵ.\nStarting from rest: v⃗ = ∫a⃗ dt = t²î + t³ĵ.\nPower P = F⃗·v⃗ = (2t)(t²) + (3t²)(t³) = 2t³ + 3t⁵ watt."},
{"y":"JEE Main 2025 · 28 Jan · Shift 2","tp":"pwp","st":"Power and efficiency","q":"A body of mass 4 kg is placed on a plane at a point P having coordinate (3, 4) m. Under the action of force F⃗ = (2î + 3ĵ)N, it moves to a new point Q having coordinates (6, 10) m in 4 sec. The average power and instantaneous power at the end of 4 sec are in the ratio of","o":["13 : 6","6 : 13","1 : 2","4 : 3"],"c":1,"s":"Displacement = (3î + 6ĵ) m. Work = F⃗·d⃗ = 2 × 3 + 3 × 6 = 24 J.\nAverage power = 24/4 = 6 W.\nAcceleration = F/m = (0.5î + 0.75ĵ) m/s². Taking the body to start from rest, v⃗ = a⃗t = (2î + 3ĵ) m/s at t = 4 s.\nInstantaneous power = F⃗·v⃗ = 2 × 2 + 3 × 3 = 13 W.\nRatio average : instantaneous = 6 : 13."},
{"y":"JEE Main 2025 · 29 Jan · Shift 2","tp":"pwp","st":"Power and efficiency","q":"A sand dropper drops sand of mass m(t) on a conveyer belt at a rate proportional to the square root of speed (v) of the belt, i.e., {dm;dt} ∝ √v, if P is the power delivered to run the belt at constant speed then which of the following relationships is true?","o":["P ∝ v","P ∝ √v","P² ∝ v⁵","P² ∝ v³"],"c":2,"s":"Sand dropped on the belt must be brought to the belt's speed v, so the force needed is F = v (dm/dt) (rate of change of momentum).\nPower P = F v = v² (dm/dt).\nWith dm/dt ∝ √v: P ∝ v² × v^(1/2) = v^(5/2).\nSquaring: P² ∝ v⁵."},
{"y":"JEE Main 2024 · 5 Apr · Shift 2","tp":"pwp","st":"Variable power and vehicles","q":"A body is moving unidirectionally under the influence of a constant power source. Its displacement in time t is proportional to","o":["t²","t^(3/2)","t^(2/3)","t"],"c":1,"s":"Constant power P means the work done in time t is Pt.\nSo ½mv² = Pt and v = √(2Pt/m), which is proportional to t^(1/2).\nDisplacement s = ∫v dt, which is proportional to t^(3/2).\nAnswer: t^(3/2)."},
{"y":"JEE Main 2024 · 31 Jan · Shift 2","tp":"pwp","st":"Power and efficiency","q":"A body of mass 2 kg begins to move under the action of a time dependent force given by F⃗ = (6t î + 6t² ĵ) N. The power developed by the force at this time t is given by","o":["(3t³ + 6t⁵) W","(6t⁴ + 9t⁵) W","(9t⁵ + 6t³) W","(9t³ + 6t⁵) W"],"c":3,"s":"Acceleration a = F/m = (3t î + 3t² ĵ) m/s².\nVelocity (from rest) v = ∫a dt = (1.5t² î + t³ ĵ) m/s.\nPower P = F·v = (6t)(1.5t²) + (6t²)(t³).\nP = 9t³ + 6t⁵ watt.\nAnswer: (9t³ + 6t⁵) W."},
{"y":"JEE Main 2023 · 13 Apr · Shift 1","tp":"pwp","st":"Pumps, lifts and flow","q":"The ratio of powers of two motors is {3√x;√x+1}, that are capable of raising 300 kg water in 5 minutes and 50 kg water in 2 minutes respectively from a well of 100 m deep. The value of x will be","o":["16","2","4","2.4"],"c":0,"s":"Power = mgh / t.\nP₁ = 300 × g × 100 / 300 s = 100g.\nP₂ = 50 × g × 100 / 120 s = {125g;3}.\nRatio P₁/P₂ = 100 × 3 / 125 = {12;5}.\nSo {3√x;√x+1} = {12;5}, giving 15√x = 12√x + 12, so √x = 4 and x = 16."},
{"y":"JEE Main 2022 · 27 Jul · Shift 1","tp":"pwp","st":"Power and efficiency","q":"Sand is being dropped from a stationary dropper at a rate of 0.5 kg s⁻¹ on a conveyor belt moving with a velocity of 5 m s⁻¹. The power needed to keep the belt moving with the same velocity will be","o":["1.25 W","2.5 W","6.25 W","12.5 W"],"c":3,"s":"The belt must give each falling grain a speed of 5 m/s.\nForce needed F = v × (dm/dt) = 5 × 0.5 = 2.5 N.\nPower P = F v = 2.5 × 5 = 12.5 W.\n(Half of this becomes kinetic energy of the sand, the rest is lost as heat by friction.)\nAnswer: 12.5 W."},
{"y":"JEE Main 2022 · 28 Jun · Shift 1","tp":"pwp","st":"Power and efficiency","q":"A particle of mass m is moving in a circular path of constant radius r such that its centripetal acceleration (a) is varying with time t as a = k²rt², where k is a constant. The power delivered to the particle by the force acting on it is given as","o":["zero","mkr²t²","mk²r²t","mk²rt"],"c":2,"s":"Centripetal acceleration v²/r = k²rt², so v = krt.\nTangential acceleration = dv/dt = kr, so tangential force = mkr.\nThe centripetal force does no work (it is perpendicular to v).\nPower = (tangential force) × v = mkr × krt = mk²r²t.\nAnswer: mk²r²t."},
{"y":"JEE Main 2022 · 28 Jun · Shift 2","tp":"pwp","st":"Pumps, lifts and flow","q":"Water falls from a 40 m high dam at the rate of 9 × 10⁴ kg per hour. Fifty percentage of gravitational potential energy can be converted into electrical energy. Using this hydroelectric energy number of 100 W lamps, that can be lit, is (Take g = 10 m s⁻²)","o":["25","50","100","18"],"c":1,"s":"Mass flow = 9 × 10⁴ kg / 3600 s = 25 kg/s.\nPower from falling water = (dm/dt) g h = 25 × 10 × 40 = 10000 W.\nElectrical power = 50% of this = 5000 W.\nNumber of lamps = 5000 / 100 = 50.\nAnswer: 50."},
{"y":"JEE Main 2021 · 20 Jul · Shift 2","tp":"pwp","st":"Variable power and vehicles","q":"A body at rest is moved along a horizontal straight line by a machine delivering a constant power. The distance moved by the body in time t is proportional to","o":["t^(3/2)","t^(1/2)","t^(3/4)","t^(1/4)"],"c":0,"s":"Constant power P gives ½mv² = Pt, so v ∝ t^(1/2).\nDistance s = ∫v dt ∝ t^(3/2).\nAnswer: t^(3/2)."},
{"y":"JEE Main 2021 · 27 Jul · Shift 2","tp":"pwp","st":"Variable power and vehicles","q":"An automobile of mass m accelerates starting from origin and initially at rest, while the engine supplies constant power P. The position is given as a function of time by","o":["√{8P;9m} t^(3/2)","√{9P;8m} t^(3/2)","√{8P;9m} t^(2/3)","√{9m;8P} t^(3/2)"],"c":0,"s":"Work-energy: ½mv² = Pt, so v = √(2P/m) t^(1/2).\nPosition x = ∫v dt = √(2P/m) × {2;3} t^(3/2).\nPut the factor inside the root: {2;3}√(2P/m) = √{4 × 2P;9m} = √{8P;9m}.\nSo x = √{8P;9m} t^(3/2).\nAnswer: the first option."},
{"y":"JEE Main 2020 · 3 Sep · Shift 2","tp":"pwp","st":"Variable power and vehicles","q":"A particle is moving unidirectionally on a horizontal plane under the action of a constant power supplying energy source. The displacement (s) – time (t) graph that describes the motion of the particle is (graphs are drawn schematically and are not to scale)","fig":{"w":340,"h":225,"alt":"Four small s versus t graphs: (a) a straight line through the origin, (b) a curve starting flat and bending steadily upward, (c) a horizontal line, (d) a curve rising steeply and then flattening.","d":[["t",100,16,"(a)","m"],["l",25,100,25,28,"a"],["l",25,100,150,100,"a"],["t",19,32,"s","es"],["t",152,104,"t","s"],["l",25,100,115,42],["t",270,16,"(b)","m"],["l",195,100,195,28,"a"],["l",195,100,320,100,"a"],["t",189,32,"s","es"],["t",322,104,"t","s"],["p","M195 100 Q255 98 300 40"],["t",100,128,"(c)","m"],["l",25,208,25,140,"a"],["l",25,208,150,208,"a"],["t",19,144,"s","es"],["t",152,212,"t","s"],["l",25,165,115,165],["t",270,128,"(d)","m"],["l",195,208,195,140,"a"],["l",195,208,320,208,"a"],["t",189,144,"s","es"],["t",322,212,"t","s"],["p","M195 208 Q205 168 290 165"]]},"o":["Graph (a)","Graph (b)","Graph (c)","Graph (d)"],"c":1,"s":"Constant power gives ½mv² = Pt, so v ∝ t^(1/2) and s ∝ t^(3/2).\nSo s starts at zero with zero slope (the body starts from rest).\nThe slope (the speed) keeps increasing, so the curve bends upward, with no straight or flattening part.\nThis matches graph (b)."},
{"y":"JEE Main 2020 · 7 Jan · Shift 1","tp":"pwp","st":"Pumps, lifts and flow","q":"A 60 HP electric motor lifts an elevator having a maximum total load capacity of 2000 kg. If the frictional force on the elevator is 4000 N, the speed of the elevator at full load is close to (1 HP = 746 W, g = 10 m s⁻²)","o":["1.5 m s⁻¹","1.7 m s⁻¹","2.0 m s⁻¹","1.9 m s⁻¹"],"c":3,"s":"Motor power = 60 × 746 = 44760 W.\nForce needed at constant speed = weight + friction = 2000 × 10 + 4000 = 24000 N.\nSpeed v = P / F = 44760 / 24000 ≈ 1.87 m/s.\nThis is close to 1.9 m/s."},
{"y":"JEE Main 2020 · 7 Jan · Shift 2","tp":"pwp","st":"Pumps, lifts and flow","q":"An elevator in a building can carry a maximum of 10 persons, with the average mass of each person being 68 kg. The mass of the elevator itself is 920 kg and it moves with a constant speed of 3 m/s. The frictional force opposing the motion is 6000 N. If the elevator is moving up with its full capacity, the power delivered by the motor to the elevator (g = 10 m/s²) must be at least","o":["48000 W","66000 W","62360 W","56300 W"],"c":1,"s":"Total mass = 10 × 68 + 920 = 1600 kg, so weight = 16000 N.\nAt constant speed the motor force = weight + friction = 16000 + 6000 = 22000 N.\nPower = F v = 22000 × 3 = 66000 W.\nAnswer: 66000 W."},
{"y":"JEE Main 2016 · Online","tp":"pwp","st":"Power and efficiency","q":"A car of weight W is on an inclined road that rises by 100 m over a distance of 1 km and applies a constant frictional force W/20 on the car. While moving uphill on the road at a speed of 10 m s⁻¹, the car needs power P. If it needs power P/2 while moving downhill at speed v then value of v is","o":["20 m s⁻¹","5 m s⁻¹","15 m s⁻¹","10 m s⁻¹"],"c":2,"s":"The slope gives sinθ = 100/1000 = 0.1, so the gravity component along the road is 0.1W.\nUphill: force = 0.1W + 0.05W = 0.15W, so P = 0.15W × 10 = 1.5W.\nDownhill: gravity pulls down the road with 0.1W and friction opposes with 0.05W, so the net force the car must supply has magnitude 0.1W − 0.05W = 0.05W.\nPower P/2 = 0.75W = 0.05W × v, so v = 15 m/s.\nAnswer: 15 m/s (as given in the official key)."},
{"y":"JEE Main 2016 · Online","tp":"pwp","st":"Power and efficiency","q":"A particle of mass M is moving in a circle of fixed radius R in such a way that its centripetal acceleration at time t is given by n²Rt² where n is a constant. The power delivered to the particle by the force acting on it, is","o":["½Mn²R²t²","Mn²R²t","MnR²t²","MnR²t"],"c":1,"s":"v²/R = n²Rt², so v = nRt.\nTangential acceleration = dv/dt = nR, so tangential force = MnR.\nThe centripetal force does no work.\nPower = MnR × nRt = Mn²R²t.\nAnswer: Mn²R²t."},
{"y":"AIEEE 2005","tp":"pwp","st":"Power and efficiency","q":"A body of mass m is accelerated uniformly from rest to a speed v in a time T. The instantaneous power delivered to the body as a function of time is given by","o":["½{mv²;T²} t","½{mv²;T²} t²","{mv²;T²} t","{mv²;T²} t²"],"c":2,"s":"Uniform acceleration a = v/T, so the force is F = mv/T.\nSpeed at time t is v(t) = (v/T) t.\nInstantaneous power P = F v(t) = (mv/T)(v t/T) = {mv²;T²} t.\nAnswer: (mv²/T²) t."},
{"y":"IIT-JEE 2000","tp":"pwp","st":"Pumps, lifts and flow","q":"A wind-powered generator converts wind energy into electrical energy. Assume that the generator converts a fixed fraction of the wind energy intercepted by its blades into electrical energy. For wind speed v, the electrical power output will be proportional to","o":["v","v²","v³","v⁴"],"c":2,"s":"Air passing the blades per second has mass = ρ A v.\nKinetic energy carried per second = ½ (ρ A v) v² = ½ ρ A v³.\nThe electrical output is a fixed fraction of this, so P ∝ v³.\nAnswer: v³."},
{"y":"IIT-JEE 1980","tp":"pwp","st":"Power and efficiency","q":"If a machine is lubricated with oil","o":["the mechanical advantage of the machine increases","the mechanical efficiency of the machine increases.","both its mechanical advantage and efficiency increase","its efficiency increases, but its mechanical advantage decreases."],"c":1,"s":"Oil reduces friction between the moving parts.\nLess energy is wasted as heat, so the useful output work is closer to the input work, and the efficiency increases.\nThe mechanical advantage is treated as fixed by the geometry of the machine, so it is not the quantity that changes.\nAnswer: the mechanical efficiency increases."},
{"y":"JEE Main 2023 · 10 Apr · Shift 2","tp":"pwp","st":"Pumps, lifts and flow","q":"If the maximum load carried by an elevator is 1400 kg (600 kg-Passengers + 800 kg-elevator), which is moving up with a uniform speed of 3 m s⁻¹ and the frictional force acting on it is 2000 N, then the maximum power used by the motor is ______ kW (g = 10 m/s²)","n":48,"s":"Total mass moved = 1400 kg, so weight = 14000 N.\nMotor force at constant speed = 14000 + 2000 = 16000 N.\nPower = F v = 16000 × 3 = 48000 W = 48 kW."},
{"y":"JEE Main 2023 · 11 Apr · Shift 2","tp":"pwp","st":"Power and efficiency","q":"A block of mass 5 kg starting from rest pulled up on a smooth incline plane making an angle of 30° with horizontal with an effective acceleration of 1 m s⁻². The power delivered by the pulling force at t = 10 s from the start is ______ W. [use g = 10 m s⁻²] (calculate the nearest integer value)","n":300,"s":"Along the incline: F − mg sin30° = ma.\nF = 5 × 1 + 5 × 10 × 0.5 = 5 + 25 = 30 N.\nSpeed at t = 10 s: v = at = 1 × 10 = 10 m/s.\nPower = F v = 30 × 10 = 300 W."},
{"y":"JEE Main 2023 · 24 Jan · Shift 2","tp":"pwp","st":"Power and efficiency","q":"A body of mass 1 kg begins to move under the action of a time dependent force F⃗ = (t î + 3t² ĵ) N, where î and ĵ are the unit vectors along x and y axis. The power developed by above force, at the time t = 2 s will be ______ W.","n":100,"s":"Acceleration a = F/m = t î + 3t² ĵ.\nVelocity (from rest) v = (t²/2) î + t³ ĵ.\nP = F·v = t × t²/2 + 3t² × t³ = t³/2 + 3t⁵.\nAt t = 2 s: P = 8/2 + 3 × 32 = 4 + 96 = 100 W."},
{"y":"JEE Main 2023 · 30 Jan · Shift 2","tp":"pwp","st":"Variable power and vehicles","q":"A body of mass 2 kg is initially at rest. It starts moving unidirectionally under the influence of a source of constant power P. Its displacement in 4 s is {1;3}α²√P m. The value of α will be ______.","n":4,"s":"Constant power: ½mv² = Pt, so v = √(2Pt/m) = √(Pt) for m = 2 kg.\nDisplacement s = ∫v dt = √P × {2;3} t^(3/2).\nAt t = 4 s: s = {2;3} × 8 × √P = {16;3}√P.\nCompare with {1;3}α²√P: α² = 16, so α = 4."},
{"y":"JEE Main 2020 · 5 Sep · Shift 2","tp":"pwp","st":"Variable power and vehicles","q":"A body of mass 2 kg is driven by an engine delivering a constant power of 1 J/s. The body starts from rest and moves in a straight line. After 9 seconds, the body has moved a distance (in m) ______.","n":18,"s":"Constant power: ½mv² = Pt, so v = √(2Pt/m) = √(2 × 1 × t / 2) = √t.\nDistance s = ∫√t dt = {2;3} t^(3/2).\nAt t = 9 s: s = {2;3} × 27 = 18 m."},
{"y":"JEE Advanced 2013","tp":"pwp","st":"Variable power and vehicles","q":"A particle of mass 0.2 kg is moving in one dimension under a force that delivers a constant power 0.5 W to the particle. If the initial speed (in m s⁻¹) of the particle is zero, the speed (in m s⁻¹) after 5 s is ______.","n":5,"s":"Work done by the force in 5 s = P t = 0.5 × 5 = 2.5 J.\nBy the work-energy theorem this equals the gain in kinetic energy: ½ × 0.2 × v² = 2.5.\nv² = 25, so v = 5 m/s."},
{"y":"JEE Main 2025 · 3 Apr · Shift 2","tp":"pwc","st":"Collisions with springs and energy loss","q":"Consider two blocks A and B of masses m₁ = 10 kg and m₂ = 5 kg that are placed on a frictionless table. The block A moves with a constant speed v = 3 m/s towards the block B kept at rest. A spring with spring constant k = 3000 N/m is attached with the block B as shown in the figure. After the collision, suppose that the blocks A and B, along with the spring in constant compression state, move together, then the compression in the spring is (Neglect the mass of the spring)","fig":{"w":340,"h":150,"alt":"Block A of mass 10 kg moving right with speed v towards block B of mass 5 kg, which carries a spring of constant 3000 N/m on its left side; all on a frictionless table.","d":[["r",30,50,70,55],["t",65,82,"A","m"],["t",65,42,"m₁ = 10 kg","m"],["l",104,72,146,72,"a"],["t",125,64,"v","m"],["p","M155 78 H163 L167.5 66 L172.0 90 L176.5 66 L181.0 90 L185.5 66 L190.0 90 L194.5 66 L199.0 90 L203.5 66 L208.0 90 L212.5 66 L217.0 78 H225"],["r",225,50,55,55],["t",252,82,"B","m"],["t",252,42,"m₂ = 5 kg","m"],["l",15,105,325,105],["t",190,128,"k = 3000 N/m","m"]]},"o":["0.4 m","0.2 m","0.1 m","0.3 m"],"c":2,"s":"When the spring is at maximum (constant) compression, A and B move with the same velocity V.\nMomentum: 10 × 3 = (10 + 5) V, so V = 2 m/s.\nEnergy: ½ × 10 × 3² = ½ × 15 × 2² + ½ k x², so 45 = 30 + 1500 x².\n1500 x² = 15, so x² = 0.01 and x = 0.1 m.\nAnswer: 0.1 m."},
{"y":"JEE Main 2025 · 29 Jan · Shift 1","tp":"pwc","st":"Elastic collisions","q":"As shown below, bob A of a pendulum having massless string of length ‘R’ is released from 60° to the vertical. It hits another bob B of half the mass that is at rest on a frictionless table in the center. Assuming elastic collision, the magnitude of the velocity of bob A after the collision will be (take g as acceleration due to gravity).","fig":{"w":340,"h":170,"alt":"A pendulum of length R hangs from a ceiling and is raised to 60 degrees from the vertical; bob A of mass m is at the end of the string, and bob B of mass m/2 rests on a frictionless table directly below the pivot.","d":[["l",25,15,215,15,"B"],["l",60,15,60,140,"d"],["l",60,15,164,75],["c",164,75,6,"F"],["t",176,72,"A"],["t",176,90,"m"],["t",70,48,"60°"],["t",112,36,"R"],["c",60,134,6,"F"],["t",72,138,"B  m/2"],["l",25,146,215,146,"B"]]},"o":["{2;3}√(Rg)","{1;3}√(Rg)","{4;3}√(Rg)","√(Rg)"],"c":1,"s":"Swing down: height drop = R(1 − cos60°) = R/2.\nSpeed of A just before impact: v = √(2g × R/2) = √(gR).\nElastic collision with B of mass m/2 at rest: v_A = {m1 − m2;m1 + m2} v = {m − m/2;m + m/2} v = {1;3} v.\nSo the speed of A after the collision is {1;3}√(Rg)."},
{"y":"JEE Main 2023 · 10 Apr · Shift 1","tp":"pwc","st":"Inelastic collisions and coefficient of restitution","q":"A particle of mass m moving with velocity v collides with a stationary particle of mass 2m. After collision, they stick together and continue to move together with velocity","o":["v","v/4","v/3","v/2"],"c":2,"s":"Momentum is conserved in the collision.\nm v = (m + 2m) V, so V = v/3.\nAnswer: v/3."},
{"y":"JEE Main 2023 · 30 Jan · Shift 1","tp":"pwc","st":"Inelastic collisions and coefficient of restitution","q":"A ball of mass 200 g rests on a vertical post of height 20 m. A bullet of mass 10 g, travelling in horizontal direction, hits the centre of the ball. After the collision both travels independently. The ball hits the ground at a distance 30 m and the bullet at a distance of 120 m from the foot of the post. The value of initial velocity of the bullet will be (if g = 10 m/s²)","o":["400 m/s","360 m/s","60 m/s","120 m/s"],"c":1,"s":"Time to fall 20 m: t = √(2h/g) = √(2 × 20/10) = 2 s (same for both).\nBall speed after collision = 30/2 = 15 m/s. Bullet speed after collision = 120/2 = 60 m/s.\nMomentum: 0.01 × u = 0.2 × 15 + 0.01 × 60 = 3 + 0.6 = 3.6.\nu = 360 m/s."},
{"y":"JEE Main 2023 · 30 Jan · Shift 1","tp":"pwc","st":"Elastic collisions","q":"As per the given figure, a small ball P slides down the quadrant of a circle and hits the other ball Q of equal mass which is initially at rest. Neglecting the effect of friction and assume the collision to be elastic, the velocity of ball Q after collision will be (g = 10 m/s²)","fig":{"w":300,"h":170,"alt":"A quadrant of a circle of radius 20 cm. Ball P starts at the top left end of the quadrant, level with the centre. Ball Q of equal mass rests on the horizontal surface at the bottom of the quadrant and moves right with unknown speed after being hit.","d":[["p","M40 25 A110 110 0 0 0 150 135","B"],["l",40,25,150,25,"db"],["t",95,18,"20 cm","m"],["l",150,25,150,129,"d"],["c",150,25,2,"F"],["c",46,25,5,"F"],["t",32,29,"P","e"],["c",150,129,6,"F"],["t",150,152,"Q","m"],["l",166,129,215,129,"a"],["t",222,133,"v = ?"],["l",20,136,285,136]]},"o":["4 m/s","0","0.25 m/s","2 m/s"],"c":3,"s":"The quadrant has radius 20 cm = 0.2 m, so P drops through 0.2 m.\nSpeed at the bottom: v = √(2gh) = √(2 × 10 × 0.2) = 2 m/s.\nIn an elastic collision between equal masses, the velocities are exchanged.\nSo P stops and Q moves with 2 m/s."},
{"y":"JEE Main 2022 · 25 Jul · Shift 2","tp":"pwc","st":"Inelastic collisions and coefficient of restitution","q":"A bag of sand of mass 9.8 kg is suspended by a rope. A bullet of 200 g travelling with speed 10 m s⁻¹ gets embedded in it, then loss of kinetic energy will be","o":["4.9 J","9.8 J","14.7 J","19.6 J"],"c":1,"s":"Common velocity: 0.2 × 10 = (0.2 + 9.8) V, so V = 0.2 m/s.\nInitial KE = ½ × 0.2 × 10² = 10 J.\nFinal KE = ½ × 10 × 0.2² = 0.2 J.\nLoss = 10 − 0.2 = 9.8 J."},
{"y":"JEE Main 2022 · 27 Jun · Shift 1","tp":"pwc","st":"Elastic collisions","q":"What percentage of kinetic energy of a moving particle is transferred to a stationary particle when it strikes the stationary particle of 5 times its mass? (Assume the collision to be head-on elastic collision)","o":["50.0%","66.6%","55.6%","33.3%"],"c":2,"s":"For a head-on elastic collision of m with a target of mass M at rest, the fraction of KE transferred is 4mM/(m + M)².\nHere M = 5m: fraction = 4 × 5/(1 + 5)² = 20/36 = 0.556.\nSo 55.6% of the kinetic energy is transferred."},
{"y":"JEE Main 2021 · 31 Aug · Shift 1","tp":"pwc","st":"Collisions in two dimensions","q":"A body of mass M moving at a speed V₀ collides elastically with a mass m at rest. After the collision, the two masses move at angles θ₁ and θ₂ with respect to the initial direction of motion of the body of mass M. The largest possible value of the ratio M/m, for which the angles θ₁ and θ₂ will be equal, is","o":["3","4","2","1"],"c":0,"s":"Let both angles equal θ and speeds after collision be V₁ and V₂.\nPerpendicular direction: M V₁ sinθ = m V₂ sinθ, so M V₁ = m V₂.\nAlong the original direction: M V₀ = (M V₁ + m V₂) cosθ = 2M V₁ cosθ, so V₁ = V₀/(2cosθ).\nEnergy: M V₀² = M V₁² + m V₂² = M V₁² (1 + M/m), which gives cos²θ = {1 + M/m;4}.\nSince cos²θ ≤ 1, we need M/m ≤ 3. The largest value is 3."},
{"y":"JEE Main 2021 · 27 Jul · Shift 1","tp":"pwc","st":"Inelastic collisions and coefficient of restitution","q":"Three objects A, B and C are kept in a straight line on a frictionless horizontal surface. The masses of A, B and C are m, 2m and 2m respectively. A moves towards B with a speed of 9 m/s and makes an elastic collision with it. Thereafter B makes a completely inelastic collision with C. All motions occur along same straight line. The final speed of C is","fig":{"w":300,"h":110,"alt":"Three blocks A, B and C in a line on a frictionless surface with masses m, 2m and 2m. Block A moves towards B.","d":[["r",30,45,44,40],["t",52,70,"m","m"],["t",52,39,"A","m"],["r",130,45,44,40],["t",152,70,"2m","m"],["t",152,39,"B","m"],["r",215,45,44,40],["t",237,70,"2m","m"],["t",237,39,"C","m"],["l",78,63,124,63,"a"],["t",101,56,"9 m/s","ms"],["l",15,85,285,85]]},"o":["6 m/s","9 m/s","4 m/s","3 m/s"],"c":3,"s":"A (mass m) hits B (mass 2m) elastically: v_B = {2m;m + 2m} × 9 = 6 m/s.\nB (2m, at 6 m/s) now sticks to C (2m, at rest): 2m × 6 = (2m + 2m) V.\nV = 3 m/s.\nThe final speed of C (moving together with B) is 3 m/s."},
{"y":"JEE Main 2021 · 16 Mar · Shift 2","tp":"pwc","st":"Inelastic collisions and coefficient of restitution","q":"A large block of wood of mass M = 5.99 kg is hanging from two long massless cords. A bullet of mass m = 10 g, is fired into the block and gets embedded in it. The (block + bullet) then swing upwards their centre of mass rising a vertical distance h = 9.8 cm before the (block + bullet) pendulum comes momentarily to rest at the end of its arc. The speed of the bullet just before collision is (take g = 9.8 m s⁻²).","fig":{"w":340,"h":175,"alt":"A wooden block of mass M hangs from two long cords. A bullet of mass m moving horizontally with speed v enters it. The block then swings up to the right, its centre of mass rising by a height h, shown dashed.","d":[["l",95,15,225,15,"B"],["l",110,15,110,130],["l",210,15,210,130],["r",110,130,100,22],["t",160,145,"M","m"],["l",110,15,180,106,"d"],["l",210,15,280,106,"d"],["r",180,106,100,22,"d"],["l",280,130,305,130,"d"],["l",280,106,305,106,"d"],["l",300,108,300,128,"b"],["t",310,121,"h"],["l",35,141,104,141,"a"],["t",45,134,"m"],["t",65,158,"v"]]},"o":["841.4 m/s","821.4 m/s","831.4 m/s","811.4 m/s"],"c":2,"s":"Total mass after the bullet sticks = 5.99 + 0.01 = 6.00 kg.\nBlock + bullet rise h: speed just after impact V = √(2gh) = √(2 × 9.8 × 0.098) = 1.386 m/s.\nMomentum conservation: 0.01 × v = 6.00 × 1.386.\nv ≈ 831.6 m/s, which is closest to 831.4 m/s."},
{"y":"JEE Main 2021 · 17 Mar · Shift 2","tp":"pwc","st":"Collisions with springs and energy loss","q":"Two identical blocks A and B each of mass m resting on the smooth horizontal floor are connected by a light spring of natural length L and spring constant K. A third block C of mass m moving with a speed v along the line joining A and B collides with A. The maximum compression in the spring is","fig":{"w":340,"h":120,"alt":"Block C of mass m moves right with speed v towards block A of mass m. Block A is joined by a light spring to block B of mass m. All rest on a smooth horizontal floor.","d":[["r",15,50,50,40],["t",40,75,"m","m"],["t",40,42,"C","m"],["l",70,70,105,70,"a"],["t",88,63,"v","m"],["r",110,50,50,40],["t",135,75,"m","m"],["t",135,42,"A","m"],["p","M160 70 H168 L172.9 58 L177.8 82 L182.8 58 L187.7 82 L192.6 58 L197.5 82 L202.4 58 L207.3 82 L212.3 58 L217.2 82 L222.1 58 L227.0 70 H235"],["r",235,50,50,40],["t",260,75,"m","m"],["t",260,42,"B","m"],["l",5,90,330,90]]},"o":["v√{m;2K}","√{mv;2K}","√{m;2K}","√{mv;K}"],"c":0,"s":"The collision of C with A is taken as elastic. For equal masses the velocities are exchanged, so C stops and A moves with speed v.\nThe spring is now compressed. At maximum compression A and B move with the same speed V: m v = 2m V, so V = v/2.\nEnergy: ½mv² = ½(2m)(v/2)² + ½ K x², so ½ K x² = ¼ m v².\nx = v√{m;2K}."},
{"y":"JEE Main 2021 · 18 Mar · Shift 2","tp":"pwc","st":"Elastic collisions","q":"An object of mass m₁ collides elastically with another object of mass m₂, which is at rest. After the collision the objects move with equal speeds in opposite direction. The ratio of the masses m₂ : m₁ is","o":["3 : 1","1 : 2","2 : 1","1 : 1"],"c":0,"s":"Take the collision as elastic. Let m₁ move at speed u before, and after the collision m₁ moves back with speed w while m₂ moves forward with speed w.\nElastic: relative speed of separation = relative speed of approach, so w + w = u, giving u = 2w.\nMomentum: m₁ u = m₂ w − m₁ w, so 2 m₁ w = (m₂ − m₁) w.\nm₂ = 3 m₁, so m₂ : m₁ = 3 : 1."},
{"y":"JEE Main 2020 · 2 Sep · Shift 1","tp":"pwc","st":"Collisions in two dimensions","q":"A particle of mass m with an initial velocity uî collides perfectly elastically with a mass 3m at rest. It moves with a velocity vĵ after collision, then, v is given by","o":["v = √{2;3} u","v = u/√3","v = u/√2","v = u/√6"],"c":2,"s":"Let the 3m mass move with (V_x, V_y) after the collision.\nx-momentum: m u = 3m V_x, so V_x = u/3.\ny-momentum: 0 = m v + 3m V_y, so V_y = −v/3.\nEnergy: u² = v² + 3(V_x² + V_y²) = v² + {u²;3} + {v²;3}.\nSo {2u²;3} = {4v²;3}, v² = u²/2 and v = u/√2."},
{"y":"JEE Main 2020 · 3 Sep · Shift 2","tp":"pwc","st":"Inelastic collisions and coefficient of restitution","q":"A block of mass 1.9 kg is at rest at the edge of a table, of height 1 m. A bullet of mass 0.1 kg collides with the block and sticks to it. If the velocity of the bullet is 20 m/s in the horizontal direction just before the collision then the kinetic energy just before the combined system strikes the floor, is [Take g = 10 m/s². Assume there is no rotational motion and loss of energy after the collision is negligible.]","o":["20 J","21 J","19 J","23 J"],"c":1,"s":"Collision: 0.1 × 20 = (0.1 + 1.9) V, so V = 1 m/s.\nKE just after = ½ × 2 × 1² = 1 J.\nFalling through 1 m adds m g h = 2 × 10 × 1 = 20 J.\nKE just before hitting the floor = 1 + 20 = 21 J."},
{"y":"JEE Main 2020 · 4 Sep · Shift 1","tp":"pwc","st":"Inelastic collisions and coefficient of restitution","q":"Blocks of masses m, 2m, 4m and 8m are arranged in a line on a frictionless floor. Another block of mass m, moving with speed v along the same line (see figure) collides with mass m in perfectly inelastic manner. All the subsequent collisions are also perfectly inelastic. By the time the last block of mass 8m starts moving the total energy loss is p% of the original energy. Value of ‘p’ is close to","fig":{"w":340,"h":110,"alt":"Five blocks in a line on a frictionless floor with masses m, m, 2m, 4m and 8m. The first block moves right with speed v.","d":[["r",15,45,44,40],["t",37,70,"m","m"],["r",75,45,44,40],["t",97,70,"m","m"],["r",135,45,44,40],["t",157,70,"2m","m"],["r",195,45,44,40],["t",217,70,"4m","m"],["r",255,45,44,40],["t",277,70,"8m","m"],["l",20,32,56,32,"a"],["t",38,24,"v","m"],["l",5,85,335,85]]},"o":["87","37","77","94"],"c":3,"s":"Each collision is perfectly inelastic, so all the blocks end up moving together.\nFinal mass = m + m + 2m + 4m + 8m = 16m, and momentum is conserved: m v = 16m V, so V = v/16.\nFinal KE = ½ × 16m × (v/16)² = {mv²;32}. Initial KE = ½ m v².\nFinal KE / initial KE = 1/16, so the loss is 15/16 = 93.75%.\np is close to 94."},
{"y":"JEE Main 2020 · 6 Sep · Shift 2","tp":"pwc","st":"Collisions in two dimensions","q":"Particle A of mass m₁ moving with velocity (√3 î + ĵ) m s⁻¹ collides with another particle B of mass m₂ which is at rest initially. Let V₁⃗ and V₂⃗ be the velocities of particles A and B after collision respectively. If m₁ = 2m₂ and after collision V₁⃗ = (î + √3 ĵ) m s⁻¹, the angle between V₁⃗ and V₂⃗ is","o":["15°","60°","−45°","105°"],"c":3,"s":"Momentum: m₁(√3 î + ĵ) = m₁(î + √3 ĵ) + m₂V₂⃗ with m₁ = 2m₂.\nSo V₂⃗ = 2[(√3 − 1) î + (1 − √3) ĵ] = 2(√3 − 1)(î − ĵ).\nThis points along −45° to the x-axis (down and to the right).\nV₁⃗ = (î + √3 ĵ) points at +60° to the x-axis.\nAngle between them = 60° + 45° = 105°."},
{"y":"JEE Main 2020 · 8 Jan · Shift 2","tp":"pwc","st":"Inelastic collisions and coefficient of restitution","q":"A particle of mass m is dropped from a height h above the ground. At the same time another particle of the same mass is thrown vertically upwards from the ground with a speed of √(2gh). If they collide head-on completely inelastically, the time taken for the combined mass to reach the ground, in units of √{h;g} is","o":["√{1;2}","{1;2}","√{3;2}","√{3;4}"],"c":2,"s":"Relative to each other the particles approach at speed √(2gh), so they meet at t = h/√(2gh) = √{h;2g}.\nAt that time the first has speed g t = √{gh;2} downward, and the second has √(2gh) − √{gh;2} = √{gh;2} upward.\nEqual masses with equal and opposite velocities: the combined mass stops (velocity zero).\nHeight at the meeting point = h − ½ g t² = h − h/4 = 3h/4.\nFalling from rest through 3h/4: t = √{2 × 3h/4;g} = √{3;2} √{h;g}."},
{"y":"JEE Main 2020 · 9 Jan · Shift 1","tp":"pwc","st":"Inelastic collisions and coefficient of restitution","q":"Two particles of equal mass m have respective initial velocities uî and u(î + ĵ)/2. They collide completely inelastically. The energy lost in the process is","o":["{3;4}mu²","√{2;3}mu²","{1;3}mu²","{1;8}mu²"],"c":3,"s":"Initial KE = ½mu² + ½m(u²/2) = {3;4}mu².\nFinal velocity V⃗ = {1;2}[uî + (u/2)(î + ĵ)] = u({3;4}î + {1;4}ĵ).\nV² = u²({9;16} + {1;16}) = {5;8}u².\nFinal KE = ½(2m)V² = {5;8}mu².\nEnergy lost = {3;4}mu² − {5;8}mu² = {1;8}mu²."},
{"y":"JEE Main 2020 · 9 Jan · Shift 2","tp":"pwc","st":"Inelastic collisions and coefficient of restitution","q":"A particle of mass m is projected with a speed u from the ground at an angle θ = π/3 w.r.t. horizontal (x-axis). When it has reached its maximum height, it collides completely inelastically with another particle of the same mass and velocity uî. The horizontal distance covered by the combined mass before reaching the ground is","o":["2√2 u²/g","{3√3 u²;8g}","{3√2 u²;4g}","{5u²;8g}"],"c":1,"s":"At the top of its path the first particle has horizontal speed u cos60° = u/2 and no vertical speed.\nMaximum height H = {u² sin²60°;2g} = {3u²;8g}.\nPerfectly inelastic collision with equal masses: V = (u/2 + u)/2 = {3u;4}, horizontal.\nTime to fall from H: t = √{2H;g} = {√3 u;2g}.\nHorizontal distance = V t = {3u;4} × {√3 u;2g} = {3√3 u²;8g}."},
{"y":"JEE Main 2019 · 8 Apr · Shift 2","tp":"pwc","st":"Inelastic collisions and coefficient of restitution","q":"A body of mass m₁ moving with an unknown velocity of v₁î, undergoes a collinear collision with a body of mass m₂ moving with a velocity v₂î. After collision, m₁ and m₂ move with velocities of v₃î and v₄î, respectively. If m₂ = 0.5 m₁ and v₃ = 0.5 v₁, then v₁ is","o":["v₄ − v₂","v₄ − {v₂;2}","v₄ − {v₂;4}","v₄ + v₂"],"c":0,"s":"Momentum conservation: m₁v₁ + m₂v₂ = m₁v₃ + m₂v₄.\nPut m₂ = 0.5 m₁ and v₃ = 0.5 v₁: v₁ + 0.5 v₂ = 0.5 v₁ + 0.5 v₄.\nSo 0.5 v₁ = 0.5 (v₄ − v₂).\nv₁ = v₄ − v₂."},
{"y":"JEE Main 2019 · 9 Apr · Shift 1","tp":"pwc","st":"Elastic collisions","q":"A body of mass 2 kg makes an elastic collision with a second body at rest and continues to move in the original direction but with one fourth of its original speed. What is the mass of the second body?","o":["1.5 kg","1.8 kg","1.2 kg","1.0 kg"],"c":2,"s":"Elastic collision with a target at rest: v₁ = {m₁ − m₂;m₁ + m₂} u.\nGiven v₁ = u/4: {2 − m₂;2 + m₂} = {1;4}.\n8 − 4m₂ = 2 + m₂, so 5m₂ = 6.\nm₂ = 1.2 kg."},
{"y":"JEE Main 2019 · 9 Apr · Shift 2","tp":"pwc","st":"Collisions in two dimensions","q":"A particle of mass ‘m’ moving with speed ‘2v’ and collides with a mass ‘2m’ moving with speed ‘v’ in the same direction. After collision, the first mass is stopped completely while the second one splits into two particles each of mass ‘m’, which move at angle 45° with respect to the original direction. The speed of each of the moving particle will be","o":["√2 v","v/(2√2)","2√2 v","v/√2"],"c":2,"s":"Total momentum along the original direction before: m(2v) + 2m(v) = 4mv.\nAfter: the first mass is at rest. The two pieces (mass m each, speed V) go at +45° and −45°, so their sideways momenta cancel.\nAlong the original direction: 2 × m V cos45° = 4mv.\nV = {4v;√2} = 2√2 v."},
{"y":"JEE Main 2019 · 10 Apr · Shift 1","tp":"pwc","st":"Collisions in two dimensions","q":"Two particles, of masses M and 2M, moving, as shown, with speeds of 10 m/s and 5 m/s, collide elastically at the origin. After the collision, they move along the indicated directions with speeds v₁ and v₂, respectively. The values of v₁ and v₂ are nearly","fig":{"w":340,"h":200,"alt":"Mass M moving at 10 m/s from upper left and mass 2M moving at 5 m/s from lower left meet at the origin; after collision 2M leaves up-right at 30 degrees with speed v1 and M leaves down-right at 45 degrees with speed v2.","d":[["l",60,100,300,100,"d"],["l",83.4,50,170,100,"a"],["l",99.3,170.7,170,100,"a"],["l",170,100,256.6,50,"a"],["l",170,100,240.7,170.7,"a"],["t",77.4,46,"M","e"],["t",93.3,182.7,"2M","e"],["t",262.6,48,"2M",""],["t",246.7,182.7,"M",""],["t",113.4,56,"10 m/s","s"],["t",95.3,162.7,"5 m/s","se"],["t",262.6,62,"v₁","s"],["t",246.7,168.7,"v₂","s"],["t",134,92,"30°","se"],["t",134,118,"45°","se"],["t",200,92,"30°","s"],["t",200,120,"45°","s"]]},"o":["6.5 m/s and 6.3 m/s","6.5 m/s and 3.2 m/s","3.2 m/s and 6.3 m/s","3.2 m/s and 12.6 m/s"],"c":0,"s":"Take x to the right and y upward and use conservation of momentum along both axes with the directions in the figure.\nx: M(10 cos30°) + 2M(5 cos45°) = 2M v₁ cos30° + M v₂ cos45°, so 1.732 v₁ + 0.707 v₂ = 15.73.\ny: −M(10 sin30°) + 2M(5 sin45°) = 2M v₁ sin30° − M v₂ sin45°, so v₁ − 0.707 v₂ = 2.07.\nAdd the two equations: 2.732 v₁ = 17.8, so v₁ ≈ 6.5 m/s. Then v₂ = (6.5 − 2.07)/0.707 ≈ 6.3 m/s.\nAnswer: 6.5 m/s and 6.3 m/s, option (a)."},
{"y":"JEE Main 2019 · 9 Jan · Shift 1","tp":"pwc","st":"Inelastic collisions and coefficient of restitution","q":"Three blocks A, B and C are lying on a smooth horizontal surface, as shown in the figure. A and B have equal masses, m while C has mass M. Block A is given an initial speed v towards B due to which it collides with B perfectly inelastically. The combined mass collides with C, also perfectly inelastically, {5;6}th of the initial kinetic energy is lost in whole process. What is value of M/m?","fig":{"w":340,"h":120,"alt":"Three blocks on a smooth floor: A of mass m moving right with speed v, B of mass m and C of mass M at rest.","d":[["l",30,100,320,100],["r",60,60,40,40],["r",150,60,40,40],["r",250,60,50,40],["t",80,84,"m","m"],["t",170,84,"m","m"],["t",275,84,"M","m"],["t",80,52,"A","ms"],["t",170,52,"B","ms"],["t",275,52,"C","ms"],["l",62,28,110,28,"a"],["t",116,32,"v",""]]},"o":["5","2","3","4"],"c":3,"s":"After A hits B (perfectly inelastic), the combined mass 2m moves with speed v/2.\nAfter it sticks to C, the final speed is v′ = 2m(v/2)/(2m+M) = mv/(2m+M).\nFinal kinetic energy = ½(2m+M)v′² = m²v²/[2(2m+M)].\nOnly {1;6} of the initial energy ½mv² is left, so m²v²/[2(2m+M)] = mv²/12.\nThis gives 6m = 2m + M, so M = 4m and M/m = 4. Option (d)."},
{"y":"JEE Main 2019 · 10 Jan · Shift 1","tp":"pwc","st":"Inelastic collisions and coefficient of restitution","q":"A piece of wood of mass 0.03 kg is dropped from the top of a 100 m height building. At the same time, a bullet of mass 0.02 kg is fired vertically upward, with a velocity 100 m s⁻¹, from the ground. The bullet gets embedded in the wood. Then the maximum height to which the combined system reaches above the top of the building before falling below is (g = 10 m s⁻²)","o":["10 m","30 m","20 m","40 m"],"c":3,"s":"Both start together; the gap closes at the relative speed 100 m/s, so they meet after t = 100/100 = 1 s.\nAt that time the wood has fallen 5 m and moves down at 10 m/s. The bullet is at 95 m height moving up at 100 − 10 = 90 m/s.\nMomentum (up positive): 0.02×90 − 0.03×10 = 1.5 = 0.05 V, so V = 30 m/s upward.\nFurther rise = 30²/(2×10) = 45 m, so the top point is 95 + 45 = 140 m above the ground, i.e. 40 m above the building top.\nAnswer: 40 m, option (d)."},
{"y":"JEE Main 2019 · 12 Jan · Shift 1","tp":"pwc","st":"Elastic collisions","q":"A simple pendulum, made of a string of length l and a bob of mass m, is released from a small angle θ₀. It strikes a block of mass M, kept on a horizontal surface at its lowest point of oscillations, elastically. It bounces back and goes up to an angle θ₁. Then M is given by","o":["{m;2}({θ₀−θ₁;θ₀+θ₁})","m({θ₀+θ₁;θ₀−θ₁})","{m;2}({θ₀+θ₁;θ₀−θ₁})","m({θ₀−θ₁;θ₀+θ₁})"],"c":1,"s":"For small angles the speed at the lowest point is proportional to the release angle: v = θ√(gl). So the speed before impact is ∝ θ₀ and the speed after bouncing back is ∝ θ₁.\nElastic collision with the block at rest: the bob's velocity after impact is u′ = {m−M;m+M}u, so its speed is {M−m;M+m}u.\nTherefore θ₁/θ₀ = (M−m)/(M+m).\nCross-multiplying: M(θ₀−θ₁) = m(θ₀+θ₁), so M = m{θ₀+θ₁;θ₀−θ₁}. This is option (b).\nNote: the printed key lists (d), but (d) gives M < m, and then the bob would not bounce back at all. (b) is the physically correct result."},
{"y":"JEE Main 2019 · 12 Jan · Shift 2","tp":"pwc","st":"Elastic collisions","q":"An alpha-particle of mass m suffers 1-dimensional elastic collision with a nucleus at rest of unknown mass. It is scattered directly backwards losing, 64% of its initial kinetic energy. The mass of the nucleus is","o":["4m","1.5m","3.5m","2m"],"c":0,"s":"Let the nucleus have mass M. After an elastic collision the alpha-particle has velocity v = {m−M;m+M}u.\nIt keeps 36% of its kinetic energy, so v² = 0.36u² and |v| = 0.6u.\nSince it goes backwards: {M−m;M+m} = 0.6.\nM − m = 0.6M + 0.6m, so 0.4M = 1.6m and M = 4m. Option (a)."},
{"y":"JEE Main 2018","tp":"pwc","st":"Elastic collisions","q":"In a collinear collision, a particle with an initial speed v₀ strikes a stationary particle of the same mass. If the final total kinetic energy is 50% greater than the original kinetic energy, the magnitude of the relative velocity between the two particles, after collision, is","o":["{v₀;4}","√2 v₀","{v₀;2}","{v₀;√2}"],"c":1,"s":"Let the final speeds be v₁ and v₂ (same direction line). Momentum: v₁ + v₂ = v₀.\nEnergy: v₁² + v₂² = 1.5 v₀².\nUse (v₁+v₂)² + (v₁−v₂)² = 2(v₁²+v₂²).\nSo v₀² + (v₁−v₂)² = 3v₀², giving (v₁−v₂)² = 2v₀².\nRelative speed = √2 v₀. Option (b)."},
{"y":"JEE Main 2018","tp":"pwc","st":"Elastic collisions","q":"It is found that if a neutron suffers an elastic collinear collision with deuterium at rest, fractional loss of its energy is p_d; while for its similar collision with carbon nucleus at rest, fractional loss of energy is p_c. The values of p_d and p_c are respectively","o":["(0.89, 0.28)","(0.28, 0.89)","(0, 0)","(0, 1)"],"c":0,"s":"For an elastic head-on collision with a target at rest, the fractional loss of energy is 4m₁m₂/(m₁+m₂)².\nNeutron (mass 1) with deuterium (mass 2): 4×1×2/(3)² = 8/9 ≈ 0.89.\nNeutron with carbon (mass 12): 4×1×12/(13)² = 48/169 ≈ 0.28.\nSo (p_d, p_c) = (0.89, 0.28). Option (a)."},
{"y":"JEE Main 2018 · Online","tp":"pwc","st":"Collisions in two dimensions","q":"A proton of mass m collides elastically with a particle of unknown mass at rest. After the collision, the proton and the unknown particle are seen moving at an angle of 90° with respect to each other. The mass of unknown particle is","o":["m","2m","{m;√3}","{m;2}"],"c":0,"s":"Let the proton speed before be u and after be v₁, and the unknown particle (mass M) speed after be v₂.\nMomentum: m u⃗ = m v⃗₁ + M v⃗₂. Energy: m u² = m v₁² + M v₂².\nIf v⃗₁ ⟂ v⃗₂, the momentum triangle is right-angled: m²u² = m²v₁² + M²v₂².\nMultiply the energy equation by m: m²u² = m²v₁² + mM v₂².\nComparing the two: M²v₂² = mM v₂², so M = m.\nOption (a)."},
{"y":"JEE Main 2017 · Online","tp":"pwc","st":"Collisions in two dimensions","q":"Two particles A and B of equal mass M are moving with the same speed v as shown in the figure. They collide completely inelastically and move as a single particle C. The angle θ that the path of C makes with the X-axis is given by","fig":{"w":340,"h":200,"alt":"Axes with the collision point at the origin: particle A comes in from lower left along a path 30 degrees from the Y axis, particle B from lower right along a path 45 degrees from the Y axis; the combined particle C leaves upward along a dotted line.","d":[["l",40,110,320,110,"a"],["l",170,190,170,15,"a"],["t",318,126,"X","s"],["t",178,20,"Y","s"],["l",140,162,170,110,"a"],["l",212.4,152.4,170,110,"a"],["l",170,110,158.9,25.7,"da"],["t",136,170,"A","e"],["t",216.4,160.4,"B",""],["t",166.9,31.7,"C",""],["t",162,140,"30°","se"],["t",182,142,"45°","s"]]},"o":["tanθ = {√3+√2;1−√2}","tanθ = {1−√3;1+√2}","tanθ = {√3−√2;1−√2}","tanθ = {1−√2;√2(1+√3)}"],"c":0,"s":"In the figure the paths of A and B make 30° and 45° with the vertical Y-axis. A moves up and to the right, B moves up and to the left.\nMomentum along X: M v sin30° − M v sin45° = 2M v_x, so v_x = {v;2}(sin30° − sin45°).\nMomentum along Y: M v cos30° + M v cos45° = 2M v_y, so v_y = {v;2}(cos30° + cos45°).\ntanθ = v_y/v_x = {cos30° + cos45°;sin30° − sin45°} = {√3/2 + 1/√2;1/2 − 1/√2} = {√3+√2;1−√2}. Option (a)."},
{"y":"JEE Main 2016 · Online","tp":"pwc","st":"Inelastic collisions and coefficient of restitution","q":"A neutron moving with a speed 'v' makes a head on collision with a stationary hydrogen atom in ground state. The minimum kinetic energy of the neutron for which inelastic collision will take place is","o":["20.4 eV","10.2 eV","12.1 eV","16.8 eV"],"c":0,"s":"The neutron and hydrogen atom have almost equal masses.\nIn the most inelastic case they move together, and half of the neutron's kinetic energy K is lost (for equal masses, loss = K/2).\nThe atom can absorb energy only if it can be excited from n = 1 to n = 2, which needs 10.2 eV.\nSo K/2 ≥ 10.2 eV, giving K ≥ 20.4 eV. Option (a)."},
{"y":"JEE Main 2015","tp":"pwc","st":"Collisions in two dimensions","q":"A particle of mass m moving in the x direction with speed 2v is hit by another particle of mass 2m moving in the y-direction with speed v. If the collision is perfectly inelastic, the percentage loss in the energy during the collision is close to","o":["56%","62%","44%","50%"],"c":0,"s":"Initial kinetic energy = ½m(2v)² + ½(2m)v² = 2mv² + mv² = 3mv².\nMomentum: p_x = 2mv, p_y = 2mv, total mass 3m, so the final speed² = (2mv)²+(2mv)² divided by (3m)² = {8v²;9}.\nFinal kinetic energy = ½(3m){8v²;9} = {4;3}mv².\nLoss = 3 − 4/3 = 5/3 mv², which is 5/9 of the initial energy ≈ 56%. Option (a)."},
{"y":"JEE Main 2015 · Online","tp":"pwc","st":"Elastic collisions","q":"A large number (n) of identical beads, each of mass m and radius r are strung on a thin smooth rigid horizontal rod of length L (L >> r) and are at rest at random positions. The rod is mounted between two rigid supports (see figure). If one of the beads is now given a speed v, the average force experienced by each support after a long time is (assume all collisions are elastic)","fig":{"w":340,"h":140,"alt":"A thin horizontal rod of length L between two rigid supports with several beads strung on it; one bead moves with speed v.","d":[["r",34,25,8,80,"F"],["r",298,25,8,80,"F"],["l",42,65,298,65,"B"],["c",70,65,6],["c",112,65,6],["c",158,65,6],["c",178,65,6],["c",232,65,6],["c",262,65,6],["l",64,44,100,44,"a"],["t",104,48,"v",""],["l",42,118,298,118,"b"],["t",170,134,"L","m"],["t",170,24,"n beads, each of radius r","ms"]]},"o":["{mv²;L−nr}","{mv²;L−2nr}","{mv²;2(L−nr)}","zero"],"c":1,"s":"Identical beads in an elastic head-on collision exchange velocities. So the speed v is simply passed from bead to bead and travels to and fro between the supports.\nThe beads occupy 2r each, i.e. 2nr in total, so the distance actually travelled at speed v between the two end beads is L − 2nr.\nA support is hit once every 2(L − 2nr)/v seconds, and each hit gives an impulse 2mv.\nAverage force = 2mv ÷ [2(L − 2nr)/v] = {mv²;L−2nr}. Option (b)."},
{"y":"JEE Advanced 2014","tp":"pwc","st":"Collisions with springs and energy loss","q":"A tennis ball is dropped on a horizontal smooth surface. It bounces back to its original position after hitting the surface. The force on the ball during the collision is proportional to the length of compression of the ball. Which one of the following sketches describes the variation of its kinetic energy K with time t most appropriately? The figures are only illustrative and not to the scale.","fig":{"w":340,"h":215,"alt":"Four small graphs of kinetic energy K against time t: (a) two rounded humps separated by a sharp drop to zero, (b) small rise to two sharp peaks with a dip between them, (c) a rise to a flat plateau and a fall, (d) two straight-line triangles.","d":[["t",6,16,"(a)",""],["l",34,94,164,94,"a"],["l",34,94,34,18,"a"],["t",38,18,"K","s"],["t",164,106,"t","se"],["p","M34 94 Q48 30 81 42 L84 94 L87 42 Q120 30 134 94","B"],["t",176,16,"(b)",""],["l",204,94,334,94,"a"],["l",204,94,204,18,"a"],["t",208,18,"K","s"],["t",334,106,"t","se"],["p","M204 94 Q232 90 249 36 L254 86 L259 36 Q276 90 304 94","B"],["t",6,124,"(c)",""],["l",34,202,164,202,"a"],["l",34,202,34,126,"a"],["t",38,126,"K","s"],["t",164,214,"t","se"],["p","M34 202 Q64 200 74 144 L94 144 Q104 200 134 202","B"],["t",176,124,"(d)",""],["l",204,202,334,202,"a"],["l",204,202,204,126,"a"],["t",208,126,"K","s"],["t",334,214,"t","se"],["p","M204 202 L251 144 L254 202 L257 144 L304 202","B"]]},"o":["Graph (a)","Graph (b)","Graph (c)","Graph (d)"],"c":1,"s":"Before touching the surface the ball falls freely: K = ½mg²t² grows like a parabola from zero (slowly at first, then faster).\nDuring contact the force is spring-like, so the ball slows down to rest at maximum compression: K falls to (nearly) zero and then rises again as the ball is pushed back. This gives a sharp dip at the middle.\nAfter leaving the surface the ball rises and K decreases to zero at the original height.\nOnly graph (b) has a small slow rise, a sharp peak, a deep dip, a second peak and a fall to zero. Graph (a) has no parabola-type rise, (c) never goes to zero in contact, (d) is made of straight lines."},
{"y":"JEE Advanced 2013","tp":"pwc","st":"Inelastic collisions and coefficient of restitution","q":"A particle of mass m is projected from the ground with an initial speed u₀ at an angle α with the horizontal. At the highest point of its trajectory, it makes a completely inelastic collision with another identical particle, which was thrown vertically upward from the ground with the same initial speed u₀. The angle that the composite system makes with the horizontal immediately after the collision is","o":["{π;4}","{π;4}+α","{π;2}−α","{π;2}"],"c":0,"s":"At the top the first particle moves horizontally with speed u₀cosα, and it is at height H = u₀²sin²α/(2g).\nThe second particle is at the same point, so its upward speed there follows from v² = u₀² − 2gH = u₀² − u₀²sin²α = u₀²cos²α. So v = u₀cosα upward.\nMomentum: horizontal = m u₀cosα, vertical = m u₀cosα.\nThe two components are equal, so tanφ = 1 and φ = π/4. Option (a)."},
{"y":"AIEEE 2009","tp":"pwc","st":"Elastic collisions","q":"Consider a rubber ball freely falling from a height h = 4.9 m onto a horizontal elastic plate. Assume that the duration of collision is negligible and the collision with the plate is totally elastic. Then the velocity as a function of time and the height as function of time will be","fig":{"w":340,"h":222,"alt":"Four options, each showing a velocity-time graph (left) and a height-time graph (right). In (a) velocity is always positive with triangular humps; in (b) it zigzags between +v1 and -v1; in (c) it falls in straight lines from +v1 to -v1 and jumps back up each time; in (d) it rises in straight lines and jumps down each time.","d":[["t",3,12,"(a)",""],["l",34,100,34,10,"a"],["l",34,84,109,84,"a"],["l",34,30,68,30,"d"],["t",31,34,"v₁","se"],["p","M34 84 L49 30 L64 84 L79 30 L94 84","B"],["t",38,14,"v","s"],["t",110,96,"t","s"],["l",106,100,170,100,"a"],["l",106,100,106,10,"a"],["t",110,14,"y","s"],["t",103,58,"h","se"],["t",172,112,"t","se"],["p","M106 54 Q117 54 120 100 M128 100 Q139 8 150 100","B"],["t",173,12,"(b)",""],["l",204,100,204,10,"a"],["l",204,57,279,57,"a"],["l",204,27,270,27,"d"],["l",204,87,270,87,"d"],["t",201,31,"+v₁","se"],["t",201,91,"−v₁","se"],["p","M204 57 L214 87 L234 27 L254 87 L274 27","B"],["t",208,14,"v","s"],["t",280,70,"t","s"],["l",276,100,340,100,"a"],["l",276,100,276,10,"a"],["t",280,14,"y","s"],["t",273,58,"h","se"],["t",342,112,"t","se"],["p","M276 54 Q287 54 290 100 Q301 8 312 100 Q323 8 334 100","B"],["t",3,122,"(c)",""],["l",34,210,34,120,"a"],["l",34,167,109,167,"a"],["l",34,137,100,137,"d"],["l",34,197,100,197,"d"],["t",31,141,"+v₁","se"],["t",31,201,"−v₁","se"],["p","M34 167 L44 197 L44 137 L64 197 L64 137 L84 197","B"],["t",38,124,"v","s"],["t",110,180,"t","s"],["l",106,210,170,210,"a"],["l",106,210,106,120,"a"],["t",110,124,"y","s"],["t",103,168,"h","se"],["t",172,222,"t","se"],["p","M106 164 Q117 164 120 210 Q131 118 142 210 Q153 118 164 210","B"],["t",173,122,"(d)",""],["l",204,210,204,120,"a"],["l",204,167,279,167,"a"],["l",204,137,270,137,"d"],["l",204,197,270,197,"d"],["t",201,141,"+v₁","se"],["t",201,201,"−v₁","se"],["p","M204 167 L214 137 L214 197 L234 137 L234 197 L254 137","B"],["t",208,124,"v","s"],["t",280,180,"t","s"],["l",276,210,340,210,"a"],["l",276,210,276,120,"a"],["t",280,124,"y","s"],["t",273,168,"h","se"],["t",342,222,"t","se"],["p","M276 164 Q287 164 290 210 Q301 118 312 210 Q323 118 334 210","B"]]},"o":["Graph (a)","Graph (b)","Graph (c)","Graph (d)"],"c":2,"s":"Take upward as positive. While falling, v = −gt, a straight line sloping down, reaching −v₁ (v₁ = √(2gh) = 9.8 m/s) at t₁ = 1 s.\nThe collision is elastic and instantaneous, so the velocity jumps at once from −v₁ to +v₁ (a vertical line).\nOn the way up the speed decreases uniformly: v goes from +v₁ down to −v₁ over 2t₁, then jumps up again at 3t₁, and so on. This saw-tooth of falling lines with upward jumps is graph (c).\nThe height starts at h, falls along a curve to zero, and then repeats arches of the same height h with no gaps. Graph (c) shows both features.\nGraph (a) has the wrong velocity sign and a gap, (b) and (d) have rising lines, which is wrong because gravity always gives a downward acceleration."},
{"y":"IIT-JEE 2009","tp":"pwc","st":"Elastic collisions","q":"Two small particles of equal masses start moving in opposite directions from a point A in a horizontal circular orbit. Their tangential velocities are v and 2v respectively, as shown in the figure. Between collisions, the particles move with constant speeds. After making how many elastic collisions, other than that at A, these two particles will again reach the point A?","fig":{"w":340,"h":170,"alt":"A horizontal circular orbit with point A at the top; one particle starts from A moving left with speed v, the other moving right with speed 2v.","d":[["c",170,100,55],["c",170,45,3,"F"],["l",162,38,118,38,"a"],["l",178,38,222,38,"a"],["t",140,28,"v","ms"],["t",200,28,"2v","ms"],["t",170,62,"A","ms"]]},"o":["4","3","2","1"],"c":2,"s":"Equal masses in an elastic head-on collision exchange velocities. So it is as if the particles pass through each other without collision.\nThe particles move in opposite directions with relative speed 3v, so they meet each time they together cover one circumference C. Meetings occur at t = C/(3v), 2C/(3v) and C/v.\nAt t = C/v the faster one has gone twice round and the slower one once round, so both are back at A together (that meeting is at A itself).\nThe collisions away from A are the first two meetings: 2 collisions. Option (c)."},
{"y":"AIEEE 2008","tp":"pwc","st":"Inelastic collisions and coefficient of restitution","q":"A block of mass 0.50 kg is moving with a speed of 2.00 m s⁻¹ on a smooth surface. It strikes another mass of 1.00 kg and then they move together as a single body. The energy loss during the collision is","o":["0.34 J","0.16 J","1.00 J","0.67 J"],"c":3,"s":"Momentum: 0.50×2.00 = (0.50 + 1.00)v, so v = 2/3 m/s.\nInitial KE = ½×0.50×(2.00)² = 1.00 J.\nFinal KE = ½×1.50×(2/3)² = 0.33 J.\nLoss = 1.00 − 0.33 = 0.67 J. Option (d)."},
{"y":"AIEEE 2005","tp":"pwc","st":"Collisions in two dimensions","q":"A mass m moves with a velocity v and collides inelastically with another identical mass. After collision the first mass moves with velocity {v;√3} in a direction perpendicular to the initial direction of motion. Find the speed of the 2nd mass after collision","fig":{"w":340,"h":210,"alt":"Before collision: mass m moves right toward a second mass m at rest. After collision: the first mass moves straight up with speed v/√3 while the second mass is shown at rest in the original line.","d":[["c",40,150,4,"F"],["l",48,150,110,150,"a"],["t",38,170,"m","m"],["t",40,188,"before collision","s"],["c",230,150,4,"F"],["t",244,154,"m",""],["c",230,70,4,"F"],["l",230,60,230,25,"a"],["t",240,38,"v/√3",""],["t",242,74,"after collision","s"]]},"o":["{2;√3}v","{v;√3}","v","√3v"],"c":0,"s":"Let the second mass move with speed V at angle φ to the initial direction.\nAlong the original direction: m v = m V cosφ, so V cosφ = v.\nPerpendicular direction: 0 = m(v/√3) − m V sinφ, so V sinφ = v/√3.\nV² = v² + v²/3 = {4v²;3}, so V = {2;√3}v. Option (a)."},
{"y":"JEE Advanced 2023","tp":"pwc","st":"Inelastic collisions and coefficient of restitution","q":"A slide with a frictionless curved surface, which becomes horizontal at its lower end, is fixed on the terrace of a building of height 3h from the ground, as shown in the figure. A spherical ball of mass m is released on the slide from rest at a height h from the top of the terrace. The ball leaves the slide with a velocity u⃗₀ = u₀ x̂ and falls on the ground at a distance d from the building making an angle θ with the horizontal. It bounces off with a velocity v⃗ and reaches a maximum height h₁. The acceleration due to gravity is g and the coefficient of restitution of the ground is 1/√3. Which of the following statement(s) is(are) correct?","fig":{"w":340,"h":215,"alt":"A ball released on a curved slide on the roof of a building of height 3h leaves horizontally with speed u0, lands at distance d at angle theta, bounces and rises to height h1.","d":[["l",20,175,330,175,"B"],["r",60,85,80,90,"f"],["p","M62 52 Q66 84 140 85"],["l",62,52,62,85],["c",68,50,3,"F"],["l",52,52,52,85,"b"],["t",48,72,"h","se"],["l",38,85,38,175,"b"],["t",34,134,"3h","se"],["p","M140 85 Q200 85 240 175","d"],["l",142,85,176,85,"a"],["t",168,76,"u₀",""],["l",156,105,156,135,"a"],["t",162,124,"g","s"],["l",240,175,290,115,"da"],["t",296,112,"v",""],["l",304,175,304,118,"b"],["t",310,150,"h₁","s"],["l",140,195,240,195,"b"],["l",140,175,140,198,"d"],["l",240,175,240,198,"d"],["t",190,210,"d","ms"],["t",224,168,"θ","se"],["l",300,56,300,24,"a"],["l",300,56,330,56,"a"],["t",304,20,"z","s"],["t",328,70,"x","s"]]},"o":["u⃗₀ = √(2gh) x̂","v⃗ = √(2gh) (x̂ − ẑ)","θ = 60°","d/h₁ = 2√3"],"c":[0,2,3],"s":"Slide: mgh = ½mu₀², so u₀ = √(2gh). Statement (a) is true.\nFall through 3h: vertical speed at the ground = √(2g·3h) = √(6gh). tanθ = √(6gh)/√(2gh) = √3, so θ = 60°. Statement (c) is true.\nBounce: the vertical component is multiplied by e = 1/√3, giving √(2gh) upward; the horizontal component stays √(2gh). So v⃗ = √(2gh)(x̂ + ẑ) with z pointing up. The option with (x̂ − ẑ) is wrong, so (b) is false.\nTime of fall t = √(6h/g), so d = u₀t = √(2gh)·√(6h/g) = 2√3 h. Rise h₁ = (√(2gh))²/(2g) = h. So d/h₁ = 2√3. Statement (d) is true.\nCorrect: (a), (c), (d)."},
{"y":"JEE Advanced 2019","tp":"pwc","st":"Elastic collisions","q":"A small particle of mass m moving inside a heavy, hollow and straight tube along the tube axis undergoes elastic collision at two ends. The tube has no friction and it is closed at one end by a flat surface while the other end is fitted with a heavy movable flat piston as shown in figure. When the distance of the piston from closed end is L = L₀, the particle speed is v = v₀. The piston is moved inward at a very low speed V such that V << {dL;L}v₀, where dL is the infinitesimal displacement of the piston. Which of the following statement(s) is/are correct?","fig":{"w":340,"h":150,"alt":"A hollow tube closed at the left end with a movable piston at the right end; a particle inside moves right with speed v. The distance between the closed end and the piston is L.","d":[["r",30,45,240,40],["r",262,45,10,40,"f"],["l",272,55,300,55],["l",272,75,300,75],["c",100,65,4,"F"],["l",108,65,150,65,"a"],["t",130,58,"v","ms"],["l",30,110,262,110,"b"],["l",30,88,30,114,"d"],["l",262,88,262,114,"d"],["t",146,130,"L","m"]]},"o":["After each collision with the piston, the particle speed increases by 2V.","If the piston moves inward by dL, the particle speed increases by 2v{dL;L}.","The particle's kinetic energy increases by a factor of 4 when the piston is moved inward from L₀ to {1;2}L₀.","The rate at which the particle strikes the piston is v/L."],"c":[0,2],"s":"(a) The piston is heavy, so in the piston frame the particle just reverses its relative velocity. Speed v+V relative to piston before, v+V after, so in the ground frame the speed becomes v + 2V. True.\n(b) The piston takes time dL/V to move dL. Hits occur every 2L/v, so the number of hits N = v dL/(2LV). Gain = 2V·N = v dL/L, not 2v dL/L. False.\n(c) From dv/v = −dL/L we get vL = constant. When L goes from L₀ to L₀/2, v doubles and kinetic energy becomes 4 times. True.\n(d) The particle strikes the piston once every 2L/v, i.e. at rate v/(2L), not v/L. False.\nCorrect: (a), (c)."},
{"y":"IIT-JEE 2010","tp":"pwc","st":"Elastic collisions","q":"A point mass of 1 kg collides elastically with a stationary point mass of 5 kg. After their collision, the 1 kg mass reverses its direction and moves with a speed of 2 m s⁻¹. Which of the following statement(s) is(are) correct for the system of these two masses?","o":["Total momentum of the system is 3 kg m s⁻¹.","Momentum of 5 kg mass after collision is 4 kg m s⁻¹.","Kinetic energy of the centre of mass is 0.75 J.","Total kinetic energy of the system is 4 J."],"c":[0,2],"s":"Elastic collision with the 5 kg mass at rest: the 1 kg mass has final velocity {1−5;1+5}u = −{2;3}u. Given speed 2 m/s, u = 3 m/s.\n(a) Total momentum = 1×3 = 3 kg m/s. True.\n(b) The 5 kg mass has velocity {2×1;6}×3 = 1 m/s, so its momentum is 5 kg m/s, not 4. False.\n(c) v_cm = 3/6 = 0.5 m/s, KE of centre of mass = ½×6×0.5² = 0.75 J. True.\n(d) Total KE = ½×1×3² = 4.5 J (check: 2 J + 2.5 J), not 4 J. False.\nCorrect: (a), (c)."},
{"y":"JEE Main 2023 · 25 Jan · Shift 2","tp":"pwc","st":"Elastic collisions","q":"A body of mass 1 kg collides head on elastically with a stationary body of mass 3 kg. After collision, the smaller body reverses its direction of motion and moves with a speed of 2 m/s. The initial speed of the smaller body before collision is ____ m s⁻¹.","n":4,"s":"For an elastic head-on collision with the 3 kg body at rest: v₁ = {m₁−m₂;m₁+m₂}u = {1−3;1+3}u = −{u;2}.\nThe speed after collision is u/2 = 2 m/s.\nSo u = 4 m/s."},
{"y":"JEE Main 2023 · 31 Jan · Shift 2","tp":"pwc","st":"Inelastic collisions and coefficient of restitution","q":"A ball is dropped from a height of 20 m. If the coefficient of restitution for the collision between ball and floor is 0.5, after hitting the floor, the ball rebounds to a height of ____ m.","n":5,"s":"Speed just before impact: v = √(2gh). Speed after impact: ev.\nRebound height h′ = (ev)²/(2g) = e²h.\nh′ = 0.5² × 20 = 0.25 × 20 = 5 m."},
{"y":"JEE Main 2022 · 28 Jun · Shift 1","tp":"pwc","st":"Inelastic collisions and coefficient of restitution","q":"A man of mass 60 kg is running on the road and suddenly jumps into a stationary trolly car of mass 120 kg. Then the trolly car starts moving with velocity 2 m s⁻¹. The velocity of the running man was ____ m s⁻¹, when he jumps into the car.","n":6,"s":"The man sticks to the car, so momentum is conserved: 60 × u = (60 + 120) × 2.\n60u = 360, so u = 6 m/s."},
{"y":"JEE Main 2021 · 27 Aug · Shift 2","tp":"pwv","st":"Vertical circle conditions","q":"A bullet of 10 g, moving with velocity v, collides head-on with the stationary bob of a pendulum and recoils with velocity 100 m/s. The length of the pendulum is 0.5 m and mass of the bob is 1 kg. The minimum value of v = ____ m/s so that the pendulum describes a circle. (Assume the string to be inextensible and g = 10 m/s²)","n":400,"s":"For the bob to complete the circle, its speed just after the hit must be at least √(5gL) = √(5×10×0.5) = 5 m/s.\nMomentum conservation (bullet recoils): 0.010 × v = 1 × 5 − 0.010 × 100 = 4.\nSo v = 4/0.010 = 400 m/s."},
{"y":"JEE Main 2021 · 16 Mar · Shift 1","tp":"pwc","st":"Collisions in two dimensions","q":"A ball of mass 10 kg moving with a velocity 10√3 m s⁻¹ along X-axis, hits another ball of mass 20 kg which is at rest. After collision, the first ball comes to rest and the second one disintegrates into two equal pieces. One of the pieces starts moving along Y-axis at a speed of 10 m s⁻¹. The second piece starts moving at a speed of 20 m s⁻¹ at an angle θ (degree) with respect to the X-axis. The configuration of pieces after collision is shown in the figure. The value of θ to the nearest integer is ____.","fig":{"w":340,"h":190,"alt":"After the collision one piece moves up along the Y axis at 10 m/s and the other piece moves down and to the right at 20 m/s at angle theta below the X axis.","d":[["l",30,100,310,100,"a"],["l",140,170,140,20,"a"],["t",312,116,"X axis","se"],["t",148,22,"Y","s"],["t",230,20,"After collision","s"],["l",140,100,140,40,"Ba"],["t",148,56,"10 m/s","s"],["l",140,100,209.3,140,"Ba"],["t",207.3,154,"20 m/s","s"],["t",170,116,"θ","s"]]},"n":30,"s":"Each piece has mass 10 kg. Initial momentum is 10 × 10√3 = 100√3 kg m/s along X.\nAlong X after collision: 10 × 20 cosθ = 100√3, so cosθ = √3/2.\nCheck along Y: 10 × 10 − 10 × 20 sinθ = 100 − 200 × ½ = 0, which is correct.\nSo θ = 30°."},
{"y":"JEE Main 2021 · 18 Mar · Shift 1","tp":"pwc","st":"Collisions in two dimensions","q":"A ball of mass 10 kg moving with a velocity 10√3 m/s along the x-axis, hits another ball of mass 20 kg which is at rest. After the collision, first ball comes to rest while the second ball disintegrates into two equal pieces. One piece starts moving along y-axis with a speed of 10 m/s. The second piece starts moving at an angle of 30° with respect to the x-axis. The velocity of the ball moving at 30° with x-axis is x m/s. The configuration of pieces after collision is shown in the figure below. The value of x to the nearest integer is ____.","fig":{"w":340,"h":190,"alt":"After the collision piece 1 moves up the y axis at 10 m/s and piece 2 moves down and to the right at 30 degrees below the x axis with speed x.","d":[["l",30,100,310,100,"a"],["l",140,170,140,20,"a"],["t",312,116,"x-axis","se"],["t",148,22,"y-axis","s"],["l",140,100,140,40,"Ba"],["t",148,48,"Piece 1","s"],["t",148,62,"v₁ = 10 m/s","s"],["l",140,100,217.9,145,"Ba"],["t",215.9,159,"v₂","s"],["t",172,116,"30°","s"]]},"n":20,"s":"Each piece has mass 10 kg. Initial momentum along x = 10 × 10√3 = 100√3 kg m/s.\nAlong x after collision: 10 × x cos30° = 100√3, so x × (√3/2) = 10√3 and x = 20 m/s.\nCheck along y: 10 × 10 − 10 × 20 × sin30° = 100 − 100 = 0, as required.\nSo x = 20."},
{"y":"JEE Main 2020 · 2 Sep · Shift 2","tp":"pwc","st":"Collisions in two dimensions","q":"A particle of mass m is moving along the x-axis with initial velocity u î. It collides elastically with a particle of mass 10 m at rest and then moves with half its initial kinetic energy (see figure). If sinθ₁ = √n sinθ₂ then value of n is ____.","fig":{"w":340,"h":160,"alt":"A particle m moving right with velocity u hits a particle 10m at rest; afterwards m moves up-right at angle theta1 and 10m moves down-right at angle theta2 from the dashed horizontal line.","d":[["l",40,80,170,80,"a"],["c",40,80,3,"F"],["t",40,66,"m","m"],["t",100,98,"u î","ms"],["c",170,80,4,"F"],["t",170,100,"10 m","ms"],["l",172,80,300,80,"d"],["l",170,80,246,28,"a"],["t",250,24,"m",""],["l",170,80,262,98,"a"],["t",262,118,"10m","m"],["t",216,70,"θ₁","s"],["t",222,96,"θ₂","s"]]},"n":10,"s":"After the collision the particle m has half its kinetic energy: ½mv₁² = ½(½mu²), so v₁ = u/√2.\nElastic collision: ½mu² = ½mv₁² + ½(10m)v₂², so 10v₂² = u²/2 and v₂ = u/√20.\nMomentum along y: m v₁ sinθ₁ = 10m v₂ sinθ₂, so sinθ₁/sinθ₂ = 10v₂/v₁ = 10 × (1/√20) × √2 = 10/√10 = √10.\nSo n = 10."},
{"y":"JEE Main 2020 · 6 Sep · Shift 1","tp":"pwc","st":"Inelastic collisions and coefficient of restitution","q":"Two bodies of the same mass are moving with the same speed, but in different directions in a plane. They have a completely inelastic collision and move together thereafter with a final speed which is half of their initial speed. The angle between the initial velocities of the two bodies (in degree) is ____.","n":120,"s":"Let each body have mass m and speed v. After sticking, the speed is v/2 and the mass is 2m, so the momentum is 2m × v/2 = mv.\nMomentum is a vector: |p⃗₁ + p⃗₂|² = (mv)² + (mv)² + 2(mv)(mv)cosφ = (mv)².\nSo 2 + 2cosφ = 1, cosφ = −½.\nφ = 120°."},
{"y":"JEE Main 2020 · 8 Jan · Shift 1","tp":"pwc","st":"Collisions in two dimensions","q":"A body A, of mass m = 0.1 kg has an initial velocity of 3î m s⁻¹. It collides elastically with another body, B of the same mass which has an initial velocity of 5ĵ m s⁻¹. After collision, A moves with a velocity v⃗ = 4(î + ĵ). The energy of B after collision is written as {x;10} J. The value of x is ____.","n":1,"s":"Momentum is conserved (same mass): 3î + 5ĵ = 4î + 4ĵ + v⃗_B, so v⃗_B = −î + ĵ m/s.\nSpeed² of B = 1 + 1 = 2, so KE of B = ½ × 0.1 × 2 = 0.1 J = {1;10} J.\nCheck energy: initial ½×0.1×(9+25) = 1.7 J; final ½×0.1×32 + 0.1 = 1.6 + 0.1 = 1.7 J, which confirms the collision is elastic.\nSo x = 1."},
{"y":"JEE Advanced 2013","tp":"pwv","st":"Vertical circle conditions","q":"A bob of mass m, suspended by a string of length l₁ is given a minimum velocity required to complete a full circle in the vertical plane. At the highest point, it collides elastically with another bob of mass m suspended by a string of length l₂, which is initially at rest. Both the strings are mass-less and inextensible. If the second bob, after collision acquires the minimum speed required to complete a full circle in the vertical plane, the ratio {l₁;l₂} is ____.","n":5,"s":"At the highest point of its circle the first bob has the minimum speed v = √(g l₁).\nIt hits the second bob (equal mass, at rest) elastically, so they exchange velocities: the second bob gets √(g l₁) while the first stops.\nFor the second bob to just complete its circle, the speed it gets at its lowest point must be √(5 g l₂).\nSo g l₁ = 5 g l₂ and l₁/l₂ = 5."},
{"y":"IIT-JEE 2009","tp":"pwc","st":"Elastic collisions","q":"Three objects A, B and C are kept in a straight line on a frictionless horizontal surface. These have masses m, 2m and m, respectively. The object A moves towards B with a speed 9 m/s and makes an elastic collision with it. Thereafter, B makes completely inelastic collision with C. All motions occur on the same straight line. Find the final speed (in m/s) of the object C.","n":4,"s":"Elastic collision of A (m, 9 m/s) with B (2m, at rest): v_B = {2m;m+2m} × 9 = 6 m/s. A rebounds at 3 m/s, away from B and C.\nB (2m, 6 m/s) now sticks to C (m, at rest): (2m + m)V = 2m × 6.\nV = 12m/3m = 4 m/s."},
{"y":"IIT-JEE 2008","tp":"pwc","st":"Inelastic collisions and coefficient of restitution","q":"A small block of mass M moves on a frictionless surface of an inclined plane, as shown in the figure. The angle of the incline suddenly changes from 60° to 30° at point B. The block is initially at rest at point A. Assume that collisions between the block and the incline are totally inelastic (g = 10 m s⁻²).\nThe speed of the block at point B immediately after it strikes the second incline is","fig":{"w":340,"h":250,"alt":"Block at A on a 60 degree incline that meets a 30 degree incline at B. The horizontal extents are root 3 m for the first incline and 3 root 3 m for the second, ending at C.","d":[["l",40,210,250,210,"B"],["l",40,30,92,120,"B"],["l",92,120,248,210,"B"],["l",92,120,92,210,"d"],["l",40,120,92,120,"d"],["l",40,120,40,225,"d"],["r",44,18,14,12,"f"],["t",37,24,"A","e"],["t",58,98,"M","s"],["t",100,118,"B",""],["t",252,214,"C",""],["t",72,114,"60°","se"],["t",226,206,"30°","se"],["l",40,224,92,224,"b"],["t",66,236,"√3 m","ms"],["l",92,224,248,224,"b"],["t",170,236,"3√3 m","ms"]]},"o":["√60 m/s","√45 m/s","√30 m/s","√15 m/s"],"c":1,"s":"Geometry: first incline has horizontal extent √3 m at 60°, so its height is √3 × tan60° = 3 m. The second has horizontal extent 3√3 m at 30°, so its height is 3√3 × tan30° = 3 m.\nSpeed at B just before the collision: v² = 2gh = 2 × 10 × 3 = 60, so v = √60 m/s, directed 60° below horizontal.\nThe second incline is 30° below horizontal, so this velocity makes 30° with it. In a totally inelastic collision the component perpendicular to the incline is lost; only the component along it survives.\nSpeed after = √60 cos30° = √60 × {√3;2} = √45 m/s. Option (b)."},
{"y":"IIT-JEE 2008","tp":"pwc","st":"Inelastic collisions and coefficient of restitution","q":"A small block of mass M moves on a frictionless surface of an inclined plane, as shown in the figure. The angle of the incline suddenly changes from 60° to 30° at point B. The block is initially at rest at point A. Assume that collisions between the block and the incline are totally inelastic (g = 10 m s⁻²).\nThe speed of the block at point C, immediately before it strikes the second incline is","fig":{"w":340,"h":250,"alt":"Block at A on a 60 degree incline that meets a 30 degree incline at B. The horizontal extents are root 3 m for the first incline and 3 root 3 m for the second, ending at C.","d":[["l",40,210,250,210,"B"],["l",40,30,92,120,"B"],["l",92,120,248,210,"B"],["l",92,120,92,210,"d"],["l",40,120,92,120,"d"],["l",40,120,40,225,"d"],["r",44,18,14,12,"f"],["t",37,24,"A","e"],["t",58,98,"M","s"],["t",100,118,"B",""],["t",252,214,"C",""],["t",72,114,"60°","se"],["t",226,206,"30°","se"],["l",40,224,92,224,"b"],["t",66,236,"√3 m","ms"],["l",92,224,248,224,"b"],["t",170,236,"3√3 m","ms"]]},"o":["√120 m/s","√105 m/s","√90 m/s","√75 m/s"],"c":1,"s":"Geometry: first incline has horizontal extent √3 m at 60°, so its height is √3 × tan60° = 3 m. The second has horizontal extent 3√3 m at 30°, so its height is 3√3 × tan30° = 3 m.\nSpeed just after the collision at B (from the previous question): v² = 45 m²/s².\nFrom B to C the block slides down a further 3 m on a frictionless incline: v_C² = 45 + 2 × 10 × 3 = 105.\nSo v_C = √105 m/s. Option (b)."},
{"y":"IIT-JEE 2008","tp":"pwc","st":"Elastic collisions","q":"A small block of mass M moves on a frictionless surface of an inclined plane, as shown in the figure. The angle of the incline suddenly changes from 60° to 30° at point B. The block is initially at rest at point A. Assume that collisions between the block and the incline are totally inelastic (g = 10 m s⁻²).\nIf the collision between the block and the incline is completely elastic, then the vertical (upward) component of the velocity of the block at point B, immediately after it strikes the second incline is","fig":{"w":340,"h":250,"alt":"Block at A on a 60 degree incline that meets a 30 degree incline at B. The horizontal extents are root 3 m for the first incline and 3 root 3 m for the second, ending at C.","d":[["l",40,210,250,210,"B"],["l",40,30,92,120,"B"],["l",92,120,248,210,"B"],["l",92,120,92,210,"d"],["l",40,120,92,120,"d"],["l",40,120,40,225,"d"],["r",44,18,14,12,"f"],["t",37,24,"A","e"],["t",58,98,"M","s"],["t",100,118,"B",""],["t",252,214,"C",""],["t",72,114,"60°","se"],["t",226,206,"30°","se"],["l",40,224,92,224,"b"],["t",66,236,"√3 m","ms"],["l",92,224,248,224,"b"],["t",170,236,"3√3 m","ms"]]},"o":["√30 m/s","√15 m/s","0","−√15 m/s"],"c":2,"s":"Geometry: first incline has horizontal extent √3 m at 60°, so its height is √3 × tan60° = 3 m. The second has horizontal extent 3√3 m at 30°, so its height is 3√3 × tan30° = 3 m.\nSpeed at B before collision is √60 m/s, directed 60° below the horizontal. The second incline is 30° below the horizontal, so the velocity makes 30° with the incline.\nIn an elastic collision the component along the incline is unchanged and the perpendicular component reverses. So the velocity is reflected and makes 30° on the other side of the incline.\nThe incline direction is −30° (below horizontal); the reflected velocity is turned 30° away from it, at −30° + 30° = 0°, i.e. horizontal. So the vertical component is 0. Option (c)."},
{"y":"JEE Main 2025 · 29 Jan · Shift 2","tp":"pwc","st":"Statements, matching and subjective","q":"Given below are two statements. One is labelled as Assertion (A) and the other is labelled as Reason (R).\nAssertion (A): Three identical spheres of same mass undergo one dimensional motion as shown in figure with initial velocities v_A = 5 m/s, v_B = 2 m/s, v_C = 4 m/s. If we wait sufficiently long for elastic collision to happen, then v_A = 4 m/s, v_B = 2 m/s, v_C = 5 m/s will be the final velocities.\nReason (R): In an elastic collision between identical masses, two objects exchange their velocities.\nIn the light of the above statements, choose the correct answer from the options given below:","fig":{"w":340,"h":120,"alt":"Three identical spheres A, B and C in a row all moving to the right with speeds 5, 2 and 4 m/s.","d":[["c",70,60,14],["c",170,60,14],["c",270,60,14],["t",70,30,"A","ms"],["t",170,30,"B","ms"],["t",270,30,"C","ms"],["l",88,60,120,60,"a"],["l",188,60,220,60,"a"],["l",288,60,320,60,"a"],["t",70,100,"v_A = 5","ms"],["t",170,100,"v_B = 2","ms"],["t",270,100,"v_C = 4","ms"]]},"o":["(A) is false but (R) is true","Both (A) and (R) are true and (R) is the correct explanation of (A)","Both (A) and (R) are true but (R) is not the correct explanation of (A)","(A) is true but (R) is false"],"c":0,"s":"Reason (R) is true: identical masses in an elastic head-on collision exchange velocities.\nA (5 m/s) catches B (2 m/s): they exchange, so A = 2 and B = 5. Then B (5 m/s) catches C (4 m/s): they exchange, so B = 4 and C = 5.\nNow A = 2 < B = 4 < C = 5, so no more collisions happen.\nFinal velocities are v_A = 2, v_B = 4, v_C = 5 m/s, not (4, 2, 5). So (A) is false but (R) is true. Option (a)."},
{"y":"JEE Main 2021 · 26 Feb · Shift 1","tp":"pwc","st":"Statements, matching and subjective","q":"Given below are two statements: one is labelled as Assertion A and the other is labelled as Reason R.\nAssertion A: Body P having mass M moving with speed u has head-on collision elastically with another body Q having mass m initially at rest. If m << M, body Q will have a maximum speed equal to 2u after collision.\nReason R: During elastic collision, the momentum and kinetic energy are both conserved.\nIn the light of the above statements, choose the most appropriate answer from the options given below:","o":["Both A and R are true but R is not the correct explanation of A.","A is correct but R is not correct.","Both A and R are correct and R is the correct explanation of A.","A is not correct but R is correct."],"c":2,"s":"For an elastic head-on collision with Q at rest: v_Q = {2M;M+m}u.\nIf m << M, then M + m ≈ M, so v_Q ≈ 2u. This is the maximum possible speed, so A is correct.\nThis result is derived by using exactly the two conservation laws (momentum and kinetic energy) given in R, so R is correct and is the explanation of A. Option (c)."},
{"y":"JEE Main 2013","tp":"pwc","st":"Statements, matching and subjective","q":"This question has Statement-I and Statement-II. Of the four choices given after the Statements, choose the one that best describes the two Statements.\nStatement-I: A point particle of mass m moving with speed v collides with stationary point particle of mass M. If the maximum energy loss possible is given as h(½mv²) then h = {m;M+m}.\nStatement-II: Maximum energy loss occurs when the particles get stuck together as a result of the collision.","o":["Statement-I is false, Statement-II is true.","Statement-I is true, Statement-II is true, Statement-II is a correct explanation of Statement-I.","Statement-I is true, Statement-II is true, Statement-II is not a correct explanation of statement-I.","Statement-I is true, Statement-II is false."],"c":0,"s":"Statement-II is true: the loss of kinetic energy is greatest in a perfectly inelastic collision (particles stick).\nThen the common speed is V = mv/(M+m).\nLoss = ½mv² − ½(M+m)V² = ½mv² − {m²v²;2(M+m)} = ½mv² × {M;M+m}.\nSo h = M/(M+m), not m/(M+m). Statement-I is false. Option (a)."},
{"y":"AIEEE 2010","tp":"pwc","st":"Statements, matching and subjective","q":"Statement-I: Two particles moving in the same direction do not lose all their energy in a completely inelastic collision.\nStatement-II: Principle of conservation of momentum holds true for all kinds of collisions.","o":["Statement-I is true, Statement-II is false.","Statement-I is true, Statement-II is true; Statement-II is the correct explanation of Statement-I.","Statement-I is true, Statement-II is true; Statement-II is not the correct explanation of Statement-I.","Statement-I is false, Statement-II is true."],"c":1,"s":"Statement-II is true: momentum is conserved in every collision (elastic or inelastic), because there is no external force on the system.\nTwo particles moving in the same direction have a non-zero total momentum. After a completely inelastic collision they move together, and momentum conservation says this combined motion still has the same non-zero momentum. So they cannot be at rest and their kinetic energy cannot be zero.\nSo Statement-I is true and Statement-II explains it. Option (b)."}
];
